DO $pv456_release$
DECLARE
 release_name text := 'perfect_video_modules_4_6_clear_practice_20261004';
 specs jsonb := $pv456_payload$[{"module":"s02-m04","lesson":"pv04-01","source_hash":"dd95a996ad4622f254aae9ca5482cd65","objective":"Ще подредиш прост кадър до прозорец и ще провериш дали лицето или предметът се виждат ясно. Ще разбереш как бялата и черната повърхност променят сянката и кога облакът налага нова проба. В края ще имаш три кратки записа, които можеш да сравниш при еднакво кадриране. За първия опит стигат наличен телефон, прозорец и безопасно закрепен картон.","hook":"Прозорецът изглежда безплатен, докато облак не премести контраста по средата на интервюто.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще подредиш прост кадър до прозорец и ще провериш дали лицето или предметът се виждат ясно. Ще разбереш как бялата и черната повърхност променят сянката и кога облакът налага нова проба. В края ще имаш три кратки записа, които можеш да сравниш при еднакво кадриране. За първия опит стигат наличен телефон, прозорец и безопасно закрепен картон.","deliverable":"Сложи един предмет на маса до прозорец. Запиши по 10 секунди без картон, с бял и с черен картон. Запази еднакви позиция и настройки, доколкото устройството позволява. При смяна на слънцето започни сравнението отново.","check":"Предметът и важният надпис се виждат; има детайл в светлите места. Вариантите се различават по една променена причина. Автоматична смяна на яркост или цвят се отбелязва като ограничение."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Прозорецът изглежда безплатен, докато облак не премести контраста по средата на интервюто."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Експозиция (експонация) — колко светло е записано изображението. Баланс на бялото — настройката, чрез която камерата определя как изглеждат неутралните цветове. Отражател — светла повърхност, която връща част от светлината. Дифузия — разсейване на светлината с подходящ материал, което може да омекоти сянката. Замразен кадър — пауза върху едно изображение от видеото.\n\nГледай къде пада светлината върху лицето и фона, вместо да преследваш един задължителен ъгъл.\n\nГолям видим източник дава по-плавен ръб на сянката. Разстоянието и посоката променят съотношението лице–фон; бял картон връща светлина, черен картон поглъща отражения."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Снимай 10 секунди при реалното време на деня и заключи експозиция и баланс на бялото. Изключи лампата на тавана само ако смесеният цвят пречи; оставена като умишлен фон, тя може да работи. Ако слънцето удря директно, тънък дифузен материал омекотява светлината, но не използвай плат до горещ източник. Запиши как ще реагираш, когато небето се смени.\n\nГраница на решението: Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Избери фон и позиция според светлината на лицето.\n2. Провери отраженията и сложи бял или черен картон според нуждата.\n3. Заключи наличните настройки, ако устройството позволява; заснеми кратък тест и запиши ограниченията.\n4. Повтори теста след промяна на облаците и сравни лицето."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Пекарка разказва за работата си до западен прозорец. В първия дубъл облак прави лицето меко; след пет минути слънцето реже половината кадър. Имаш още три въпроса.\n\nРешение: Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор.\n\nКакво да провериш: Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор. Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон.","label":"Как го поправяш"},"before":{"text":"Продължаваш със същите настройки, а после се опитваш да възстановиш изгоряла кожа в монтажа.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Сложи един предмет на маса до прозорец. Запиши по 10 секунди без картон, с бял и с черен картон. Запази еднакви позиция и настройки, доколкото устройството позволява. При смяна на слънцето започни сравнението отново.\n\nПровери резултата: Предметът и важният надпис се виждат; има детайл в светлите места. Вариантите се различават по една променена причина. Автоматична смяна на яркост или цвят се отбелязва като ограничение.\n\nПримерна работна бележка: А: предметът е четим, но сянката е тъмна. Б: белият картон връща светлина и надписът се вижда по-лесно. В: черният картон усилва сянката; избирам го само ако важният детайл остава видим. Това са примерни наблюдения — при твоя прозорец резултатът може да е различен.\n\nАко не е изпълнено: Ако телефонът сменя яркостта между вариантите, повтори с заключване, когато го поддържа. Ако не го поддържа, запиши ограничението и сравнявай предпазливо. Не приписвай всяка разлика на картона."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Първи кадър сутрин и втори следобед, като запазвам картона."},{"id":"b","label":"Единият вариант е по-светъл заради новата автоматична експонация."},{"id":"c","label":"Същият кадър и светлина, като променям само картона."}],"question":"Кое сравнение показва най-ясно ефекта на отражателя?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Същият кадър и светлина, като променям само картона. Предметът и важният надпис се виждат; има детайл в светлите места. Вариантите се различават по една променена причина. Автоматична смяна на яркост или цвят се отбелязва като ограничение."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Пекарка разказва за работата си до западен прозорец. В първия дубъл облак прави лицето меко; след пет минути слънцето реже половината кадър. Имаш още три въпроса.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор."},{"id":"b","label":"Намалявам яркостта на целия кадър, без да променя директното слънце върху човека."},{"id":"c","label":"Запазвам мястото и планирам една обща корекция за всички отговори."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор.\n\nКакво да провериш: Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Пусни автоматичен баланс на бялото и се надявай той да изравни всички дубъли."},{"id":"b","label":"Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Сложи един предмет на маса до прозорец. Запиши по 10 секунди без картон, с бял и с черен картон. Запази еднакви позиция и настройки, доколкото устройството позволява. При смяна на слънцето започни сравнението отново.","takeaways":["Гледай къде пада светлината върху лицето и фона, вместо да преследваш един задължителен ъгъл.","Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор.","Провери: Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Заключи наличните настройки, ако устройството позволява; заснеми кратък тест и запиши ограниченията."},{"id":"s1","text":"Избери фон и позиция според светлината на лицето."},{"id":"s4","text":"Повтори теста след промяна на облаците и сравни лицето."},{"id":"s2","text":"Провери отраженията и сложи бял или черен картон според нуждата."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Избери фон и позиция според светлината на лицето. → Провери отраженията и сложи бял или черен картон според нуждата. → Заключи наличните настройки, ако устройството позволява; заснеми кратък тест и запиши ограниченията. → Повтори теста след промяна на облаците и сравни лицето."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Прозорецът е зад говорителя, а стаята е тъмна; местене на целия екип е невъзможно.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Промени посоката на камерата или използвай налично отражение и измери лицето спрямо фона; ако няма достатъчно светлина, смени мястото или времето."},{"id":"b","label":"Продължаваш със същите настройки, а после се опитваш да възстановиш изгоряла кожа в монтажа."},{"id":"c","label":"Пусни автоматичен баланс на бялото и се надявай той да изравни всички дубъли."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Промени посоката на камерата или използвай налично отражение и измери лицето спрямо фона; ако няма достатъчно светлина, смени мястото или времето. Предметът и важният надпис се виждат; има детайл в светлите места. Вариантите се различават по една променена причина. Автоматична смяна на яркост или цвят се отбелязва като ограничение."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Пробата проверява светлината. Тя не доказва дали зрителят ще се довери на говорителя или ще купи продукта."}}]},{"module":"s02-m04","lesson":"pv04-02","source_hash":"b4db2a6dc637dc2d05b9b5c272b89ebd","objective":"Ще избираш осветление според конкретния кадър и мястото. Ще проверяваш дали лампата помага на лицето или надписа, дали не създава отражение и дали стои безопасно. Резултатът е изпълнима установка с един основен източник. Покупката не е условие: можеш първо да провериш същия принцип с прозорец.","hook":"Пълна чанта с лампи не помага, ако на място няма място за безопасен статив.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще избираш осветление според конкретния кадър и мястото. Ще проверяваш дали лампата помага на лицето или надписа, дали не създава отражение и дали стои безопасно. Резултатът е изпълнима установка с един основен източник. Покупката не е условие: можеш първо да провериш същия принцип с прозорец.","deliverable":"Избери безопасно място за един източник и предмет с надпис. Запиши 10 секунди. Промени само ъгъла и повтори. Не закрепвай домашни материали към нагряващи лампи.","check":"Надписът се чете, няма пречещо отражение или видими ленти в пробата, а източникът и кабелите не блокират пътя. Това важи за проверените настройки."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Пълна чанта с лампи не помага, ако на място няма място за безопасен статив."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Модификатор — принадлежност, която променя разпространението на светлината. Трептене — промяна в светлината, която записът може да покаже като пулсации или ленти. Кадрова честота — броят кадри за секунда.\n\nПърво избери позиция на светлината; купувай мощност и модификатори едва след тест на реалната сцена.\n\nЕдна стабилна светлина, мек модификатор, надежден статив, захранване и черен или бял картон решават повече задачи от случаен набор RGB панели. Приеми ограничението на помещението и дистанцията до човека като част от решението."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"На малък снимачен терен окабеляването и товарът на стойката са производствен риск. Провери маркировките и инструкциите на производителя за захранване, монтаж и разстояние до плат или перде. Нискочестотното трептене на осветлението може да даде ленти или пулсации при конкретен затвор; виж го във видео проба при същата кадрова честота, а не само с очи.\n\nГраница на решението: Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Опиши сцена, размер на помещение и нужната площ светлина.\n2. Разположи една лампа и безопасен статив извън пътя на хората.\n3. Запиши проба със същите fps и затвор като проекта.\n4. Провери сенки, отблясъци, трептене и кабели преди снимки."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Малък магазин иска интервю след затваряне. Пространството е тясно, има стъклена витрина и пътека към изхода; разполагаш с една лампа.\n\nРешение: Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор.\n\nКакво да провериш: В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор. В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно.","label":"Как го поправяш"},"before":{"text":"Поставяш лампата на пътеката, гониш „кинематографичен“ контур и пропускаш отблясък във витрината.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Избери безопасно място за един източник и предмет с надпис. Запиши 10 секунди. Промени само ъгъла и повтори. Не закрепвай домашни материали към нагряващи лампи.\n\nПровери резултата: Надписът се чете, няма пречещо отражение или видими ленти в пробата, а източникът и кабелите не блокират пътя. Това важи за проверените настройки.\n\nПримерна работна бележка: В първата проба лампата се отразява върху надписа. Във втората е преместена встрани и надписът е четим. Записвам позицията и използваните настройки; проверявам, че стативът и кабелът не са в прохода.\n\nАко не е изпълнено: Ако отражението остава, промени ъгъла на източника или предмета и запиши нова проба. При трептене провери съвместимите настройки и режимите на лампата; не приемай липса на ленти в един кадър за гаранция за всички режими."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Дали комплектът е по-мощен от този на друг снимачен екип."},{"id":"b","label":"Кой конкретен проблем остава в пробата и дали новият източник го решава."},{"id":"c","label":"Дали цветът на светлината изглежда ефектно върху празната стена."}],"question":"Какво трябва да установиш преди избор на допълнителна лампа?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Кой конкретен проблем остава в пробата и дали новият източник го решава. Надписът се чете, няма пречещо отражение или видими ленти в пробата, а източникът и кабелите не блокират пътя. Това важи за проверените настройки."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Малък магазин иска интервю след затваряне. Пространството е тясно, има стъклена витрина и пътека към изхода; разполагаш с една лампа.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Оставям стойката на пътеката и снимам само докато няма посетители."},{"id":"b","label":"Усилвам лампата, без да проверя отражението в стъклената витрина."},{"id":"c","label":"Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор.\n\nКакво да провериш: В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Вдигни ISO и поправи отблясъците с цветна корекция."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Избери безопасно място за един източник и предмет с надпис. Запиши 10 секунди. Промени само ъгъла и повтори. Не закрепвай домашни материали към нагряващи лампи.","takeaways":["Първо избери позиция на светлината; купувай мощност и модификатори едва след тест на реалната сцена.","Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор.","Провери: В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Запиши проба със същите fps и затвор като проекта."},{"id":"s1","text":"Опиши сцена, размер на помещение и нужната площ светлина."},{"id":"s4","text":"Провери сенки, отблясъци, трептене и кабели преди снимки."},{"id":"s2","text":"Разположи една лампа и безопасен статив извън пътя на хората."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Опиши сцена, размер на помещение и нужната площ светлина. → Разположи една лампа и безопасен статив извън пътя на хората. → Запиши проба със същите fps и затвор като проекта. → Провери сенки, отблясъци, трептене и кабели преди снимки."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Контактът на място е далече и клиентът иска да смениш позицията на масата.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Поставяш лампата на пътеката, гониш „кинематографичен“ контур и пропускаш отблясък във витрината."},{"id":"b","label":"Вдигни ISO и поправи отблясъците с цветна корекция."},{"id":"c","label":"Преизчисли маршрута и захранването; ако кабелът трябва да пресече проход, промени плана и избери безопасна позиция."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Преизчисли маршрута и захранването; ако кабелът трябва да пресече проход, промени плана и избери безопасна позиция. Надписът се чете, няма пречещо отражение или видими ленти в пробата, а източникът и кабелите не блокират пътя. Това важи за проверените настройки."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"В този урок практическата стойност е видима информация и изпълнима работа. Не се изисква конкретна марка или цена на техника."}}]},{"module":"s02-m04","lesson":"pv04-03","source_hash":"5288883943f9da5d913472d448a64c8b","objective":"Ще можеш да върнеш форма на лице или предмет, когато светлите стени връщат прекалено много светлина. Ще сравняваш кадър с и без черен картон и ще спираш промяната, когато важният детайл започне да изчезва. Няма да използваш силната сянка като оправдание за нечетим продукт.","hook":"В бяла стая отраженията могат да направят сянката прекалено слаба. Първо провери какво връщат стените към предмета.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще можеш да върнеш форма на лице или предмет, когато светлите стени връщат прекалено много светлина. Ще сравняваш кадър с и без черен картон и ще спираш промяната, когато важният детайл започне да изчезва. Няма да използваш силната сянка като оправдание за нечетим продукт.","deliverable":"До прозорец заснеми матов предмет без черен картон, после с картон от страната на сянката. Направи трети вариант с по-далечен картон. Не сменяй кадрирането между записите.","check":"Формата се различава, а надписът или важният детайл остава видим. Ако цялата сенчеста страна се загуби, отдалечи картона или се върни към по-светлия вариант."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"В бяла стая отраженията могат да направят сянката прекалено слаба. Първо провери какво връщат стените към предмета."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Черно знаме — матова черна плоскост, която ограничава светлината. Отрицателно запълване — намаляване на отразената светлина от определена страна. Контраст — видимата разлика между светло и тъмно.\n\nЧерна повърхност от страната на сянката спира част от върнатата светлина и прави формата видима.\n\nПостави матов черен картон извън кадъра; мести го и гледай как се изменя сенчестата страна. Това не е „намаляване на експозицията“ на цялата сцена, а контрол на отражението в определена посока."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Гланцирана или твърде малка повърхност може да не помогне. Отдръпни картона постепенно, докато окото в сянката остане четимо. Провери фона и дрехите: ако те потъват в черно, добави разстояние или промени ъгъла на ключовата светлина, вместо да стискаш контраста в монтажа.\n\nГраница на решението: Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Заключи експонация, баланс и основен кадър.\n2. Сравни кадъра без черна повърхност и с нея от страната на сянката.\n3. Мести картона, докато лицето запази нужния детайл.\n4. Провери очите и черната дреха на реален екран."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Говорител с тъмно сако стои в бял офис. Лицето е плоско, но сакото лесно се слива със стената, когато добавиш черен картон.\n\nРешение: Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно.\n\nКакво да провериш: На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно. На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен.","label":"Как го поправяш"},"before":{"text":"Слагаш голяма черна плоскост до самото лице и приемаш изгубеното око за „драматичен стил“.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"До прозорец заснеми матов предмет без черен картон, после с картон от страната на сянката. Направи трети вариант с по-далечен картон. Не сменяй кадрирането между записите.\n\nПровери резултата: Формата се различава, а надписът или важният детайл остава видим. Ако цялата сенчеста страна се загуби, отдалечи картона или се върни към по-светлия вариант.\n\nПримерна работна бележка: Без картон формата е плоска. Близкият черен картон прави ръба по-ясен, но скрива част от надписа. По-далечният дава умерена сянка и запазва четливостта; за този предмет избирам него.\n\nАко не е изпълнено: Ако губиш важната информация, отдалечи или намали черната повърхност. При гланциран предмет отделно провери отраженията — те могат да пречат, дори сянката да е добра."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Намалява част от отразената светлина от тази посока."},{"id":"b","label":"Намалява еднакво яркостта на всички предмети в кадъра."},{"id":"c","label":"Добавя светлина към предмета, като променя цвета ѝ."}],"question":"Какво действително променя черният картон до сенчестата страна?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Намалява част от отразената светлина от тази посока. Формата се различава, а надписът или важният детайл остава видим. Ако цялата сенчеста страна се загуби, отдалечи картона или се върни към по-светлия вариант."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Говорител с тъмно сако стои в бял офис. Лицето е плоско, но сакото лесно се слива със стената, когато добавиш черен картон.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Увеличавам контраста в редактора, без да проверя дали сенчестото око е записано."},{"id":"b","label":"Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно."},{"id":"c","label":"Приближавам още черната плоскост, защото по-дълбокото черно изглежда по-изразително."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно.\n\nКакво да провериш: На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Усили черния цвят в цялата картина и ще получиш същия локален ефект."},{"id":"c","label":"Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"До прозорец заснеми матов предмет без черен картон, после с картон от страната на сянката. Направи трети вариант с по-далечен картон. Не сменяй кадрирането между записите.","takeaways":["Черна повърхност от страната на сянката спира част от върнатата светлина и прави формата видима.","Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно.","Провери: На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Мести картона, докато лицето запази нужния детайл."},{"id":"s1","text":"Заключи експонация, баланс и основен кадър."},{"id":"s4","text":"Провери очите и черната дреха на реален екран."},{"id":"s2","text":"Сравни кадъра без черна повърхност и с нея от страната на сянката."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Заключи експонация, баланс и основен кадър. → Сравни кадъра без черна повърхност и с нея от страната на сянката. → Мести картона, докато лицето запази нужния детайл. → Провери очите и черната дреха на реален екран."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: След това преместваш същата установка в малко тъмно помещение.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Усили черния цвят в цялата картина и ще получиш същия локален ефект."},{"id":"b","label":"Първо измери дали има достатъчно светлина върху лицето; използвай отрицателно запълване само ако има излишно отражение."},{"id":"c","label":"Слагаш голяма черна плоскост до самото лице и приемаш изгубеното око за „драматичен стил“."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Първо измери дали има достатъчно светлина върху лицето; използвай отрицателно запълване само ако има излишно отражение. Формата се различава, а надписът или важният детайл остава видим. Ако цялата сенчеста страна се загуби, отдалечи картона или се върни към по-светлия вариант."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Умереният или силен контраст е избор за разказа. Няма една правилна сянка за всички лица, услуги и аудитории."}}]},{"module":"s02-m04","lesson":"pv04-04","source_hash":"0b1662c79880b5468295082230abb36e","objective":"Ще разпознаваш кога човекът се слива с фона и дали допълнителна светлина зад него помага. Ще проверяваш косата, дрехите и целия кадър, а не само красивия светъл ръб. В края ще можеш да запазиш или премахнеш контура според видимата полза.","hook":"Контурът може да отдели рамото, но същата лампа може да измие целия кадър.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще разпознаваш кога човекът се слива с фона и дали допълнителна светлина зад него помага. Ще проверяваш косата, дрехите и целия кадър, а не само красивия светъл ръб. В края ще можеш да запазиш или премахнеш контура според видимата полза.","deliverable":"Ако имаш подходящ безопасен източник, направи три кратки записа: без контур, слаб и по-силен. Без втори източник сравни отделянето чрез промяна на фона; отбележи, че не си изпълнил проба с контурна лампа.","check":"Ръбът помага за отделянето, но пази детайл в косата и дрехата. Светлината не прави широкия план млечен. Ако фонът решава задачата, допълнителната лампа може да отпадне."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Контурът може да отдели рамото, но същата лампа може да измие целия кадър."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Контур — светъл ръб, който отделя предмет или човек от фона. Разлив — светлина извън желаната зона. Отблясък в обектива — светлина, която може да намали контраста на изображението.\n\nПостави контурната светлина зад и встрани от субекта, като гледаш краищата и отблясъка едновременно.\n\nФлаг, решетка или промяна на ъгъла ограничава разлива към обектива. Не осветявай косата и рамото на максимума само защото има отделяне; търси разлика спрямо фона, която помага на читимостта."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Запиши проба с включен и изключен контур. Провери дали бялата риза не губи текстура, дали светлината не реже носа и дали в очилата няма ярко петно. Ако фонът вече дава достатъчен цвят или тонален контраст, допълнителната лампа може да не е нужна. Контурът не заменя правилно осветено лице.\n\nГраница на решението: При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Настрой основния кадър и лицето без контур.\n2. Добави слаба светлина зад рамото и провери отраженията.\n3. Ограничи лъча или промени ъгъла, ако удари обектива.\n4. Сравни A/B на експортирания файл и остави по-ясния вариант."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Снимаш интервю пред тъмни рафтове. Контурът отделя косата, но на широкия план образът става млечен.\n\nРешение: Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне.\n\nКакво да провериш: Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне. Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно.","label":"Как го поправяш"},"before":{"text":"Вдигаш яркостта, докато косата свети в бяло; отблясъкът остава във всяка камера.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Ако имаш подходящ безопасен източник, направи три кратки записа: без контур, слаб и по-силен. Без втори източник сравни отделянето чрез промяна на фона; отбележи, че не си изпълнил проба с контурна лампа.\n\nПровери резултата: Ръбът помага за отделянето, но пази детайл в косата и дрехата. Светлината не прави широкия план млечен. Ако фонът решава задачата, допълнителната лампа може да отпадне.\n\nПримерна работна бележка: Без контур тъмната дреха се слива с фона. Слабият контур отделя рамото и запазва текстурата. Силният прави ръба бял и без детайл; избирам слабия. Ако пробата е само с друг фон, отбелязвам точно това.\n\nАко не е изпълнено: При светъл воал в целия кадър провери дали източникът попада в обектива. Промени безопасно позицията или отслаби лампата и сравни отново. При достатъчно отделяне чрез фон лампата може да отпадне."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Когато светлият ръб е най-ярката част, независимо от облеклото."},{"id":"b","label":"Когато я има в схемата, дори кадърът без нея да е по-четим."},{"id":"c","label":"Когато подобрява отделянето, без да заличава текстура или контраст."}],"question":"Кога контурната лампа заслужава да остане?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Когато подобрява отделянето, без да заличава текстура или контраст. Ръбът помага за отделянето, но пази детайл в косата и дрехата. Светлината не прави широкия план млечен. Ако фонът решава задачата, допълнителната лампа може да отпадне."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Снимаш интервю пред тъмни рафтове. Контурът отделя косата, но на широкия план образът става млечен.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне."},{"id":"b","label":"Намалявам експонацията на всички камери и приемам по-тъмното лице."},{"id":"c","label":"Изрязвам широкия план, без да изясня причината за млечния образ."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне.\n\nКакво да провериш: Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Компенсирай липсващия контур със силно изостряне в монтажа."},{"id":"b","label":"При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Ако имаш подходящ безопасен източник, направи три кратки записа: без контур, слаб и по-силен. Без втори източник сравни отделянето чрез промяна на фона; отбележи, че не си изпълнил проба с контурна лампа.","takeaways":["Постави контурната светлина зад и встрани от субекта, като гледаш краищата и отблясъка едновременно.","Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне.","Провери: Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Ограничи лъча или промени ъгъла, ако удари обектива."},{"id":"s1","text":"Настрой основния кадър и лицето без контур."},{"id":"s4","text":"Сравни A/B на експортирания файл и остави по-ясния вариант."},{"id":"s2","text":"Добави слаба светлина зад рамото и провери отраженията."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Настрой основния кадър и лицето без контур. → Добави слаба светлина зад рамото и провери отраженията. → Ограничи лъча или промени ъгъла, ако удари обектива. → Сравни A/B на експортирания файл и остави по-ясния вариант."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Говорителят сменя тъмното сако с лъскава бяла риза.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Намали или премахни контура; провери дали бялата тъкан запазва детайл и дали широкият кадър не губи черното."},{"id":"b","label":"Вдигаш яркостта, докато косата свети в бяло; отблясъкът остава във всяка камера."},{"id":"c","label":"Компенсирай липсващия контур със силно изостряне в монтажа."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Намали или премахни контура; провери дали бялата тъкан запазва детайл и дали широкият кадър не губи черното. Ръбът помага за отделянето, но пази детайл в косата и дрехата. Светлината не прави широкия план млечен. Ако фонът решава задачата, допълнителната лампа може да отпадне."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Сравняваш записани варианти. Описанието на схема само по себе си не доказва правилно осветен кадър."}}]},{"module":"s02-m04","lesson":"pv04-05","source_hash":"96b6b2ea36624535e29700d7ee63c018","objective":"Ще подреждаш светлината така, че съседните кадри да изглеждат от едно място. Ще можеш да обясниш защо лицето е осветено от определена страна и как видимата лампа или прозорец подкрепя това. Целта е последователна сцена, която не обърква зрителя при смяна на плана.","hook":"В общия план виждаш лампа от едната страна, а при смяна на плана основната сянка необяснимо се обръща. Провери дали светлината остава последователна.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще подреждаш светлината така, че съседните кадри да изглеждат от едно място. Ще можеш да обясниш защо лицето е осветено от определена страна и как видимата лампа или прозорец подкрепя това. Целта е последователна сцена, която не обърква зрителя при смяна на плана.","deliverable":"Заснеми предмет или себе си от две посоки, с видим прозорец или лампа като ориентир. Използвай безопасни налични източници. Сравни посоката на сенките при редуване на кадрите.","check":"Светлината има разбираема посока и при двата плана. Важният обект се вижда, а светлите предмети запазват форма. Втори видим източник може да обясни различието."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"В общия план виждаш лампа от едната страна, а при смяна на плана основната сянка необяснимо се обръща. Провери дали светлината остава последователна."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Мотивирана светлина — осветление с разбираема причина в сцената. Основен източник — светлината, която определя лицето и главната сянка. План и обратен план — два кадъра към различни страни на разговора.\n\nВсяка видима светлина предполага посока. Нека основният източник продължи това, което зрителят вече вижда в сцената.\n\nНощна лампа, прозорец или отворена врата може да е визуално обяснение за светлина извън кадър. Не е задължително практическата лампа сама да осветява лицето; важно е посоката, цветът и яркостта да не си противоречат."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Изключи всички лампи и виж каква светлина идва от мястото. После включвай източник по източник и наблюдавай сенките. Ако фонова лампа изгаря абажура, намали експозицията ѝ или смени крушката, без да потапяш лицето в тъмно. Заключи баланса на бялото и снимай срещуположните планове със същата логика на посоката.\n\nГраница на решението: Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Посочи видимия или предполагаем източник в сцената.\n2. Подреди основната светлина така, че сянката да има логична посока.\n3. Настрой отделно лицето и практическата лампа.\n4. Снимай план и обратен план; провери дали светлината пази една история."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Готвач разказва пред топла настолна лампа, но голям LED осветява лицето от страната, която лампата не може да достигне.\n\nРешение: Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина.\n\nКакво да провериш: И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина. И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл.","label":"Как го поправяш"},"before":{"text":"Добавяш още две цветни лампи и прикриваш несъответствието с оранжев филтър.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Заснеми предмет или себе си от две посоки, с видим прозорец или лампа като ориентир. Използвай безопасни налични източници. Сравни посоката на сенките при редуване на кадрите.\n\nПровери резултата: Светлината има разбираема посока и при двата плана. Важният обект се вижда, а светлите предмети запазват форма. Втори видим източник може да обясни различието.\n\nПримерна работна бележка: В общия план прозорецът е отляво на предмета. Детайлният план запазва тази посока и сянката е последователна. При втори източник отбелязвам откъде идва различието, вместо да го обявя за грешка автоматично.\n\nАко не е изпълнено: Ако при срез светлината необяснимо сменя страна, върни се към позицията на предмета и камерата. Провери и дали действително има втори източник, който обяснява кадъра."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Само лампите, видими в кадър, имат право да осветяват човека."},{"id":"b","label":"Посоката и видът ѝ са убедителни спрямо показаното място."},{"id":"c","label":"Всички източници трябва да бъдат с еднаква яркост."}],"question":"Какво означава светлината да има причина в кадъра?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Посоката и видът ѝ са убедителни спрямо показаното място. Светлината има разбираема посока и при двата плана. Важният обект се вижда, а светлите предмети запазват форма. Втори видим източник може да обясни различието."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Готвач разказва пред топла настолна лампа, но голям LED осветява лицето от страната, която лампата не може да достигне.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Оставям противоречивата посока и добавям общ топъл филтър."},{"id":"b","label":"Изключвам настолната лампа, но запазвам плана, който я представя като основен източник."},{"id":"c","label":"Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина.\n\nКакво да провериш: И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Остави всички източници на максимална яркост, за да няма тъмни участъци."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Заснеми предмет или себе си от две посоки, с видим прозорец или лампа като ориентир. Използвай безопасни налични източници. Сравни посоката на сенките при редуване на кадрите.","takeaways":["Всяка видима светлина предполага посока. Нека основният източник продължи това, което зрителят вече вижда в сцената.","Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина.","Провери: И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Настрой отделно лицето и практическата лампа."},{"id":"s1","text":"Посочи видимия или предполагаем източник в сцената."},{"id":"s4","text":"Снимай план и обратен план; провери дали светлината пази една история."},{"id":"s2","text":"Подреди основната светлина така, че сянката да има логична посока."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Посочи видимия или предполагаем източник в сцената. → Подреди основната светлина така, че сянката да има логична посока. → Настрой отделно лицето и практическата лампа. → Снимай план и обратен план; провери дали светлината пази една история."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Екипът премества разговора по-близо до дневен прозорец.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Добавяш още две цветни лампи и прикриваш несъответствието с оранжев филтър."},{"id":"b","label":"Остави всички източници на максимална яркост, за да няма тъмни участъци."},{"id":"c","label":"Избери водещия източник наново; ако прозорецът вземе сцената, остави настолната лампа като фонов акцент."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Избери водещия източник наново; ако прозорецът вземе сцената, остави настолната лампа като фонов акцент. Светлината има разбираема посока и при двата плана. Важният обект се вижда, а светлите предмети запазват форма. Втори видим източник може да обясни различието."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Светлината може да бъде усилена извън кадър. Това е творческо решение, когато не създава невярна информация за продукта или услугата."}}]},{"module":"s02-m04","lesson":"pv04-06","source_hash":"0b0bb04a5f83acefb804898a9f134e4d","objective":"Ще откриваш защо едната страна на лицето или продукта сменя цвят. Ще избираш водещ източник и ще проверяваш останалите един по един. В края ще имаш сравнение, което показва дали проблемът идва от смесената светлина, а не от нужда от по-силен филтър.","hook":"Едната страна на лицето е под дневна светлина, другата — под жълта стайна лампа. Една обща настройка на бялото може да не реши различието.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще откриваш защо едната страна на лицето или продукта сменя цвят. Ще избираш водещ източник и ще проверяваш останалите един по един. В края ще имаш сравнение, което показва дали проблемът идва от смесената светлина, а не от нужда от по-силен филтър.","deliverable":"Снимай един предмет при дневна и стайна светлина заедно, после изключи единия източник. Пази еднаква позиция. Ако балансът се сменя автоматично, отбележи това и не прави извод за точна цветова вярност.","check":"Важната повърхност няма неволно противоречиви цветове. При смяна на план няма внезапен цветен скок. Цветният фон може да остане умишлен."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Едната страна на лицето е под дневна светлина, другата — под жълта стайна лампа. Една обща настройка на бялото може да не реши различието."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Kelvin — стойност за цветната температура на източника. Оттенък — отклонение например към зелено или магента. Неутрален ориентир — подходящ бял или сив предмет под същата светлина; домашният лист не е измервателна карта.\n\nЕдин баланс на бялото избира една опорна точка. Първо реши кои източници ще осветяват лицето.\n\nМожеш да изключиш, покриеш или преместиш нежелан източник, да групираш лампите с близък цвят или умишлено да оставиш контраст в отделен фон. Цветната температура не описва напълно спектъра на една лампа."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Постави неутрален предмет или референтна карта при светлината върху лицето, а не на произволно място в стаята. Заключи баланса след проба и гледай кожата и цветните предмети. При светодиоди с различен спектър две лампи със сходни Kelvin стойности пак може да дадат различни кожи; сравни записа от самата камера, вместо да разчиташ на числото.\n\nГраница на решението: Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Определи водещия източник за лицето.\n2. Ограничи вторичната светлина или я остави само във фона.\n3. Заключи баланса на бялото при реалната светлина.\n4. Снимай и сравни кожа и неутрален предмет в двата плана."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Снимаш фризьорски салон: голяма витрина отляво, топли спотове над клиентката и студено огледало отпред.\n\nРешение: Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба.\n\nКакво да провериш: Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба. Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок.","label":"Как го поправяш"},"before":{"text":"Коригираш целия кадър към неутрално и оставяш зеленикави петна по едната буза.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Снимай един предмет при дневна и стайна светлина заедно, после изключи единия източник. Пази еднаква позиция. Ако балансът се сменя автоматично, отбележи това и не прави извод за точна цветова вярност.\n\nПровери резултата: Важната повърхност няма неволно противоречиви цветове. При смяна на план няма внезапен цветен скок. Цветният фон може да остане умишлен.\n\nПримерна работна бележка: С прозорец и таванна лампа бялата опаковка има две различни оцветени страни. След изключване на таванната лампа важната повърхност изглежда по-последователна. Цветна лампа далеч във фона може да остане, ако не оцветява продукта.\n\nАко не е изпълнено: Ако проблемът е само върху едната страна, обща корекция на бялото може да премести грешката другаде. Провери източниците отделно и повтори пробата при окончателното им разполагане."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Различните източници могат да оцветяват различни части по различен начин."},{"id":"b","label":"Стойностите в Kelvin винаги определят напълно спектъра на лампата."},{"id":"c","label":"Всеки фон трябва да е неутрален, дори да е творчески цветен."}],"question":"Защо една обща настройка на бялото може да не реши целия кадър?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Различните източници могат да оцветяват различни части по различен начин. Важната повърхност няма неволно противоречиви цветове. При смяна на план няма внезапен цветен скок. Цветният фон може да остане умишлен."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Снимаш фризьорски салон: голяма витрина отляво, топли спотове над клиентката и студено огледало отпред.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Настройвам бялото по предмет далече от светлината върху лицето."},{"id":"b","label":"Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба."},{"id":"c","label":"Прилагам зелена корекция върху целия кадър, без да проверя отделните източници."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба.\n\nКакво да провериш: Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Прехвърли всички камери на автоматичен баланс и остави всяка да решава самостоятелно."},{"id":"c","label":"Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Снимай един предмет при дневна и стайна светлина заедно, после изключи единия източник. Пази еднаква позиция. Ако балансът се сменя автоматично, отбележи това и не прави извод за точна цветова вярност.","takeaways":["Един баланс на бялото избира една опорна точка. Първо реши кои източници ще осветяват лицето.","Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба.","Провери: Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Заключи баланса на бялото при реалната светлина."},{"id":"s1","text":"Определи водещия източник за лицето."},{"id":"s4","text":"Снимай и сравни кожа и неутрален предмет в двата плана."},{"id":"s2","text":"Ограничи вторичната светлина или я остави само във фона."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Определи водещия източник за лицето. → Ограничи вторичната светлина или я остави само във фона. → Заключи баланса на бялото при реалната светлина. → Снимай и сравни кожа и неутрален предмет в двата плана."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Настъпва залез и дневната светлина отслабва по време на интервюто.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Прехвърли всички камери на автоматичен баланс и остави всяка да решава самостоятелно."},{"id":"b","label":"Преоцени водещия източник, направи нов ръчен баланс и остави контролен кадър за цветно съвпадение."},{"id":"c","label":"Коригираш целия кадър към неутрално и оставяш зеленикави петна по едната буза."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Преоцени водещия източник, направи нов ръчен баланс и остави контролен кадър за цветно съвпадение. Важната повърхност няма неволно противоречиви цветове. При смяна на план няма внезапен цветен скок. Цветният фон може да остане умишлен."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Първо установяваш къде възниква смесването. Корекция в редактора може да помогне, но не заменя проверката на терен."}}]},{"module":"s02-m04","lesson":"pv04-07","source_hash":"d815185a46702d399c776f2fa65250de","objective":"Ще сравняваш лампи по запис на важните за проекта цветове. Ще разбереш защо високото CRI не гарантира еднакъв резултат във всяка камера. За начална проба можеш да използваш наличните източници; ако имаш само един, ще провериш методиката чрез задачата с предоставени условия.","hook":"Две лампи имат еднакво високо CRI, но важният червен етикет изглежда различно в записите. Числото е начало на проверката.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще сравняваш лампи по запис на важните за проекта цветове. Ще разбереш защо високото CRI не гарантира еднакъв резултат във всяка камера. За начална проба можеш да използваш наличните източници; ако имаш само един, ще провериш методиката чрез задачата с предоставени условия.","deliverable":"При налични две лампи запиши една и съща опаковка при сравнимо осветяване. Ако температурите са различни, настрой подходящ баланс за всяка и отбележи промяната; заключен баланс е подходящ за сравними условия, не за скриване на различия.","check":"Пазиш сведения за лампа, режим, настройка и предмет. Изборът е за действителната комбинация с камерата. Без два източника не заявяваш, че си направил реално сравнение на лампи."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Две лампи имат еднакво високо CRI, но важният червен етикет изглежда различно в записите. Числото е начало на проверката."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"CRI — показател за цветопредаване спрямо определен еталонен източник. Спектър — какви части от светлината дава източникът. Наситеност — колко силно изглежда даден цвят.\n\nОцени лампата по реален запис на кожа и фирмени цветове; числото на кутията само насочва кои да тестваш.\n\nCRI описва определен тест спрямо референтен източник, но не гарантира как всеки цвят или всяка камера ще реагира. При различни диоди и режими спектърът, зеленото отклонение и цветните наситени повърхности може да се различават."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Снимай една и съща сцена с кожа или собствен предмет, червен и син цвят и подходящ неутрален ориентир. Пази сравнима експозиция, позиция и условия. При сходна цветна температура заключеният баланс е полезен. При различни температури използвай подходящ баланс за всеки източник и запиши тази промяна; иначе общият цветен уклон може да прикрие въпроса за цветопредаването.\n\nАко производителят публикува други показатели, използвай ги за подбор на пробите. ARRI уточнява, че показатели за човешкото възприятие като CRI не описват пряко записа на конкретната камера. Приглушеният режим и смесването на различни лампи се проверяват отделно.\n\nГраница на решението: Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Избери една и съща сцена и цветни предмети.\n2. Пази позицията и сравнима експозиция; запиши баланса и режима за всеки източник.\n3. Запиши A/B с двата източника при сравнима яркост.\n4. Провери кожа, наситени цветове и сенки на еднакъв екран."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Снимаш червена опаковка на бонбони за каталог. Два панела пишат CRI 95; при единия продуктът губи разликата между червено и оранжево.\n\nРешение: Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно.\n\nКакво да провериш: Условията и промените са записани; сравняваш важните цветове при съпоставима експозиция и подходящ баланс. Изборът е за проверената комбинация камера, лампа и режим."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно. Условията и промените са записани; сравняваш важните цветове при съпоставима експозиция и подходящ баланс. Изборът е за проверената комбинация камера, лампа и режим.","label":"Как го поправяш"},"before":{"text":"Обявяваш двата панела за еднакви по спецификация и поправяш всеки кадър с различен LUT.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"При налични две лампи запиши една и съща опаковка при сравнимо осветяване. Ако температурите са различни, настрой подходящ баланс за всяка и отбележи промяната; заключен баланс е подходящ за сравними условия, не за скриване на различия.\n\nПровери резултата: Пазиш сведения за лампа, режим, настройка и предмет. Изборът е за действителната комбинация с камерата. Без два източника не заявяваш, че си направил реално сравнение на лампи.\n\nПримерна работна бележка: Учебни условия: два панела с CRI 95, еднаква зададена температура и сравнима яркост; записът с панел А пази червения етикет, а Б го измества. Изборът е А за този предмет, камера и режим. Числото не доказва равен запис.\n\nАко не е изпълнено: Ако смениш едновременно лампа, яркост и баланс без записани условия, сравнението е неясно. Повтори при съпоставими условия. При различни цветни температури използвай подходящ баланс за всяка и отбележи промяната."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Камерата непременно ще запише всяка опаковка с еднакъв цвят."},{"id":"b","label":"Не е необходимо да проверявам приглушения режим на лампите."},{"id":"c","label":"Имат еднаква стойност по този показател, но нужният запис още трябва да се сравни."}],"question":"Какво можеш да заключиш от еднакво CRI 95 на две лампи?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Имат еднаква стойност по този показател, но нужният запис още трябва да се сравни. Пазиш сведения за лампа, режим, настройка и предмет. Изборът е за действителната комбинация с камерата. Без два източника не заявяваш, че си направил реално сравнение на лампи."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Снимаш червена опаковка на бонбони за каталог. Два панела пишат CRI 95; при единия продуктът губи разликата между червено и оранжево.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно."},{"id":"b","label":"Избирам лампата по CRI, без проба с червената опаковка."},{"id":"c","label":"Изравнявам общата наситеност, без да проверя дали червено и оранжево още се различават."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно.\n\nКакво да провериш: Условията и промените са записани; сравняваш важните цветове при съпоставима експозиция и подходящ баланс. Изборът е за проверената комбинация камера, лампа и режим."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Вдигни сатурацията, докато опаковката изглежда „по-цветна“ на камерата."},{"id":"b","label":"Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"При налични две лампи запиши една и съща опаковка при сравнимо осветяване. Ако температурите са различни, настрой подходящ баланс за всяка и отбележи промяната; заключен баланс е подходящ за сравними условия, не за скриване на различия.","takeaways":["Оцени лампата по реален запис на кожа и фирмени цветове; числото на кутията само насочва кои да тестваш.","Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно.","Провери: Условията и промените са записани; сравняваш важните цветове при съпоставима експозиция и подходящ баланс. Изборът е за проверената комбинация камера, лампа и режим."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Запиши A/B с двата източника при сравнима яркост."},{"id":"s1","text":"Избери една и съща сцена и цветни предмети."},{"id":"s4","text":"Провери кожа, наситени цветове и сенки на еднакъв екран."},{"id":"s2","text":"Пази позицията и сравнима експозиция; запиши баланса и режима за всеки източник."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Избери една и съща сцена и цветни предмети. → Пази позицията и сравнима експозиция; запиши баланса и режима за всеки източник. → Запиши A/B с двата източника при сравнима яркост. → Провери кожа, наситени цветове и сенки на еднакъв екран."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът добавя в кадър ярко лилава опаковка.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Направи нова проба именно с лилавата повърхност и финалната комбинация лампа–камера."},{"id":"b","label":"Обявяваш двата панела за еднакви по спецификация и поправяш всеки кадър с различен LUT."},{"id":"c","label":"Вдигни сатурацията, докато опаковката изглежда „по-цветна“ на камерата."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Направи нова проба именно с лилавата повърхност и финалната комбинация лампа–камера. Пазиш сведения за лампа, режим, настройка и предмет. Изборът е за действителната комбинация с камерата. Без два източника не заявяваш, че си направил реално сравнение на лампи."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Промяна на мощността или добавяне на нов цвят в проекта е причина за нов тест. Това не е оценка само по числа от реклама."}}]},{"module":"s02-m04","lesson":"pv04-08","source_hash":"fcebc8cf8210367bfe78fb4b4a60a22c","objective":"Ще използваш един източник за различни задачи: лице, надпис и движение. Ще сменяш позицията според това какво зрителят трябва да различи. В края ще имаш три кратки проби с различен критерий, вместо една схема, приложена механично навсякъде.","hook":"Светлина, която ласкае лице, често скрива релефа на опаковка или блести в чашата.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще използваш един източник за различни задачи: лице, надпис и движение. Ще сменяш позицията според това какво зрителят трябва да различи. В края ще имаш три кратки проби с различен критерий, вместо една схема, приложена механично навсякъде.","deliverable":"С един прозорец или лампа заснеми матов предмет, лъскава опаковка и собствено кратко движение. За всеки вариант промени позицията само когато конкретният детайл се губи.","check":"При матовия предмет се различава релеф; при опаковката се чете надпис; при движение важният обект остава видим. Самото наличие на светлина не изпълнява трите задачи."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Светлина, която ласкае лице, често скрива релефа на опаковка или блести в чашата."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Текстура — видимата повърхност и релеф на предмета. Огледално отражение — ярка следа от източника върху лъскава повърхност. Зона на движение — провереното пространство, в което кадърът остава използваем.\n\nСменяй посока, размер и дистанция според това какво зрителят трябва да види.\n\nЗа интервю провери очите и фона; при продукт провери текстура, отблясъци и надпис; при влог провери как лицето остава четимо при движение. Една лампа може да остане същата, но задачата ѝ се сменя."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Големият мек източник разширява отражението върху лъскав предмет; тесен източник може да покаже текстура по-рязко. При самозаснемане маркирай допустимата зона на движение на пода и направи проба в двата края. Не подреждай оборудването по любима диаграма, ако резултатът не служи на обекта.\n\nГраница на решението: Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Запиши една цел: лице, надпис или движение.\n2. Разположи лампата и фона според тази цел.\n3. Сними проба и провери ръбове, отблясък и сенки.\n4. Промени едно условие и повтори теста за следващата сцена."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Екип снима собственик на кафене, после лъскав буркан и накрая кратък влог, докато той върви между масите.\n\nРешение: За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото.\n\nКакво да провериш: Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото. Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение.","label":"Как го поправяш"},"before":{"text":"Оставяш осветлението на едно място и приемаш отражение, което заличава името на буркана.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"С един прозорец или лампа заснеми матов предмет, лъскава опаковка и собствено кратко движение. За всеки вариант промени позицията само когато конкретният детайл се губи.\n\nПровери резултата: При матовия предмет се различава релеф; при опаковката се чете надпис; при движение важният обект остава видим. Самото наличие на светлина не изпълнява трите задачи.\n\nПримерна работна бележка: За матовата кутия страничната светлина показва релефа. При лъскавия етикет променям ъгъла, за да се чете текстът. При движението разширявам полезната осветена зона, за да не изчезва предметът в сянка.\n\nАко не е изпълнено: Назови отделния дефект: скрит релеф, отблясък върху текст или излизане от светлината. Промени позицията за него и запиши целия кратък опит, включително движението."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Копирам позицията за лицето, защото лампата е същата."},{"id":"b","label":"По проба, при която отражението не пречи на нужния надпис."},{"id":"c","label":"Избирам най-яркия вариант, независимо от четливостта."}],"question":"Как избираш позицията за продукт с лъскав етикет?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"По проба, при която отражението не пречи на нужния надпис. При матовия предмет се различава релеф; при опаковката се чете надпис; при движение важният обект остава видим. Самото наличие на светлина не изпълнява трите задачи."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Екип снима собственик на кафене, после лъскав буркан и накрая кратък влог, докато той върви между масите.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Приемам заличения етикет, защото лицето в интервюто изглежда добре."},{"id":"b","label":"Добавям повече предна светлина, без да проверя къде попада отражението."},{"id":"c","label":"За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото.\n\nКакво да провериш: Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Добави още лампи преди да провериш отблясъка."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"С един прозорец или лампа заснеми матов предмет, лъскава опаковка и собствено кратко движение. За всеки вариант промени позицията само когато конкретният детайл се губи.","takeaways":["Сменяй посока, размер и дистанция според това какво зрителят трябва да види.","За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото.","Провери: Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Сними проба и провери ръбове, отблясък и сенки."},{"id":"s1","text":"Запиши една цел: лице, надпис или движение."},{"id":"s4","text":"Промени едно условие и повтори теста за следващата сцена."},{"id":"s2","text":"Разположи лампата и фона според тази цел."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Запиши една цел: лице, надпис или движение. → Разположи лампата и фона според тази цел. → Сними проба и провери ръбове, отблясък и сенки. → Промени едно условие и повтори теста за следващата сцена."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Бурканът се заменя с матова кутия с релефен печат.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Оставяш осветлението на едно място и приемаш отражение, което заличава името на буркана."},{"id":"b","label":"Добави още лампи преди да провериш отблясъка."},{"id":"c","label":"Тествай по-странична светлина за релефа и запази четимостта на печата; не пренасяй ъгъла от лъскавия буркан механично."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Тествай по-странична светлина за релефа и запази четимостта на печата; не пренасяй ъгъла от лъскавия буркан механично. При матовия предмет се различава релеф; при опаковката се чете надпис; при движение важният обект остава видим. Самото наличие на светлина не изпълнява трите задачи."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Различните критерии учат да избираш решение за задача. Не е нужно трите проби да бъдат еднакво стилизирани."}}]},{"module":"s02-m04","lesson":"pv04-09","source_hash":"7638918fbf00236cd1f4d470dd11a94e","objective":"Ще отделяш техническото поправяне на кадъра от творческия му вид. Ще разбираш защо общ филтър не изравнява автоматично две камери. В края ще имаш чиста и стилизирана версия и ще можеш да установиш в коя стъпка се появява проблемът.","hook":"Красив LUT върху неправилен баланс прави грешката по-красива и по-трудна за откриване.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще отделяш техническото поправяне на кадъра от творческия му вид. Ще разбираш защо общ филтър не изравнява автоматично две камери. В края ще имаш чиста и стилизирана версия и ще можеш да установиш в коя стъпка се появява проблемът.","deliverable":"Избери два свои кратки кадъра от една сцена. Първо изравни основната яркост и неволния цветен уклон, после запази отделна умерена визия. Изнеси кратък файл от всеки вариант.","check":"Срезът не променя неволно цвета на важния предмет. Чистата версия остава достъпна. Ако проблемът съществува и там, не го наричаш само творчески стил."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Красив LUT върху неправилен баланс прави грешката по-красива и по-трудна за откриване."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Цветова корекция — поправяне на неволни разлики и проблеми. Визия — творческият вид на изображението. LUT — таблица, която преобразува цветове; значението ѝ зависи от предназначения вход и изход.\n\nРаздели нормализиране на материала, изравняване на плановете и стилистичната визия.\n\nПърво избери правилен вход и изход за материала. После настрой експонация, контраст и баланс по образа и измервателните инструменти. Едва след това добави творческата промяна."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Използвай референтен кадър от същата сцена, но не изтривай умишлена нощна атмосфера с автоматично „избелване“. Ако екранът не е надежден, гледай waveform и RGB parade за крайности и сравнявай на още едно устройство. Запази версия преди визията, за да можеш да отделиш технически проблем от стил.\n\nГраница на решението: Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Провери входния цветови профил и целевия изход.\n2. Изправи експонация и баланс без творчески филтър.\n3. Изравни съседните планове с референтен кадър.\n4. Добави визия и провери на целевия екран."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Кафене получава два кадъра от една сцена: едната камера е студена, другата топла. Иска се мек филмов тон.\n\nРешение: Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез.\n\nКакво да провериш: При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез. При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони.","label":"Как го поправяш"},"before":{"text":"Слагаш един и същ LUT на двата клипа и оставяш кожата да сменя цвят при срез.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Избери два свои кратки кадъра от една сцена. Първо изравни основната яркост и неволния цветен уклон, после запази отделна умерена визия. Изнеси кратък файл от всеки вариант.\n\nПровери резултата: Срезът не променя неволно цвета на важния предмет. Чистата версия остава достъпна. Ако проблемът съществува и там, не го наричаш само творчески стил.\n\nПримерна работна бележка: А е технически изравнената последователност; Б добавя умерена визия върху нея. Ако бялата чаша е зеленикава и в А, поправката е още в техническата част. Ако проблемът е само в Б, променям стила.\n\nАко не е изпълнено: Изключвай творческите промени последователно и сравнявай на същия екран. Не записвай върху единственото чисто копие. При непознат входен профил първо уточни произхода на материала."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Проверен вход, техническа корекция, съвпадение между кадри, отделна визия."},{"id":"b","label":"Силен общ филтър, после коригиране само на кадрите, които изглеждат най-различни."},{"id":"c","label":"Копиране на числата от първата камера, без проверка на втората."}],"question":"Кой работен ред позволява да намериш причината за цветна грешка?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Проверен вход, техническа корекция, съвпадение между кадри, отделна визия. Срезът не променя неволно цвета на важния предмет. Чистата версия остава достъпна. Ако проблемът съществува и там, не го наричаш само творчески стил."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Кафене получава два кадъра от една сцена: едната камера е студена, другата топла. Иска се мек филмов тон.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Прилагам общата визия направо върху различните изходни профили."},{"id":"b","label":"Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез."},{"id":"c","label":"Избирам една температура за целия монтаж и не сравнявам лицето при срез."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез.\n\nКакво да провериш: При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Добави наситеност към всички цветове, докато продуктът се доближи до каталога."},{"id":"c","label":"Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Избери два свои кратки кадъра от една сцена. Първо изравни основната яркост и неволния цветен уклон, после запази отделна умерена визия. Изнеси кратък файл от всеки вариант.","takeaways":["Раздели нормализиране на материала, изравняване на плановете и стилистичната визия.","Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез.","Провери: При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Изравни съседните планове с референтен кадър."},{"id":"s1","text":"Провери входния цветови профил и целевия изход."},{"id":"s4","text":"Добави визия и провери на целевия екран."},{"id":"s2","text":"Изправи експонация и баланс без творчески филтър."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Провери входния цветови профил и целевия изход. → Изправи експонация и баланс без творчески филтър. → Изравни съседните планове с референтен кадър. → Добави визия и провери на целевия екран."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът одобрява стила, но иска продукта по-близо до реалния му цвят.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Добави наситеност към всички цветове, докато продуктът се доближи до каталога."},{"id":"b","label":"Запази одобрената обща визия и поправи локално продукта с проверка срещу референтен кадър."},{"id":"c","label":"Слагаш един и същ LUT на двата клипа и оставяш кожата да сменя цвят при срез."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Запази одобрената обща визия и поправи локално продукта с проверка срещу референтен кадър. Срезът не променя неволно цвета на важния предмет. Чистата версия остава достъпна. Ако проблемът съществува и там, не го наричаш само творчески стил."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Безплатен редактор може да е достатъчен за основната задача. Нужна е проба, че той отваря конкретните файлове; платени автоматични инструменти не са предпоставка."}}]},{"module":"s02-m04","lesson":"pv04-10","source_hash":"150b535fc359c71d1a064a8d23472173","objective":"Ще избираш палитра и цветно настроение според историята, продукта и аудиторията. Ще сравняваш умерени варианти на същия кадър и ще пазиш реалния цвят на важните предмети. Ще можеш да обясниш творческия избор, без да обещаваш, че определен цвят непременно продава.","hook":"Оранжевият кадър може да е уютен, но също може да направи синята опаковка кафява.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще избираш палитра и цветно настроение според историята, продукта и аудиторията. Ще сравняваш умерени варианти на същия кадър и ще пазиш реалния цвят на важните предмети. Ще можеш да обясниш творческия избор, без да обещаваш, че определен цвят непременно продава.","deliverable":"За пекарна „Зърно“ направи неутрален и умерено топъл вариант от същия кадър. Запази 6 мини банички, 9 € и истинския цвят на опаковката. При графичен вариант отдели фон, текст и акцент.","check":"Храната и условията остават достоверни, текстът се чете и разликата може да се обясни с конкретната идея. Ассоциацията с уют е творческа хипотеза, не установен резултат от аудиторията."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Оранжевият кадър може да е уютен, но също може да направи синята опаковка кафява."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Палитра — подбран набор от цветове. Цветен кръг — помощно подреждане на цветни отношения. Архетип в разказа — творческа роля, например майстор или водач; тук не го използваме като диагноза на зрителя.\n\nНастроението идва от сцената, светлината и монтажа заедно; температурата сама не обещава определена емоция.\n\nИзбери какво трябва да усеща зрителят, какво трябва да разпознае и кои цветове са неприкосновени. Направи два варианта от един и същ неутрален кадър, вместо да сравняваш различни кадри."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Гледай кожата, фирмения цвят и неутрален предмет при двата варианта. Покажи ги в контекста на съседните кадри и звука. Ако разказът е за свежест, топлият вариант може да му противоречи; ако клиентът продава физически продукт, значимите цветове не бива да се измислят.\n\nГраница на решението: Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Определи посланието и предметите, чиито цветове трябва да останат честни.\n2. Изготви неутрален референтен кадър.\n3. Направи два умерени варианта само от него.\n4. Прегледай ги в последователността на видеото с клиента."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Пекарна иска „топло, домашно“ видео. Първата версия прави хляба оранжев, но маслото и бялата опаковка изглеждат неверни.\n\nРешение: Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове.\n\nКакво да провериш: Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове. Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми.","label":"Как го поправяш"},"before":{"text":"Усилваш топлината до максимум, защото „топло продава“.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"За пекарна „Зърно“ направи неутрален и умерено топъл вариант от същия кадър. Запази 6 мини банички, 9 € и истинския цвят на опаковката. При графичен вариант отдели фон, текст и акцент.\n\nПровери резултата: Храната и условията остават достоверни, текстът се чете и разликата може да се обясни с конкретната идея. Ассоциацията с уют е творческа хипотеза, не установен резултат от аудиторията.\n\nПримерна работна бележка: Неутралната версия пази опаковката. Умерено топлата свързва кадъра с идеята за прясно приготвена храна, без да променя продукта. Надписът остава „6 мини банички — 9 €; вземане след уточняване“. Няма обещание за доставка или наличност.\n\nАко не е изпълнено: Ако топлата версия променя продукта, отслаби промяната или я ограничи до фон и графика. Ако текстът се губи, промени фона или текста и провери контраста. Емоционалната асоциация остава хипотеза за бъдещ тест."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Оцветявам всички важни предмети в оранжево, за да усилвам усещането."},{"id":"b","label":"Избирам по таблица, която обещава еднакъв психологически ефект за всички."},{"id":"c","label":"Проверявам настроението в контекст и пазя разпознаваемите цветове на продукта."}],"question":"Кое е обосновано решение за топла визия на хранителен продукт?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Проверявам настроението в контекст и пазя разпознаваемите цветове на продукта. Храната и условията остават достоверни, текстът се чете и разликата може да се обясни с конкретната идея. Ассоциацията с уют е творческа хипотеза, не установен резултат от аудиторията."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Пекарна иска „топло, домашно“ видео. Първата версия прави хляба оранжев, но маслото и бялата опаковка изглеждат неверни.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове."},{"id":"b","label":"Усилвам топлия цвят върху храната и опаковката едновременно."},{"id":"c","label":"Оставям неверния цвят на продукта, защото палитрата изглежда последователна."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове.\n\nКакво да провериш: Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Промени температурата на всички кадри на една и съща стойност без сравнение."},{"id":"b","label":"Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"За пекарна „Зърно“ направи неутрален и умерено топъл вариант от същия кадър. Запази 6 мини банички, 9 € и истинския цвят на опаковката. При графичен вариант отдели фон, текст и акцент.","takeaways":["Настроението идва от сцената, светлината и монтажа заедно; температурата сама не обещава определена емоция.","Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове.","Провери: Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Направи два умерени варианта само от него."},{"id":"s1","text":"Определи посланието и предметите, чиито цветове трябва да останат честни."},{"id":"s4","text":"Прегледай ги в последователността на видеото с клиента."},{"id":"s2","text":"Изготви неутрален референтен кадър."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Определи посланието и предметите, чиито цветове трябва да останат честни. → Изготви неутрален референтен кадър. → Направи два умерени варианта само от него. → Прегледай ги в последователността на видеото с клиента."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Същото видео ще се използва и за техническа инструкция.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Остави по-неутрална, ясна версия за инструкцията; провери дали материалите и предупрежденията не се губят."},{"id":"b","label":"Усилваш топлината до максимум, защото „топло продава“."},{"id":"c","label":"Промени температурата на всички кадри на една и съща стойност без сравнение."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Остави по-неутрална, ясна версия за инструкцията; провери дали материалите и предупрежденията не се губят. Храната и условията остават достоверни, текстът се чете и разликата може да се обясни с конкретната идея. Ассоциацията с уют е творческа хипотеза, не установен резултат от аудиторията."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Ако разказваш чрез ролята на майстор, покажи проверимо действие. Цветният кръг помага за съчетания; не представяме „юнгианска палитра“ като доказана формула за покупки. За текст върху фон използвай проверка на контраста, после гледай реалния файл в движение."}}]},{"module":"s02-m04","lesson":"pv04-11","source_hash":"e4e7aec22a8ca9e00782ce38d0498a59","objective":"Ще проверяваш дали лицето остава последователно между кадрите, без да уеднаквяваш различни хора. Ще използваш кожа и неутрален предмет като ориентири в конкретната светлина. Целта е да откриеш неволен цветен уклон и да запазиш естествените различия и текстурата.","hook":"Плъзгачът казва „правилно“, а лицето изглежда сиво или прекалено оранжево.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще проверяваш дали лицето остава последователно между кадрите, без да уеднаквяваш различни хора. Ще използваш кожа и неутрален предмет като ориентири в конкретната светлина. Целта е да откриеш неволен цветен уклон и да запазиш естествените различия и текстурата.","deliverable":"Сравни собствено лице или доброволен възрастен участник в два плана от същата сцена. Не използвай друго лице като универсален образец. При липса на измервателен инструмент изпълни визуалната част и отбележи ограничението.","check":"Същият човек не сменя неволно оттенък при срез. Умишлената цветна светлина се запазва, когато е част от сцената. Измервателната линия не се използва като еднаква цел за всички."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Плъзгачът казва „правилно“, а лицето изглежда сиво или прекалено оранжево."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Vectorscope — графика за посоката и силата на цвета. Маска — ограничаване на корекцията до част от кадъра. Магента — пурпурният цветен уклон, противопоставян на зеленикавия при някои корекции.\n\nОцени кожата във връзка със светлината, човека и съседните кадри; не настройвай всички лица към един цвят.\n\nVectorscope може да подскаже нежелан цветен уклон, но линията за кожа не определя светлота или желания вид за всеки човек. Маска върху малка зона може да помогне да прочетеш посоката, без да променяш целия кадър."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Започни с правилен входен профил и баланс на бялото. Сравни лице, бял/сив предмет под същата светлина и референтен кадър от снимачния ден. Ако светлината е умишлено цветна, не изравнявай всяка буза към неутрално; поправи неволен зелен или магента оттенък само когато нарушава достоверността.\n\nГраница на решението: Различните тонове кожа и умишленото цветно осветление не се побират в един универсален цветен ориентир на vectorscope."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Нормализирай материала и намери референтен кадър.\n2. Провери кожата и неутралния предмет под една и съща светлина.\n3. Коригирай нежелания уклон умерено; пази текстура.\n4. Прехвърли между плановете и провери на друг екран."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Двама служители са снимани в една стая, но единият стои под зеленикав LED. След обща корекция неговото лице още изглежда болно.\n\nРешение: Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план.\n\nКакво да провериш: Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план. Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез.","label":"Как го поправяш"},"before":{"text":"Издърпваш глобално всички лица към една оранжева стойност.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Сравни собствено лице или доброволен възрастен участник в два плана от същата сцена. Не използвай друго лице като универсален образец. При липса на измервателен инструмент изпълни визуалната част и отбележи ограничението.\n\nПровери резултата: Същият човек не сменя неволно оттенък при срез. Умишлената цветна светлина се запазва, когато е част от сцената. Измервателната линия не се използва като еднаква цел за всички.\n\nПримерна работна бележка: Същият участник изглежда неволно по-зелен в близкия план; неутралният предмет също се измества. Поправям този план умерено и сравнявам при срез. Не изравнявам различни хора към една числова стойност.\n\nАко не е изпълнено: Провери дали цветната светлина е умишлена и дали неутралният ориентир показва същото отклонение. Ако липсва сравним ориентир, не представяй личното впечатление като точна цветова проверка."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Всички говорители спрямо една избрана оранжева стойност."},{"id":"b","label":"Същият човек при същата или ясно описана светлина и съседни планове."},{"id":"c","label":"Копирани настройки от различна сцена, без контролен кадър."}],"question":"Какво е полезното сравнение при корекция на кожа?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Същият човек при същата или ясно описана светлина и съседни планове. Същият човек не сменя неволно оттенък при срез. Умишлената цветна светлина се запазва, когато е част от сцената. Измервателната линия не се използва като еднаква цел за всички."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Двама служители са снимани в една стая, но единият стои под зеленикав LED. След обща корекция неговото лице още изглежда болно.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Изравнявам двете лица към една стойност, без да отделя проблемния кадър."},{"id":"b","label":"Поправям само бялата чаша, без да погледна лицето под зеленикавата лампа."},{"id":"c","label":"Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план.\n\nКакво да провериш: Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Различните тонове кожа и умишленото цветно осветление не се побират в един универсален цветен ориентир на vectorscope."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Кликни автоматично „skin tone“ и копирай стойностите на всички говорители."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Различните тонове кожа и умишленото цветно осветление не се побират в един универсален цветен ориентир на vectorscope."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Сравни собствено лице или доброволен възрастен участник в два плана от същата сцена. Не използвай друго лице като универсален образец. При липса на измервателен инструмент изпълни визуалната част и отбележи ограничението.","takeaways":["Оцени кожата във връзка със светлината, човека и съседните кадри; не настройвай всички лица към един цвят.","Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план.","Провери: Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Коригирай нежелания уклон умерено; пази текстура."},{"id":"s1","text":"Нормализирай материала и намери референтен кадър."},{"id":"s4","text":"Прехвърли между плановете и провери на друг екран."},{"id":"s2","text":"Провери кожата и неутралния предмет под една и съща светлина."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Различните тонове кожа и умишленото цветно осветление не се побират в един универсален цветен ориентир на vectorscope."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Нормализирай материала и намери референтен кадър. → Провери кожата и неутралния предмет под една и съща светлина. → Коригирай нежелания уклон умерено; пази текстура. → Прехвърли между плановете и провери на друг екран."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Оказва се, че финалният кадър е заснет под цветна сценична светлина.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Издърпваш глобално всички лица към една оранжева стойност."},{"id":"b","label":"Кликни автоматично „skin tone“ и копирай стойностите на всички говорители."},{"id":"c","label":"Запази умишления цвят на сцената и търси само неволни зелени/магента смени спрямо съседните кадри."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Запази умишления цвят на сцената и търси само неволни зелени/магента смени спрямо съседните кадри. Същият човек не сменя неволно оттенък при срез. Умишлената цветна светлина се запазва, когато е част от сцената. Измервателната линия не се използва като еднаква цел за всички."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Не правим психологически изводи или оценки за човека по цвета на кожата. Тук проверяваме изображението и условията на записа."}}]},{"module":"s02-m04","lesson":"pv04-12","source_hash":"94f6922d7326527b1926e220c3041764","objective":"Ще четеш основните измервателни графики заедно с изображението. Ще откриваш къде се губи светъл детайл и кога наситеният цвят е умишлен. В края ще провериш една и съща проблемна зона в изходния кадър, корекцията и изнесения файл.","hook":"Мониторът изглежда добре, но експортът губи белия текст на опаковката.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще четеш основните измервателни графики заедно с изображението. Ще откриваш къде се губи светъл детайл и кога наситеният цвят е умишлен. В края ще провериш една и съща проблемна зона в изходния кадър, корекцията и изнесения файл.","deliverable":"Заснеми светла чиния и цветна опаковка. В редактор с подходящи графики сравни оригинала, силна и умерена корекция. Ако нямаш такъв редактор, реши задачите с условията; това не е практически опит със измервателни графики.","check":"Важният светъл предмет пази детайл във финалния файл. Знаеш дали измерваш входа или изхода. Графиката не се разтяга до краищата само за да изглежда „пълна“."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Мониторът изглежда добре, но експортът губи белия текст на опаковката."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Waveform — графика на яркостта по ширината на изображението. RGB parade — отделни графики за червения, зеления и синия канал. Vectorscope — графика за цвят и наситеност.\n\nWaveform показва разпределението на яркостта по изображението, vectorscope показва посока и сила на цвета.\n\nЧети измервателни графики заедно с кадъра. Плоска линия в горния край на waveform може да е клипинг; силно изнесена точка на vectorscope може да е наситен предмет, не „грешка“. RGB parade помага да видиш разминаване между канали в неутрални области."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Увери се, че гледаш правилното място във веригата на управление на цветовете в проекта: лог сигнал преди трансформация изглежда различно от финалния изход. Провери отделно оригинал, коригирана версия и експорт. Никоя графика не заменя решение за съдържанието; тя показва какво се случва със сигнала.\n\nГраница на решението: Стойностите на измервателни графики зависят от цветното пространство, трансформацията и настройките на проекта."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Определи дали измерваш входа или финалния изход.\n2. Намери конкретно място в кадъра, което изглежда проблемно.\n3. Сравни waveform, vectorscope и изображението след една промяна.\n4. Изнеси тестов файл и повтори проверката върху него."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Видео на шоколадов десерт има бяла чиния и червено лого. На лаптопа изглежда красиво, но на телефона чинията е без текстура.\n\nРешение: Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран.\n\nКакво да провериш: Чинията пази форма, логото остава четимо, а измервателни графики и експортираният файл не си противоречат."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран. Чинията пази форма, логото остава четимо, а измервателни графики и експортираният файл не си противоречат.","label":"Как го поправяш"},"before":{"text":"Вярваш само на яркостта на лаптопа и добавяш още контраст.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Заснеми светла чиния и цветна опаковка. В редактор с подходящи графики сравни оригинала, силна и умерена корекция. Ако нямаш такъв редактор, реши задачите с условията; това не е практически опит със измервателни графики.\n\nПровери резултата: Важният светъл предмет пази детайл във финалния файл. Знаеш дали измерваш входа или изхода. Графиката не се разтяга до краищата само за да изглежда „пълна“.\n\nПримерна работна бележка: При силната корекция светлата чиния губи рисунъка си и графиката показва натрупване в горната зона. Умереният вариант пази детайла. Записвам, че проверявам изходния SDR сигнал и после действителния експорт.\n\nАко не е изпълнено: Ако детайлът е изгубен още в оригинала, намаляването на яркостта не го възстановява. Ако измерваш Log преди преобразуване, първо уточни този етап. Не оформяй графиката по външния ѝ вид."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"На кой етап е измерването и дали входната трансформация е правилна."},{"id":"b","label":"Дали графиката може да се разтегне до максимума с контраст."},{"id":"c","label":"Дали изображението е достатъчно ярко на автоматично усиления екран."}],"question":"Какво проверяваш преди да коригираш сплескана графика на Log материал?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"На кой етап е измерването и дали входната трансформация е правилна. Важният светъл предмет пази детайл във финалния файл. Знаеш дали измерваш входа или изхода. Графиката не се разтяга до краищата само за да изглежда „пълна“."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Видео на шоколадов десерт има бяла чиния и червено лого. На лаптопа изглежда красиво, но на телефона чинията е без текстура.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Добавям още контраст, защото чинията на лаптопа изглежда бяла."},{"id":"b","label":"Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран."},{"id":"c","label":"Намалявам яркостта на телефона и приемам това за поправка на файла."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран.\n\nКакво да провериш: Чинията пази форма, логото остава четимо, а измервателни графики и експортираният файл не си противоречат."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Премести всички нива така, че графиката да докосва и двата края."},{"id":"c","label":"Стойностите на измервателни графики зависят от цветното пространство, трансформацията и настройките на проекта."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Стойностите на измервателни графики зависят от цветното пространство, трансформацията и настройките на проекта."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Заснеми светла чиния и цветна опаковка. В редактор с подходящи графики сравни оригинала, силна и умерена корекция. Ако нямаш такъв редактор, реши задачите с условията; това не е практически опит със измервателни графики.","takeaways":["Waveform показва разпределението на яркостта по изображението, vectorscope показва посока и сила на цвета.","Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран.","Провери: Чинията пази форма, логото остава четимо, а измервателни графики и експортираният файл не си противоречат."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Сравни waveform, vectorscope и изображението след една промяна."},{"id":"s1","text":"Определи дали измерваш входа или финалния изход."},{"id":"s4","text":"Изнеси тестов файл и повтори проверката върху него."},{"id":"s2","text":"Намери конкретно място в кадъра, което изглежда проблемно."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Стойностите на измервателни графики зависят от цветното пространство, трансформацията и настройките на проекта."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Определи дали измерваш входа или финалния изход. → Намери конкретно място в кадъра, което изглежда проблемно. → Сравни waveform, vectorscope и изображението след една промяна. → Изнеси тестов файл и повтори проверката върху него."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Получаваш Log материал от втора камера и waveform изглежда сплескан.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Премести всички нива така, че графиката да докосва и двата края."},{"id":"b","label":"Провери входната трансформация и оцени измервателни графики на правилния етап преди да „поправяш“ сигнал, който е нормален за Log."},{"id":"c","label":"Вярваш само на яркостта на лаптопа и добавяш още контраст."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Провери входната трансформация и оцени измервателни графики на правилния етап преди да „поправяш“ сигнал, който е нормален за Log. Важният светъл предмет пази детайл във финалния файл. Знаеш дали измерваш входа или изхода. Графиката не се разтяга до краищата само за да изглежда „пълна“."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"При наличен подходящ компютър основните графики могат да се изучават с безплатен редактор. Те измерват сигнал, а не харесване, доверие или виралност."}}]},{"module":"s02-m04","lesson":"pv04-13","source_hash":"b9713c7dcde3b23084a982687a26c384","objective":"Ще проследяваш как материалът преминава от камерата към крайния файл. Ще различаваш запис в Log от готов стандартен вид и ще откриваш дублирано преобразуване. За първия проект можеш да останеш със стандартен SDR запис; Log е възможност за подходяща задача, не условие за стойност.","hook":"Материалът изглежда сив; слагаш LUT, после още един и лицето става пластмасово.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще проследяваш как материалът преминава от камерата към крайния файл. Ще различаваш запис в Log от готов стандартен вид и ще откриваш дублирано преобразуване. За първия проект можеш да останеш със стандартен SDR запис; Log е възможност за подходяща задача, не условие за стойност.","deliverable":"На работно копие проследи входен профил, обработка и изход. Ако имаш достоверно обозначен Log клип, сравни правилна трансформация с дублирана. Без такъв файл не приписвай профил по външен вид.","check":"Точният вход е известен или обозначен като неизвестен. Няма две еднакви технически преобразувания. Експортът е прегледан; оригиналът е запазен."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Материалът изглежда сив; слагаш LUT, после още един и лицето става пластмасово."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Log — начин за записване на яркостта, който изисква правилна интерпретация. Gamut — диапазонът цветове в дадено пространство. Rec.709 — стандарт, използван при много SDR видеодоставки.\n\nЗапиши какъв е реалният профил на всеки файл, в кое пространство работиш и към какъв екран изнасяш.\n\nLog е начин за кодиране на картината, а не готов финален вид. Превръщането към Rec.709 може да стане с подходящо управление на цветовете в проекта или с правилна трансформация; ако приложиш и двете като еднакви стъпки, често удвояваш контраста и цвета."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Провери точния профил в настройките на камерата или файловите метаданни; „Log“ не е една универсална крива. Използвай официалната трансформация за конкретната камера и поддържай последователен изходна цел за файла. Сравнявай референтна снимка от терена и провери финала на реален екран, защото превюто на монтажната програма може да следва друга дисплейна настройка.\n\nГраница на решението: Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Идентифицирай профила и gamut за всеки източник.\n2. Избери една работна схема: управление на цветовете в проекта или ръчно управлявани трансформации.\n3. Коригирай експонация и баланс на нормализиран образ.\n4. Изнеси Rec.709 тест и провери кожа, светли и тъмни области."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Един клип е заснет в Log, вторият е готов стандартен профил. Монтажът автоматично управлява цвета, а върху първия вече има технически LUT.\n\nРешение: Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж.\n\nКакво да провериш: В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж. В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация.","label":"Как го поправяш"},"before":{"text":"Слагаш същия технически LUT и на двата файла, за да са „еднакви“.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"На работно копие проследи входен профил, обработка и изход. Ако имаш достоверно обозначен Log клип, сравни правилна трансформация с дублирана. Без такъв файл не приписвай профил по външен вид.\n\nПровери резултата: Точният вход е известен или обозначен като неизвестен. Няма две еднакви технически преобразувания. Експортът е прегледан; оригиналът е запазен.\n\nПримерна работна бележка: Вход: потвърден конкретен Log профил от данните на камерата. Обработка: една техническа трансформация към уговорения SDR изход, после корекция и визия. При стандартния телефонен запис не добавям Log преобразуване по догадка.\n\nАко не е изпълнено: При прекален контраст провери първо за повторна трансформация в проекта и върху клипа. Ако профилът е неизвестен, запази това като неизвестно и уточни файла; не избирай LUT само по приятна миниатюра."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Дали името му съдържа „cinematic“ и картината е по-контрастна."},{"id":"b","label":"Дали може да се използва еднакво върху стандартен и неизвестен клип."},{"id":"c","label":"За кой конкретен вход и изход е предназначен и какво вече прави проектът."}],"question":"Какво трябва да знаеш преди технически LUT?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"За кой конкретен вход и изход е предназначен и какво вече прави проектът. Точният вход е известен или обозначен като неизвестен. Няма две еднакви технически преобразувания. Експортът е прегледан; оригиналът е запазен."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Един клип е заснет в Log, вторият е готов стандартен профил. Монтажът автоматично управлява цвета, а върху първия вече има технически LUT.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж."},{"id":"b","label":"Добавям технически LUT към вече управлявания Log кадър."},{"id":"c","label":"Преобразувам и стандартния профил като Log, за да изравня настройките."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж.\n\nКакво да провериш: В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Вдигни контраст ръчно, докато сивият клип изглежда цветен."},{"id":"b","label":"Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"На работно копие проследи входен профил, обработка и изход. Ако имаш достоверно обозначен Log клип, сравни правилна трансформация с дублирана. Без такъв файл не приписвай профил по външен вид.","takeaways":["Запиши какъв е реалният профил на всеки файл, в кое пространство работиш и към какъв екран изнасяш.","Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж.","Провери: В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Коригирай експонация и баланс на нормализиран образ."},{"id":"s1","text":"Идентифицирай профила и gamut за всеки източник."},{"id":"s4","text":"Изнеси Rec.709 тест и провери кожа, светли и тъмни области."},{"id":"s2","text":"Избери една работна схема: управление на цветовете в проекта или ръчно управлявани трансформации."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Идентифицирай профила и gamut за всеки източник. → Избери една работна схема: управление на цветовете в проекта или ръчно управлявани трансформации. → Коригирай експонация и баланс на нормализиран образ. → Изнеси Rec.709 тест и провери кожа, светли и тъмни области."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Получаваш клип без достоверни метаданни от трета камера.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Поискай или провери настройката от снимачния ден и направи тест с референтен кадър; не приписвай профил по външен вид."},{"id":"b","label":"Слагаш същия технически LUT и на двата файла, за да са „еднакви“."},{"id":"c","label":"Вдигни контраст ръчно, докато сивият клип изглежда цветен."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Поискай или провери настройката от снимачния ден и направи тест с референтен кадър; не приписвай профил по външен вид. Точният вход е известен или обозначен като неизвестен. Няма две еднакви технически преобразувания. Експортът е прегледан; оригиналът е запазен."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"SDR и HDR са различни работни условия. Не сменяй изхода към HDR по впечатление от по-ярък екран; провери целта и цялата верига."}}]},{"module":"s02-m04","lesson":"pv04-14","source_hash":"70a79c04511066018df67993bfd6deb3","objective":"Ще сравняваш съседни кадри по общи ориентири и ще откриваш неволния цветен скок. Ще поправяш различието в конкретния план, вместо да копираш числа от друга камера. Резултатът е кратка последователност, в която лицето или продуктът остава последователен.","hook":"Снимките са красиви поотделно, но при монтаж чашата и лицето сменят цвят през секунда.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще сравняваш съседни кадри по общи ориентири и ще откриваш неволния цветен скок. Ще поправяш различието в конкретния план, вместо да копираш числа от друга камера. Резултатът е кратка последователност, в която лицето или продуктът остава последователен.","deliverable":"Монтирай няколко редувания между два плана на един предмет. Първо сравни яркостта, после неутралния ориентир и продукта. Запази корекция само в проблемния план.","check":"Важният обект не сменя неволно цвят при срез. Естествената различна посока на светлината не се унищожава. Проверката е върху краткия изнесен файл."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Снимките са красиви поотделно, но при монтаж чашата и лицето сменят цвят през секунда."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Контролен кадър — избран ориентир от същата сцена. Срез — преминаването от един кадър към друг. Цветен уклон — неволна промяна например към зелено или синьо.\n\nИзбери контролен кадър и сравнявай планове в един и същ контекст, преди да копираш настройки.\n\nГледай общите предмети, лице, фон и посока на светлината. Първо изравни най-видимото разминаване в експонацията, после баланса и цвета. Прескачай между кадрите с кратък интервал, за да усетиш внезапния скок."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Ако камерата се е обърнала към прозорец, двата плана имат естествено различна светлина. Целта не е числено съвпадение на всяка пикселна стойност, а зрителят да не се обърка от неволна смяна. Корекцията на кожа не трябва да унищожава истинския цвят на продукта. Запази неподправен контролен стоп кадър преди силна визия.\n\nГраница на решението: Две камери с различна цветна реакция или при различна светлина няма да съвпаднат чрез копиране на плъзгачи."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Избери референтен кадър от същата сцена.\n2. Сравни експонация и неутрални предмети.\n3. Промени цветния уклон само в проблемния план.\n4. Прегледай среза на цял екран и в експорт."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"На интервю основната камера показва топло лице, близкият план е зеленикав. В кадъра и на двете има бяла чаша.\n\nРешение: Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез.\n\nКакво да провериш: Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез. Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината.","label":"Как го поправяш"},"before":{"text":"Копираш стойностите на първата камера върху втората без да погледнеш оригиналния ѝ профил.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Монтирай няколко редувания между два плана на един предмет. Първо сравни яркостта, после неутралния ориентир и продукта. Запази корекция само в проблемния план.\n\nПровери резултата: Важният обект не сменя неволно цвят при срез. Естествената различна посока на светлината не се унищожава. Проверката е върху краткия изнесен файл.\n\nПримерна работна бележка: Общият и близкият план показват една и съща опаковка. Близкият е по-зелен; поправям неговия неутрален ориентир и проверявам продукта в редуване. По-тъмната страна остава по-тъмна, когато светлината го обяснява.\n\nАко не е изпълнено: Ако срезът още променя предмета, сравни входния профил и неутралния ориентир, преди да усилваш общия стил. Оцени изнесената последователност, а не само две отделни снимки."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Съседните планове винаги трябва да имат напълно еднакви пикселни стойности."},{"id":"b","label":"Входните профили и светлината могат да бъдат различни."},{"id":"c","label":"Различният план изисква по-силен стил, преди техническата проверка."}],"question":"Защо копираните плъзгачи не гарантират съвпадение?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Входните профили и светлината могат да бъдат различни. Важният обект не сменя неволно цвят при срез. Естествената различна посока на светлината не се унищожава. Проверката е върху краткия изнесен файл."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"На интервю основната камера показва топло лице, близкият план е зеленикав. В кадъра и на двете има бяла чаша.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Копирам корекцията на топлата камера и приемам зеленикавия близък план."},{"id":"b","label":"Променям всички кадри заради чашата в един проблемен план."},{"id":"c","label":"Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез.\n\nКакво да провериш: Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Две камери с различна цветна реакция или при различна светлина няма да съвпаднат чрез копиране на плъзгачи."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Уеднакви всички кадри по обща стойност на Kelvin."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Две камери с различна цветна реакция или при различна светлина няма да съвпаднат чрез копиране на плъзгачи."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Монтирай няколко редувания между два плана на един предмет. Първо сравни яркостта, после неутралния ориентир и продукта. Запази корекция само в проблемния план.","takeaways":["Избери контролен кадър и сравнявай планове в един и същ контекст, преди да копираш настройки.","Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез.","Провери: Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Промени цветния уклон само в проблемния план."},{"id":"s1","text":"Избери референтен кадър от същата сцена."},{"id":"s4","text":"Прегледай среза на цял екран и в експорт."},{"id":"s2","text":"Сравни експонация и неутрални предмети."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Две камери с различна цветна реакция или при различна светлина няма да съвпаднат чрез копиране на плъзгачи."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Избери референтен кадър от същата сцена. → Сравни експонация и неутрални предмети. → Промени цветния уклон само в проблемния план. → Прегледай среза на цял екран и в експорт."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: При снимането облак е затъмнил втория план, а човекът е преместен до лампа.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Копираш стойностите на първата камера върху втората без да погледнеш оригиналния ѝ профил."},{"id":"b","label":"Уеднакви всички кадри по обща стойност на Kelvin."},{"id":"c","label":"Провери кой проблем е експонация и кой е нова посока на светлина; компенсирай четимостта, без да симулираш невъзможен идентичен модел."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Провери кой проблем е експонация и кой е нова посока на светлина; компенсирай четимостта, без да симулираш невъзможен идентичен модел. Важният обект не сменя неволно цвят при срез. Естествената различна посока на светлината не се унищожава. Проверката е върху краткия изнесен файл."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Последователността помага зрителят да следи действието. Тя не изисква изкуствено еднаква светлина във всяка посока."}}]},{"module":"s02-m04","lesson":"pv04-15","source_hash":"9349394d30d224925ab82c7ce8b1cc1b","objective":"Ще проверяваш творческата визия върху различни кадри, а не само върху най-красивия. Ще избираш контролни изображения с лице, продукт и трудно осветление. В края ще имаш кратък монтаж, който показва дали стилът пази важната информация през целия разказ.","hook":"Твоят любим кадър изглежда отлично; следващият със светла риза и тъмна кожа се разпада.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще проверяваш творческата визия върху различни кадри, а не само върху най-красивия. Ще избираш контролни изображения с лице, продукт и трудно осветление. В края ще имаш кратък монтаж, който показва дали стилът пази важната информация през целия разказ.","deliverable":"Избери три свои различни кадъра и направи 20-секундна последователност. Сравни чиста и умерено стилизирана версия. Не използвай един и същ лесен кадър като доказателство за целия монтаж.","check":"Лицето, надписът и важният детайл в сянката се запазват и в най-трудния план. Визията не добавя пречещи ленти или шум. При провал я отслабваш или поправяш конкретния кадър."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Твоят любим кадър изглежда отлично; следващият със светла риза и тъмна кожа се разпада."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Градиент — плавен преход между цветове или яркости. Ленти — видими стъпала в иначе плавния преход. Времева линия — подредените кадри и звук в монтажния проект.\n\nДобрата визия трябва да издържи различни лица, материали и планове в една история.\n\nОстави отделни етапи за техническа корекция и творческа визия. Избери два или три контролни кадъра: лице, продукт и крайно осветление. Настрой визията върху тях, вместо да копираш силна настройка по цялата времева линия."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Насищането на сенките и цветовете във високите светлини често изглеждат впечатляващи в един стоп кадър, но губят информация в движение. Следи за клипинг, шум и ленти при силни градиенти. Сравни преди/след на финален размер и в кратка последователност, защото усещането за стил се променя при монтаж.\n\nГраница на решението: Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Коригирай технически три различни контролни кадъра.\n2. Избери каква промяна подкрепя посланието.\n3. Приложи умерена визия и коригирай отделните кадри.\n4. Изнеси кратка последователност и провери най-трудния кадър."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Филм за работилница включва слънчев вход, тъмно интервю и близък план на меден продукт. Силният стил прави продукта червен и убива сенките.\n\nРешение: Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение.\n\nКакво да провериш: Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение. Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени.","label":"Как го поправяш"},"before":{"text":"Показваш само слънчевия вход и обявяваш визията за завършена.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Избери три свои различни кадъра и направи 20-секундна последователност. Сравни чиста и умерено стилизирана версия. Не използвай един и същ лесен кадър като доказателство за целия монтаж.\n\nПровери резултата: Лицето, надписът и важният детайл в сянката се запазват и в най-трудния план. Визията не добавя пречещи ленти или шум. При провал я отслабваш или поправяш конкретния кадър.\n\nПримерна работна бележка: Контролните кадри са лице, опаковка и сцена с дълбока сянка. Стилът работи на първите два, но губи надписа в третия; отслабвам го там или поправям причината преди стилизацията. Предавам кратка сравнима последователност.\n\nАко не е изпълнено: Ако трудният кадър се разпада, не го изключвай от проверката. Намери дали дефектът е в източника, техническата корекция или визията. Пази чистата версия за сравнение."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Кратка последователност с различни контролни и трудни кадри."},{"id":"b","label":"Един стоп кадър при силно увеличена наситеност."},{"id":"c","label":"Преглед само на първата сцена след копиране на филтъра."}],"question":"Кой тест е достатъчно показателен за обща визия?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Кратка последователност с различни контролни и трудни кадри. Лицето, надписът и важният детайл в сянката се запазват и в най-трудния план. Визията не добавя пречещи ленти или шум. При провал я отслабваш или поправяш конкретния кадър."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Филм за работилница включва слънчев вход, тъмно интервю и близък план на меден продукт. Силният стил прави продукта червен и убива сенките.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Одобрявам стила по слънчевия вход и оставям продукта непроверен."},{"id":"b","label":"Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение."},{"id":"c","label":"Увеличавам наситеността, за да върна детайл в вече затворените сенки."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение.\n\nКакво да провериш: Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Копирай една силна настройка върху всичко и прегледай само първия кадър."},{"id":"c","label":"Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Избери три свои различни кадъра и направи 20-секундна последователност. Сравни чиста и умерено стилизирана версия. Не използвай един и същ лесен кадър като доказателство за целия монтаж.","takeaways":["Добрата визия трябва да издържи различни лица, материали и планове в една история.","Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение.","Провери: Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Приложи умерена визия и коригирай отделните кадри."},{"id":"s1","text":"Коригирай технически три различни контролни кадъра."},{"id":"s4","text":"Изнеси кратка последователност и провери най-трудния кадър."},{"id":"s2","text":"Избери каква промяна подкрепя посланието."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Коригирай технически три различни контролни кадъра. → Избери каква промяна подкрепя посланието. → Приложи умерена визия и коригирай отделните кадри. → Изнеси кратка последователност и провери най-трудния кадър."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Появява се архивен клип от друг фотоапарат.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Копирай една силна настройка върху всичко и прегледай само първия кадър."},{"id":"b","label":"Нормализирай го към работната схема и провери дали стилът не разкрива шум или клипинг; ако трябва, използвай по-лек вариант."},{"id":"c","label":"Показваш само слънчевия вход и обявяваш визията за завършена."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Нормализирай го към работната схема и провери дали стилът не разкрива шум или клипинг; ако трябва, използвай по-лек вариант. Лицето, надписът и важният детайл в сянката се запазват и в най-трудния план. Визията не добавя пречещи ленти или шум. При провал я отслабваш или поправяш конкретния кадър."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"По-силната промяна е видима, но това не означава, че е по-полезна за бизнеса или по-убедителна за зрителя."}}]},{"module":"s02-m04","lesson":"pv04-16","source_hash":"bbbaf5572f0af2185bfda12702679e50","objective":"Ще разбираш как по-хладен фон и по-топъл основен обект могат да дадат отделяне. Ще запазваш цвета на кожа, бели предмети и опаковки и ще можеш да отхвърлиш стила, когато той не служи на задачата. Няма да използваш популярната комбинация като знак за професионализъм сама по себе си.","hook":"Популярна визия може да превърне всяко лице в един и същ оранжев тон.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще разбираш как по-хладен фон и по-топъл основен обект могат да дадат отделяне. Ще запазваш цвета на кожа, бели предмети и опаковки и ще можеш да отхвърлиш стила, когато той не служи на задачата. Няма да използваш популярната комбинация като знак за професионализъм сама по себе си.","deliverable":"Направи неутрална и лека стилизирана версия на същия кратък материал. При липса на локални инструменти избери по-умерена обща корекция, вместо да оцветяваш всички сенки.","check":"Бялото не става неволно синьо, кожата пази текстура, а фирменият цвят остава разпознаваем. Изборът е свързан с посланието, не с етикет „професионално“."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Популярна визия може да превърне всяко лице в един и същ оранжев тон."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Teal — синьо-зелен цвят. Локална корекция — промяна на избрана област или диапазон. Цветно отделяне — разлика, която прави главния обект по-разпознаваем спрямо фона.\n\nТопъл субект и по-студен фон може да дадат отделяне, ако сцената и марката позволяват това.\n\nЗапочни с чиста корекция и избери ограничени области, вместо да завъртиш глобално всички сенки към синьо. Пази белите предмети и корпоративните цветове; не всяка сянка е синя и не всяка кожа трябва да е оранжева."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Избери кадър с лице, кадър с продукт и кадър със смесена светлина. Изгради лек вариант, после силен само за сравнение. При близък план следи порите, текстурата на косата и естествената разлика между хората. Ако корекцията работи само когато увеличиш сатурацията до край, тя вероятно не решава историята.\n\nГраница на решението: Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Нормализирай входа и избери референтна сцена.\n2. Отдели фон и субект с умерени промени.\n3. Провери кожа, бели предмети и фирмени цветове.\n4. Прегледай срезовете на целевия екран и запази по-честния вариант."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Видео за лекарски кабинет получава синкави сенки и силно оранжеви лица. Клиентът казва, че изглежда като екшън, а не като доверен разговор.\n\nРешение: Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието.\n\nКакво да провериш: Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието. Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо.","label":"Как го поправяш"},"before":{"text":"Защитаваш стила с аргумента, че така изглеждат „професионалните видеа“.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Направи неутрална и лека стилизирана версия на същия кратък материал. При липса на локални инструменти избери по-умерена обща корекция, вместо да оцветяваш всички сенки.\n\nПровери резултата: Бялото не става неволно синьо, кожата пази текстура, а фирменият цвят остава разпознаваем. Изборът е свързан с посланието, не с етикет „професионално“.\n\nПримерна работна бележка: Неутралната версия пази бялата чаша и синята опаковка. Леката синьо-зелена промяна във фона отделя главния обект, но силната обща промяна оцветява чашата. За продукта избирам умерения или неутралния вариант.\n\nАко не е изпълнено: При липса на локални инструменти намали общия ефект. Провери лицето, белите предмети и фирмения цвят поотделно. Изразителният контраст е полезен само ако важната информация остава вярна."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Когато не е достатъчно силен да личи във всяка сянка."},{"id":"b","label":"Когато не съвпада с любимия филтър на автора."},{"id":"c","label":"Когато променя важния цвят или противоречи на задачата."}],"question":"Кога трябва да отхвърлиш teal–оранжево за продуктова версия?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Когато променя важния цвят или противоречи на задачата. Бялото не става неволно синьо, кожата пази текстура, а фирменият цвят остава разпознаваем. Изборът е свързан с посланието, не с етикет „професионално“."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Видео за лекарски кабинет получава синкави сенки и силно оранжеви лица. Клиентът казва, че изглежда като екшън, а не като доверен разговор.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието."},{"id":"b","label":"Запазвам силно оранжевите лица, защото цветното отделяне е видимо."},{"id":"c","label":"Оцветявам всички бели повърхности синьо, за да направя палитрата еднаква."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието.\n\nКакво да провериш: Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Оцвети всички тъмни пиксели в синьо и всички средни в оранжево."},{"id":"b","label":"Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Направи неутрална и лека стилизирана версия на същия кратък материал. При липса на локални инструменти избери по-умерена обща корекция, вместо да оцветяваш всички сенки.","takeaways":["Топъл субект и по-студен фон може да дадат отделяне, ако сцената и марката позволяват това.","Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието.","Провери: Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Провери кожа, бели предмети и фирмени цветове."},{"id":"s1","text":"Нормализирай входа и избери референтна сцена."},{"id":"s4","text":"Прегледай срезовете на целевия екран и запази по-честния вариант."},{"id":"s2","text":"Отдели фон и субект с умерени промени."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Нормализирай входа и избери референтна сцена. → Отдели фон и субект с умерени промени. → Провери кожа, бели предмети и фирмени цветове. → Прегледай срезовете на целевия екран и запази по-честния вариант."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Същият материал ще се ползва в продуктова реклама с синя опаковка.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Пази разпознаваемия син цвят на продукта и оцени дали този стил изобщо е подходящ за продуктова версия."},{"id":"b","label":"Защитаваш стила с аргумента, че така изглеждат „професионалните видеа“."},{"id":"c","label":"Оцвети всички тъмни пиксели в синьо и всички средни в оранжево."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Пази разпознаваемия син цвят на продукта и оцени дали този стил изобщо е подходящ за продуктова версия. Бялото не става неволно синьо, кожата пази текстура, а фирменият цвят остава разпознаваем. Изборът е свързан с посланието, не с етикет „професионално“."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Творческа роля като водач може да насочи тона на разказа, но не диктува цвета. Проверяваме показаното действие, четливостта и точността."}}]},{"module":"s02-m04","lesson":"pv04-17","source_hash":"80bfbbc8690c559feea0b88056f9f88f","objective":"Ще свържеш решенията за светлина и цвят в малък завършен проект. Ще направиш три сравними версии и ще избираш по предварително определени критерии. Резултатът е комплект от реални кратки файлове и проверка, която можеш сам да повториш.","hook":"Три филтъра върху различни кадри не доказват, че можеш да контролираш светлината.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще свържеш решенията за светлина и цвят в малък завършен проект. Ще направиш три сравними версии и ще избираш по предварително определени критерии. Резултатът е комплект от реални кратки файлове и проверка, която можеш сам да повториш.","deliverable":"Използвай собствен предмет като заместител на учебния продукт. А е базов запис; Б променя един светлинен фактор; В е умерена визия върху технически поправен вариант. Обозначи заместителя; не го представяй като истински продукт на пекарната.","check":"Има три сравними файла, четим важен предмет и описани промени. Сравнението на светлина използва съпоставими записи; сравнението на стил използва същия източник. Самооценката не е автоматична оценка на художественото качество."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Три филтъра върху различни кадри не доказват, че можеш да контролираш светлината."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Контролирано сравнение — описано сравнение с ясни променени условия. Експорт — изнесен файл от редактора. Критерий за приемане — конкретното условие, което файлът трябва да изпълни.\n\nИзползвай един и същ кратък разговор и запази ясна връзка между светлината на терен, техническата корекция и стила.\n\nВерсия А показва чистата сцена; Б променя светлината или отраженията; В добавя умерена цветна визия след нормализиране. Постави един и същ важен предмет и лице във всички сравнения."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Запиши експонация, баланс, позиция на източника и какво си променил между вариантите. Не подменяй речта и кадрирането толкова, че сравнението да стане нечестно. Проверявай клипинг, кожа, отблясък и бранд цвят върху експортирани файлове. При провал избери варианта, който изпълнява задачата, дори да е по-скромен.\n\nГраница на решението: Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Заснеми базов кратък кадър и контролен still.\n2. Промени един светлинен фактор и запиши втори вариант.\n3. Коригирай технически, после направи отделна стилова версия.\n4. Изнеси A/B/C и сравни по предварително записани критерии."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Малка сладкарница иска 20 секунди за нов продукт. Версия А е четима, Б добавя контраст със черен картон, В прави продукта неестествено червен.\n\nРешение: Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния.\n\nКакво да провериш: Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния. Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат.","label":"Как го поправяш"},"before":{"text":"Избираш В, защото най-силно привлича окото, без да погледнеш истинския продукт.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Използвай собствен предмет като заместител на учебния продукт. А е базов запис; Б променя един светлинен фактор; В е умерена визия върху технически поправен вариант. Обозначи заместителя; не го представяй като истински продукт на пекарната.\n\nПровери резултата: Има три сравними файла, четим важен предмет и описани промени. Сравнението на светлина използва съпоставими записи; сравнението на стил използва същия източник. Самооценката не е автоматична оценка на художественото качество.\n\nПримерна работна бележка: А: базов 10-секунден запис. Б: същата сцена с един променен светлинен фактор. В: умерена визия върху технически поправения Б. Записвам отделно сравнението А–Б за светлина и Б–В за стил; обозначавам домашния предмет като заместител.\n\nАко не е изпълнено: Ако вариантите сменят едновременно съдържание и стил, повтори сравнимата част. Ако имаш само снимки на екрана, изнеси и отвори действителните файлове. Финалният избор трябва да е свързан с видим критерий."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Сменям едновременно реплика, кадриране, предмет и цветен филтър."},{"id":"b","label":"Отделям промяната на светлина от стилизацията и пазя сравнимо съдържание."},{"id":"c","label":"Предавам най-ярката версия без другите два файла."}],"question":"Коя промяна прави сравнението честно?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Отделям промяната на светлина от стилизацията и пазя сравнимо съдържание. Има три сравними файла, четим важен предмет и описани промени. Сравнението на светлина използва съпоставими записи; сравнението на стил използва същия източник. Самооценката не е автоматична оценка на художественото качество."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Малка сладкарница иска 20 секунди за нов продукт. Версия А е четима, Б добавя контраст със черен картон, В прави продукта неестествено червен.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Избирам най-червения продукт, без да го сравня с действителния предмет."},{"id":"b","label":"Показвам само екранни снимки от различни приложения като сравнение на финални файлове."},{"id":"c","label":"Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния.\n\nКакво да провериш: Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Предай само най-ефектния файл без контролно сравнение."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Използвай собствен предмет като заместител на учебния продукт. А е базов запис; Б променя един светлинен фактор; В е умерена визия върху технически поправен вариант. Обозначи заместителя; не го представяй като истински продукт на пекарната.","takeaways":["Използвай един и същ кратък разговор и запази ясна връзка между светлината на терен, техническата корекция и стила.","Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния.","Провери: Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Коригирай технически, после направи отделна стилова версия."},{"id":"s1","text":"Заснеми базов кратък кадър и контролен still."},{"id":"s4","text":"Изнеси A/B/C и сравни по предварително записани критерии."},{"id":"s2","text":"Промени един светлинен фактор и запиши втори вариант."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Заснеми базов кратък кадър и контролен still. → Промени един светлинен фактор и запиши втори вариант. → Коригирай технически, после направи отделна стилова версия. → Изнеси A/B/C и сравни по предварително записани критерии."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът сменя целта: видеото трябва да служи и като продуктова инструкция.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Избираш В, защото най-силно привлича окото, без да погледнеш истинския продукт."},{"id":"b","label":"Предай само най-ефектния файл без контролно сравнение."},{"id":"c","label":"Прегледай трите версии за точност на продукта и четимост на демонстрацията; избери или адаптирай най-ясната."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Прегледай трите версии за точност на продукта и четимост на демонстрацията; избери или адаптирай най-ясната. Има три сравними файла, четим важен предмет и описани промени. Сравнението на светлина използва съпоставими записи; сравнението на стил използва същия източник. Самооценката не е автоматична оценка на художественото качество."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"За учебния избор можеш да използваш чеклиста без оценител. Реакция на клиент или зрител би дала допълнителни данни, но не се изисква за преминаване на задачите."}}]},{"module":"s02-m05","lesson":"pv05-01","source_hash":"9e1fcac37f8842b742bca1264fd49e2b","objective":"Ще проверяваш мястото със запис на истинска реч, преди да започнеш интервю. Ще различаваш постоянен шум, ехо и внезапен звук и ще избираш промяна, която действително помага на думите. Резултатът е кратка използваема проба и проверен резервен вариант, вместо надежда за поправка след снимането.","hook":"Изображението е остро, но хладилникът заглушава цялото интервю.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще проверяваш мястото със запис на истинска реч, преди да започнеш интервю. Ще различаваш постоянен шум, ехо и внезапен звук и ще избираш промяна, която действително помага на думите. Резултатът е кратка използваема проба и проверен резервен вариант, вместо надежда за поправка след снимането.","deliverable":"С наличен телефон запиши една и съща кратка реплика на две безопасни места. Остави по 10 секунди без говор. Слушай при сравнима сила и отбележи кое пречи на думите, а не кое помещение изглежда по-красиво.","check":"Същата ключова реплика се разбира без напрягане; след думите не остава пречещ отзвук. Пробата е при реален шум. Ако звукът е непостоянен, краткият тест не се приема за гаранция."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Изображението е остро, но хладилникът заглушава цялото интервю."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Постоянен шум — звук като вентилатор, който продължава под речта. Отзвук — отражения на гласа от помещението. Звук от мястото — запис на средата без говор, полезен за последователни паузи.\n\nЗатвори очи и слушай мястото за глас, тишина и внезапни звуци, преди да фиксираш кадъра.\n\nСлушай с надеждни слушалки директно от записващото устройство, не само от монитора на камерата без аудио. Отдели постоянен шум, отражения на стаята и случайни събития като врата или телефон."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Запиши 20 секунди нормална реч и поне 10 секунди тишина на същото място. Сравни какво се чува при паузите и под думите. Реверберацията не се решава със същия бутон като постоянен шум; най-евтината поправка често е да доближиш микрофона и да смениш позицията. Ако екипът трябва да остане на мястото, отбележи рисковите звуци в снимачния план.\n\nГраница на решението: Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Слушай помещението в тишина и назови три конкретни звука.\n2. Запиши кратка реч и тишина с избрания микрофон.\n3. Пусни пробата през слушалки от устройството.\n4. Промени място или позиция и повтори при същия глас."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Собственик на фурна говори ясно, но по време на пробата фурната включва вентилатор на всеки няколко минути.\n\nРешение: Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба.\n\nКакво да провериш: В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба. В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите.","label":"Как го поправяш"},"before":{"text":"Пропускаш пробата, защото шумът ще се „махне с AI“.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"С наличен телефон запиши една и съща кратка реплика на две безопасни места. Остави по 10 секунди без говор. Слушай при сравнима сила и отбележи кое пречи на думите, а не кое помещение изглежда по-красиво.\n\nПровери резултата: Същата ключова реплика се разбира без напрягане; след думите не остава пречещ отзвук. Пробата е при реален шум. Ако звукът е непостоянен, краткият тест не се приема за гаранция.\n\nПримерна работна бележка: В място А вентилаторът покрива окончанията. В Б същата реплика се разбира, а паузата показва по-малко пречещ шум. Избирам Б за текущата проба и отбелязвам кога може да се появи периодичен шум.\n\nАко не е изпълнено: Ако по-силният файл изглежда по-добър, изравни прослушването и сравни пак. Ако шумът е непостоянен, провери при реалния му цикъл или уговори друго време; пази функциите на помещението."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"За да чуя как шумът и помещението действат върху истинските думи."},{"id":"b","label":"За да избера най-силно звучащия файл без изравняване на прослушването."},{"id":"c","label":"За да потвърдя, че всеки по-късен шум ще може да се премахне."}],"question":"Защо записваш реч и пауза на планираното място?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"За да чуя как шумът и помещението действат върху истинските думи. Същата ключова реплика се разбира без напрягане; след думите не остава пречещ отзвук. Пробата е при реален шум. Ако звукът е непостоянен, краткият тест не се приема за гаранция."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Собственик на фурна говори ясно, но по време на пробата фурната включва вентилатор на всеки няколко минути.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Оставям същата позиция, защото шумът не се е чул в началото на пробата."},{"id":"b","label":"Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба."},{"id":"c","label":"Усилвам говорния канал, без да уговоря шумния цикъл на фурната."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба.\n\nКакво да провериш: В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Усили гласовия канал до максимум, за да скриеш реверберацията."},{"id":"c","label":"Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"С наличен телефон запиши една и съща кратка реплика на две безопасни места. Остави по 10 секунди без говор. Слушай при сравнима сила и отбележи кое пречи на думите, а не кое помещение изглежда по-красиво.","takeaways":["Затвори очи и слушай мястото за глас, тишина и внезапни звуци, преди да фиксираш кадъра.","Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба.","Провери: В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Пусни пробата през слушалки от устройството."},{"id":"s1","text":"Слушай помещението в тишина и назови три конкретни звука."},{"id":"s4","text":"Промени място или позиция и повтори при същия глас."},{"id":"s2","text":"Запиши кратка реч и тишина с избрания микрофон."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Слушай помещението в тишина и назови три конкретни звука. → Запиши кратка реч и тишина с избрания микрофон. → Пусни пробата през слушалки от устройството. → Промени място или позиция и повтори при същия глас."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Вратата към улицата трябва да остане отворена за работата на обекта.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Усили гласовия канал до максимум, за да скриеш реверберацията."},{"id":"b","label":"Промени ориентацията на микрофона и времето на запис; ако шумът заглушава думите, уговори друго място."},{"id":"c","label":"Пропускаш пробата, защото шумът ще се „махне с AI“."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Промени ориентацията на микрофона и времето на запис; ако шумът заглушава думите, уговори друго място. Същата ключова реплика се разбира без напрягане; след думите не остава пречещ отзвук. Пробата е при реален шум. Ако звукът е непостоянен, краткият тест не се приема за гаранция."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Думите носят предложението на бизнеса. AI почистване е възможна допълнителна обработка; наличието на такава функция не доказва възстановяване на липсваща реплика."}}]},{"module":"s02-m05","lesson":"pv05-02","source_hash":"187b888f440577b5150940599993b11f","objective":"Ще избираш микрофон според дистанцията, движението и дрехите. Ще проверяваш дали петличката се търка и дали насоченият микрофон действително е близо до гласа. Не е нужно да притежаваш три вида микрофони: първата задача може да покаже ефекта на дистанцията с един телефон.","hook":"Скъп насочен микрофон от три метра записва по-ясно стаята, отколкото гласа.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще избираш микрофон според дистанцията, движението и дрехите. Ще проверяваш дали петличката се търка и дали насоченият микрофон действително е близо до гласа. Не е нужно да притежаваш три вида микрофони: първата задача може да покаже ефекта на дистанцията с един телефон.","deliverable":"Запиши една фраза с телефона от по-близка и по-далечна позиция, при същия говор и място. Ако имаш външен микрофон, повтори при истинското движение и облекло. Пази безопасна позиция на устройството.","check":"Речта остава разбираема при цялото движение. Няма търкане на плат върху важната дума. Изравняваш силата на прослушване, преди да избереш по-добрия вариант."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Скъп насочен микрофон от три метра записва по-ясно стаята, отколкото гласа."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Петличка — малък микрофон върху дрехата. Бум — поставяне на микрофон близо до човека извън кадър. Насочен микрофон — приема различните посоки с различна чувствителност; не е увеличение на далечен звук.\n\nПоложението на микрофона и прякото звучене на гласа често имат по-голям ефект от името на модела.\n\nПетличката следва движещ се говорител, но може да търка дреха. Бумът стои извън кадър и дава естествен глас, ако може да се държи близо. Вграденият микрофон е резервен или синхронизиращ източник, когато камерата е далеч."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"При петличка направи тест при истинските движения и дрехи; проверявай триене, бижута и проводник. При бум провери дали микрофонът остава насочен към устата, а не към отразяваща стена. Ако снимачният план се променя, резервен канал или втори запис може да спаси интервюто само ако е бил проверен преди снимките.\n\nГраница на решението: Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Опиши движение, кадриране и облекло.\n2. Постави наличния микрофон възможно най-близо без да влиза в кадър.\n3. Запиши реч при реалните движения и слушай за триене.\n4. Избери основен и проверен резервен източник."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Говорител в работилница се навежда над маса. Петличката е скрита под яке, а насоченият микрофон е закрепен върху камерата на два метра.\n\nРешение: Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение.\n\nКакво да провериш: В цялото навеждане речта остава разбираема и няма силно търкане на плат."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение. В цялото навеждане речта остава разбираема и няма силно търкане на плат.","label":"Как го поправяш"},"before":{"text":"Оставяш микрофона на камерата като „професионален shotgun“ и приемаш кухия звук.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Запиши една фраза с телефона от по-близка и по-далечна позиция, при същия говор и място. Ако имаш външен микрофон, повтори при истинското движение и облекло. Пази безопасна позиция на устройството.\n\nПровери резултата: Речта остава разбираема при цялото движение. Няма търкане на плат върху важната дума. Изравняваш силата на прослушване, преди да избереш по-добрия вариант.\n\nПримерна работна бележка: По-близкият телефон пази съгласните по-ясно при същия говор и стая. При налична петличка проверявам и навеждането: ако якето търка върху ключовата дума, сменям безопасно закрепването и правя нова проба.\n\nАко не е изпълнено: Ако близкият запис е изкривен, провери допустимите нива и позицията според устройството. Ако има търкане, поправи закрепването преди обработка. Увеличаването на далечен сигнал усилва и стаята."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Списък с по-скъпи модели, без запис в същото помещение."},{"id":"b","label":"Сравнение на различни говорители при различна сила на плейъра."},{"id":"c","label":"Проба с истинските дрехи, дистанция и движения на говорителя."}],"question":"Кое наблюдение е най-полезно при избор на микрофон за движение?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Проба с истинските дрехи, дистанция и движения на говорителя. Речта остава разбираема при цялото движение. Няма търкане на плат върху важната дума. Изравняваш силата на прослушване, преди да избереш по-добрия вариант."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Говорител в работилница се навежда над маса. Петличката е скрита под яке, а насоченият микрофон е закрепен върху камерата на два метра.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение."},{"id":"b","label":"Оставям микрофона на камерата далече и повишавам чувствителността."},{"id":"c","label":"Закрепвам петличката по-плътно под якето, без проба при навеждане."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение.\n\nКакво да провериш: В цялото навеждане речта остава разбираема и няма силно търкане на плат."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Повиши чувствителността на камерата, за да компенсираш далечния микрофон."},{"id":"b","label":"Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Запиши една фраза с телефона от по-близка и по-далечна позиция, при същия говор и място. Ако имаш външен микрофон, повтори при истинското движение и облекло. Пази безопасна позиция на устройството.","takeaways":["Положението на микрофона и прякото звучене на гласа често имат по-голям ефект от името на модела.","Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение.","Провери: В цялото навеждане речта остава разбираема и няма силно търкане на плат."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Запиши реч при реалните движения и слушай за триене."},{"id":"s1","text":"Опиши движение, кадриране и облекло."},{"id":"s4","text":"Избери основен и проверен резервен източник."},{"id":"s2","text":"Постави наличния микрофон възможно най-близо без да влиза в кадър."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Опиши движение, кадриране и облекло. → Постави наличния микрофон възможно най-близо без да влиза в кадър. → Запиши реч при реалните движения и слушай за триене. → Избери основен и проверен резервен източник."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Говорителят сменя якето с риза, която шумоли при допир.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Тествай ново място за петличката или използвай близък бум и избери след реален запис."},{"id":"b","label":"Оставяш микрофона на камерата като „професионален shotgun“ и приемаш кухия звук."},{"id":"c","label":"Повиши чувствителността на камерата, за да компенсираш далечния микрофон."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Тествай ново място за петличката или използвай близък бум и избери след реален запис. Речта остава разбираема при цялото движение. Няма търкане на плат върху важната дума. Изравняваш силата на прослушване, преди да избереш по-добрия вариант."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Заемането на подходящ микрофон може да е разумен тест. Покупката следва установен проблем, а не престиж на оборудването."}}]},{"module":"s02-m05","lesson":"pv05-03","source_hash":"fcdf8a1f9dfa3a34f5bde05f7f4fcb6b","objective":"Ще проверяваш най-силната реплика, смеха и тихия пасаж, преди дългия запис. Ще разбираш къде може да се претовари звукът и кога намаляването на файла действително помага. Ще различаваш възможностите на 32-bit float от ограничението на микрофон, предавател или аналогов вход.","hook":"Силната реплика звучи изкривено. Преди да намаляваш файла, установи дали проблемът е възникнал при входа или само при възпроизвеждането.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще проверяваш най-силната реплика, смеха и тихия пасаж, преди дългия запис. Ще разбираш къде може да се претовари звукът и кога намаляването на файла действително помага. Ще различаваш възможностите на 32-bit float от ограничението на микрофон, предавател или аналогов вход.","deliverable":"Запиши кратко собствен тихо и нормално силно изречение, без да викаш опасно близо до микрофона. Прослушай оригинала. При налично ръчно управление направи втори тест с подходящ запас според устройството.","check":"Силната дума не е изкривена, а тихият пасаж се разбира. При 32-bit float провери дали проблемът е само при възпроизвеждане или е възникнал преди файла. По-тихото възпроизвеждане само по себе си не доказва възстановена информация."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Силната реплика звучи изкривено. Преди да намаляваш файла, установи дали проблемът е възникнал при входа или само при възпроизвеждането."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Gain — усилване във входната верига. Клипинг — изкривяване при надвишаване на допустимото ниво на определен етап. Резервен канал — отделен проверен запис, а не второ име на същия повреден сигнал. 32-bit float — числов формат за аудиоданни с голям диапазон; възможностите на записа зависят и от устройството.\n\nПровери най-силната очаквана реплика и прослушай пробата от началото до края.\n\nПри устройства с входно усилване gain определя нивото на този етап. Ако микрофон, аналогов вход или безжичен предавател се претовари, по-късният файлов формат не връща изгубената информация. 32-bit float дава гъвкавост при обработката на подходящ запис, но хардуерната верига продължава да има ограничения. При някои такива рекордери няма обичайна настройка за входен gain; следвай конкретното ръководство."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Пробата съдържа тихия пасаж и най-силната реалистична реплика, без опасно викане до микрофона. При обичаен запис гледай нивата и слушай за изкривяване. При 32-bit float разграничавай претоварване при възпроизвеждане от повреден сигнал преди файла. Например ръководството на Zoom F3 описва намаляване на нивото на float файл при съвместима обработка, но задава и максимални входни нива на устройството.\n\nАко използваш резервен канал, провери как действително се записва и го прослушай. Второ име на един изкривен сигнал не създава резерв. Важно е къде възниква проблемът, а не сравнение със запис в Log при видео.\n\nВ решения случай и новия казус по-долу устройството има регулируемо входно ниво. Затова можеш да провериш и него. При рекордер без тази настройка следваш ръководството, вместо да търсиш несъществуващ плъзгач.\n\nГраница на решението: 32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Провери захранване, вход и място на микрофона.\n2. Провери запаса и допустимия вход според устройството с най-силната реалистична реплика.\n3. Запиши и прослушай силен и тих пасаж.\n4. Провери резервния канал и запази настройката преди интервю."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Човек говори тихо в началото, после разказва развълнувано. Първите проби са добри, но при силната фраза звукът пука.\n\nРешение: Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал.\n\nКакво да провериш: Силната и тихата реплика се разбират без чуваемо изкривяване. При float файл първо провери съвместимото възпроизвеждане; хардуерното претоварване не се обявява за поправено само с по-тих изход."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал. Силната и тихата реплика се разбират без чуваемо изкривяване. При float файл първо провери съвместимото възпроизвеждане; хардуерното претоварване не се обявява за поправено само с по-тих изход.","label":"Как го поправяш"},"before":{"text":"Намаляваш плъзгача в монтажа и обявяваш отрязаната фраза за поправена.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Запиши кратко собствен тихо и нормално силно изречение, без да викаш опасно близо до микрофона. Прослушай оригинала. При налично ръчно управление направи втори тест с подходящ запас според устройството.\n\nПровери резултата: Силната дума не е изкривена, а тихият пасаж се разбира. При 32-bit float провери дали проблемът е само при възпроизвеждане или е възникнал преди файла. По-тихото възпроизвеждане само по себе си не доказва възстановена информация.\n\nПримерна работна бележка: Обичайният входен запис изкривява най-силната дума: правя нов тест с подходящо по-ниско входно усилване. При истински 32-bit float файл пробвам съвместимо възпроизвеждане с намален изход; ако изкривяването остава от микрофона или предавателя, нужен е нов запис.\n\nАко не е изпълнено: Установи къде е възникнал дефектът. Следвай ръководството: някои float рекордери работят без обичайния gain. По-тихото възпроизвеждане е проверка, а не доказателство, че повредена входна верига е поправена."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Всяко пукане изчезва след намаляване на силата в монтажната програма."},{"id":"b","label":"Може да даде гъвкавост на файла, но не поправя претоварен микрофон или предавател."},{"id":"c","label":"Позволява да не проверяваме устройството или съвместимостта на редактора."}],"question":"Кое твърдение за 32-bit float е вярно?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Може да даде гъвкавост на файла, но не поправя претоварен микрофон или предавател. Силната дума не е изкривена, а тихият пасаж се разбира. При 32-bit float провери дали проблемът е само при възпроизвеждане или е възникнал преди файла. По-тихото възпроизвеждане само по себе си не доказва възстановена информация."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Човек говори тихо в началото, после разказва развълнувано. Първите проби са добри, но при силната фраза звукът пука.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Намалявам само нивото на вече изкривения запис и не търся мястото на претоварване."},{"id":"b","label":"Разчитам на резервен канал, който не е бил прослушан."},{"id":"c","label":"Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал.\n\nКакво да провериш: Силната и тихата реплика се разбират без чуваемо изкривяване. При float файл първо провери съвместимото възпроизвеждане; хардуерното претоварване не се обявява за поправено само с по-тих изход."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Пиши „Log аудио“ в инструкциите и разчитай файловият формат да възстанови клипинг."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Запиши кратко собствен тихо и нормално силно изречение, без да викаш опасно близо до микрофона. Прослушай оригинала. При налично ръчно управление направи втори тест с подходящ запас според устройството.","takeaways":["Провери най-силната очаквана реплика и прослушай пробата от началото до края.","Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал.","Провери: Силната и тихата реплика се разбират без чуваемо изкривяване. При float файл първо провери съвместимото възпроизвеждане; хардуерното претоварване не се обявява за поправено само с по-тих изход."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Запиши и прослушай силен и тих пасаж."},{"id":"s1","text":"Провери захранване, вход и място на микрофона."},{"id":"s4","text":"Провери резервния канал и запази настройката преди интервю."},{"id":"s2","text":"Провери запаса и допустимия вход според устройството с най-силната реалистична реплика."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. 32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Провери захранване, вход и място на микрофона. → Провери запаса и допустимия вход според устройството с най-силната реалистична реплика. → Запиши и прослушай силен и тих пасаж. → Провери резервния канал и запази настройката преди интервю."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Интервюто се мести до шумна машина и човекът започва да говори по-силно.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Намаляваш плъзгача в монтажа и обявяваш отрязаната фраза за поправена."},{"id":"b","label":"Пиши „Log аудио“ в инструкциите и разчитай файловият формат да възстанови клипинг."},{"id":"c","label":"Настрой входа и позицията наново по новата силна реплика, прослушай през слушалки и провери резервния запис."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Настрой входа и позицията наново по новата силна реплика, прослушай през слушалки и провери резервния запис. Силната дума не е изкривена, а тихият пасаж се разбира. При 32-bit float провери дали проблемът е само при възпроизвеждане или е възникнал преди файла. По-тихото възпроизвеждане само по себе си не доказва възстановена информация."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Настройките зависят от устройството. При някои 32-bit float рекордери няма обичайно регулиране на входния gain; следвай реалното ръководство и ограниченията на входа."}}]},{"module":"s02-m05","lesson":"pv05-04","source_hash":"9fedf65257dac409c99d39fa4f3dd2d6","objective":"Ще сравняваш две места по разбираемост на гласа. Ще разбереш защо тихият коридор може да звучи по-зле от стая с меки повърхности. Резултатът е избор по кратък запис и план за периодичните шумове, без да променяш работата на обекта опасно.","hook":"Празна тиха зала звучи като тунел, докато малък шумен офис може да даде по-четима реч.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще сравняваш две места по разбираемост на гласа. Ще разбереш защо тихият коридор може да звучи по-зле от стая с меки повърхности. Резултатът е избор по кратък запис и план за периодичните шумове, без да променяш работата на обекта опасно.","deliverable":"Запиши фраза и пет секунди пауза в две налични стаи. Пази еднаква дистанция. Слушай окончанията на думите при еднаква сила. Не спирай чуждо оборудване и вентилация за учебния опит.","check":"Избраният файл пази окончанията и няма пречещо наслагване на отзвук. Периодичен шум се отбелязва. Преместване или доближаване се приема само след нова проба."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Празна тиха зала звучи като тунел, докато малък шумен офис може да даде по-четима реч."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Акустика — как помещението влияе на звука. Пряк звук — гласът, който достига директно до микрофона. Отражения — същият звук, върнат от стени, под или таван.\n\nГледай едновременно съотношението на гласа към шума и колко дълго отекват думите.\n\nГолемите голи повърхности връщат речта към микрофона. Мека мебел, завеси и близък микрофон често подобряват разбираемостта. Изключването на климатик може да помогне само ако е позволено и безопасно за мястото."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Направи проба със същия човек и микрофон в две възможни позиции. Пази разстоянието до устата сравнимо и не оценявай по сила на плейъра. Отбележи периодични звуци като каса, превозно средство или хладилник. Ако шумът не може да се спре, търси място, където близкият глас преобладава и където имаш контрол върху паузите.\n\nГраница на решението: Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Слушай постоянното и периодичното в две локации.\n2. Запиши една и съща фраза от еднаква дистанция.\n3. Прослушай думите и паузите при изравнена сила.\n4. Избери място и уговори контрол над непредвидимия шум."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Снимаш лекар в коридор и в кабинет. Коридорът е по-тих на слух, но гласът се връща от стените.\n\nРешение: Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности.\n\nКакво да провериш: Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности. Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая.","label":"Как го поправяш"},"before":{"text":"Избираш коридора само по измереното ниво на фонов шум.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Запиши фраза и пет секунди пауза в две налични стаи. Пази еднаква дистанция. Слушай окончанията на думите при еднаква сила. Не спирай чуждо оборудване и вентилация за учебния опит.\n\nПровери резултата: Избраният файл пази окончанията и няма пречещо наслагване на отзвук. Периодичен шум се отбелязва. Преместване или доближаване се приема само след нова проба.\n\nПримерна работна бележка: Коридорът е тих, но след всяка дума остава дълго отражение. В по-меката стая при същата дистанция окончанията са по-четими. Избирам нея, ако достъпът и периодичният шум са изпълними.\n\nАко не е изпълнено: Повтори с по-близка безопасна позиция и сравни. Не променяй няколко условия едновременно, ако искаш да разбереш причината. Не спирай чужда вентилация или техника без потвърждение."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Това, в което реалната проба дава по-разбираем глас при изпълними условия."},{"id":"b","label":"Това с най-нисък фонов шум, независимо от дългия отзвук."},{"id":"c","label":"Това с най-просторен фон, независимо от дистанцията на микрофона."}],"question":"Кое място е по-подходящо за интервю?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Това, в което реалната проба дава по-разбираем глас при изпълними условия. Избраният файл пази окончанията и няма пречещо наслагване на отзвук. Периодичен шум се отбелязва. Преместване или доближаване се приема само след нова проба."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Снимаш лекар в коридор и в кабинет. Коридорът е по-тих на слух, но гласът се връща от стените.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Избирам коридора само по усещането за тишина."},{"id":"b","label":"Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности."},{"id":"c","label":"Усилвам записа от коридора и не сравнявам отраженията след думите."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности.\n\nКакво да провериш: Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Добави дебел килим извън мястото на отражение и приеми, че всяко ехо е решено."},{"id":"c","label":"Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Запиши фраза и пет секунди пауза в две налични стаи. Пази еднаква дистанция. Слушай окончанията на думите при еднаква сила. Не спирай чуждо оборудване и вентилация за учебния опит.","takeaways":["Гледай едновременно съотношението на гласа към шума и колко дълго отекват думите.","Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности.","Провери: Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Прослушай думите и паузите при изравнена сила."},{"id":"s1","text":"Слушай постоянното и периодичното в две локации."},{"id":"s4","text":"Избери място и уговори контрол над непредвидимия шум."},{"id":"s2","text":"Запиши една и съща фраза от еднаква дистанция."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Слушай постоянното и периодичното в две локации. → Запиши една и съща фраза от еднаква дистанция. → Прослушай думите и паузите при изравнена сила. → Избери място и уговори контрол над непредвидимия шум."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Планираното помещение не е достъпно и остава само кух коридор.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Добави дебел килим извън мястото на отражение и приеми, че всяко ехо е решено."},{"id":"b","label":"Доближи микрофона, промени ориентацията и ограничи кадъра до по-акустично защитено място; повтори теста."},{"id":"c","label":"Избираш коридора само по измереното ниво на фонов шум."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Доближи микрофона, промени ориентацията и ограничи кадъра до по-акустично защитено място; повтори теста. Избраният файл пази окончанията и няма пречещо наслагване на отзвук. Периодичен шум се отбелязва. Преместване или доближаване се приема само след нова проба."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Смяната на позиция е решение за конкретна стая. Не се преподава универсална дистанция, която ще поправи всяка акустика."}}]},{"module":"s02-m05","lesson":"pv05-05","source_hash":"332100b5d622b8703e7e0b238d0a1910","objective":"Ще подготвиш кратък текст за задкадров глас и ще запишеш сравними дубъли. Ще избираш естествено, разбираемо произнасяне и ще проверяваш дали обработката не изяжда съгласните. Резултатът е кратък оригинален и обработен файл със същата ключова мисъл.","hook":"Гласът е записан в килер без шум, но дишането и дрехите звучат по-силно от текста.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще подготвиш кратък текст за задкадров глас и ще запишеш сравними дубъли. Ще избираш естествено, разбираемо произнасяне и ще проверяваш дали обработката не изяжда съгласните. Резултатът е кратък оригинален и обработен файл със същата ключова мисъл.","deliverable":"Запиши със собствен глас потвърдените условия на пекарната: 6 мини банички за 9 €, вземане след уточняване. Направи два естествени дубъла. Остави версия без обработка и сравни с умерено почистен вариант, ако редакторът позволява.","check":"Брой, цена и получаване се чуват ясно. Обработката не променя думите и не добавя метален звук. Сравняваш при сходна сила на възпроизвеждане."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Гласът е записан в килер без шум, но дишането и дрехите звучат по-силно от текста."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Voiceover — глас зад кадър. Компресия на звука — намалява разликите между тихи и силни части. EQ — промяна на честотни области. LUFS — измерване на възприеманата сила, а не оценка на яснота.\n\nКачественият voiceover започва от текст, тиха сцена, постоянна дистанция и няколко контролни дубъла.\n\nПостави микрофона леко извън директната струя въздух и използвай поп филтър при нужда. Маркирай позицията на човека и говори със същата енергия. Запиши проба и тишина на място."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"В монтажа първо избери най-ясния дубъл и сглоби естествени паузи. Ползвай шумоподтискане умерено; силна обработка може да изяде съгласните и да остави метален оттенък. Компресията изравнява големите разлики, но не замества позицията на микрофона. Слушай на слушалки и на обикновен телефон, като сравняваш еднаква крайна сила.\n\nГраница на решението: Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Прочети текста на глас и махни неудобните думи.\n2. Маркирай позиция, направи проба с нормална интонация.\n3. Избери дубъл и почисти очевидните шумове.\n4. Експортирай и провери паузите и разбираемостта на телефон."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"За реклама на сладкарница имаш 30 секунди глас. Дубъл 1 е чист, но бърз; дубъл 2 е по-естествен, но има една шумна глътка.\n\nРешение: Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция.\n\nКакво да провериш: В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция. В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа.","label":"Как го поправяш"},"before":{"text":"Пускаш агресивен denoise върху целия дубъл 2 и изтъняваш всички съгласни.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Запиши със собствен глас потвърдените условия на пекарната: 6 мини банички за 9 €, вземане след уточняване. Направи два естествени дубъла. Остави версия без обработка и сравни с умерено почистен вариант, ако редакторът позволява.\n\nПровери резултата: Брой, цена и получаване се чуват ясно. Обработката не променя думите и не добавя метален звук. Сравняваш при сходна сила на възпроизвеждане.\n\nПримерна работна бележка: Примерна реплика: „Пакетът е от 6 мини банички за 9 евро. Вземането се уточнява предварително. Изпратете запитване, за да проверите възможностите.“ Това е учебен текст; не обещава наличност, доставка или потвърдена поръчка.\n\nАко не е изпълнено: Ако обработката изяжда съгласни, върни по-умерена настройка или оригинала. Ако един дубъл е прекалено бърз, повтори нужната фраза с естествени паузи. Провери автоматичния транскрипт спрямо гласа."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Файлът е по-силен, независимо дали думите са изменени."},{"id":"b","label":"В паузите има пълна тишина, но краят на думите изчезва."},{"id":"c","label":"Шумът е намален, а съгласните и естественият глас са запазени."}],"question":"Кога шумоподтискането е помогнало?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Шумът е намален, а съгласните и естественият глас са запазени. Брой, цена и получаване се чуват ясно. Обработката не променя думите и не добавя метален звук. Сравняваш при сходна сила на възпроизвеждане."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"За реклама на сладкарница имаш 30 секунди глас. Дубъл 1 е чист, но бърз; дубъл 2 е по-естествен, но има една шумна глътка.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция."},{"id":"b","label":"Обработвам агресивно целия естествен дубъл заради една глътка."},{"id":"c","label":"Избирам чистия, но прекалено бърз дубъл, без да проверя дали условията се разбират."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция.\n\nКакво да провериш: В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Повиши компресията, за да направиш тихите грешки еднакво силни с правилните думи."},{"id":"b","label":"Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Запиши със собствен глас потвърдените условия на пекарната: 6 мини банички за 9 €, вземане след уточняване. Направи два естествени дубъла. Остави версия без обработка и сравни с умерено почистен вариант, ако редакторът позволява.","takeaways":["Качественият voiceover започва от текст, тиха сцена, постоянна дистанция и няколко контролни дубъла.","Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция.","Провери: В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Избери дубъл и почисти очевидните шумове."},{"id":"s1","text":"Прочети текста на глас и махни неудобните думи."},{"id":"s4","text":"Експортирай и провери паузите и разбираемостта на телефон."},{"id":"s2","text":"Маркирай позиция, направи проба с нормална интонация."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Прочети текста на глас и махни неудобните думи. → Маркирай позиция, направи проба с нормална интонация. → Избери дубъл и почисти очевидните шумове. → Експортирай и провери паузите и разбираемостта на телефон."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът променя последното изречение след като цялата озвучка е записана.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Презапиши изречението с еднаква позиция, помещение и тон; сравни с двете съседни реплики."},{"id":"b","label":"Пускаш агресивен denoise върху целия дубъл 2 и изтъняваш всички съгласни."},{"id":"c","label":"Повиши компресията, за да направиш тихите грешки еднакво силни с правилните думи."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Презапиши изречението с еднаква позиция, помещение и тон; сравни с двете съседни реплики. Брой, цена и получаване се чуват ясно. Обработката не променя думите и не добавя метален звук. Сравняваш при сходна сила на възпроизвеждане."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Ако избираш синтетичен глас, провери употребата и произношението. Това не е изпълнение на задачата за собствен микрофонен запис и не заменя сравнението на реалните дубъли."}}]},{"module":"s02-m05","lesson":"pv05-06","source_hash":"a66022f3406a8ea3104adc1dd753e593","objective":"Ще свързваш отделен звук с картината по ясен общ момент. Ще проверяваш началото, средата и края, защото точният старт не гарантира точен дълъг запис. Резултатът е файл с проверен синхрон и запазени оригинали.","hook":"Началото е синхронно, а след половин час устните вече изпреварват гласа.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще свързваш отделен звук с картината по ясен общ момент. Ще проверяваш началото, средата и края, защото точният старт не гарантира точен дълъг запис. Резултатът е файл с проверен синхрон и запазени оригинали.","deliverable":"Ако имаш две устройства, запиши кратко пляскане и няколко реплики, после провери синхрона. С един телефон изпълни задачата с предоставения случай; не представяй това като реален тест на отделни устройства.","check":"Пляскането и ясните съгласни съвпадат на няколко места. При дълъг материал проверката обхваща края. Коригираните работни копия са отделени от оригиналите."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Началото е синхронно, а след половин час устните вече изпреварват гласа."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Маркер — видим и чуваем общ момент, например пляскане. Scratch audio — помощният звук от камерата. Дрейф — постепенно разминаване. Променлива кадрова честота — кадрите не са с еднакъв времеви интервал.\n\nСъздай ясен общ маркер за записите и провери синхрона и в началото, и в края.\n\nПляскане в кадър оставя видим и звуков пик; помощният звук от камерата също помага при синхронизиране. Поддържай отделните файлове организирани по дубъл, устройство и време."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"При дълги записи може да има дрейф заради различни часовници, променлива кадрова честота или грешно интерпретирани настройки. Не го поправяй само с преместване на целия аудио клип, ако началото е наред, а краят не е. Проверявай говорни съгласни на поне две далечни места във времевата линия и при нужда подготви коректен работен формат/настройка.\n\nГраница на решението: Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Пусни външен рекордер и камера, после направи видим маркер.\n2. Кръсти и архивирай файловете по дубъл.\n3. Синхронизирай началото по маркера или камерата.\n4. Провери говор в началото и края на дългия клип."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"40-минутен разговор от телефон и външен рекордер започва точно, но след 35 минути устните не съвпадат.\n\nРешение: Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда.\n\nКакво да провериш: Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда. Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати.","label":"Как го поправяш"},"before":{"text":"Местиш целия звук с две рамки и разваляш началото.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Ако имаш две устройства, запиши кратко пляскане и няколко реплики, после провери синхрона. С един телефон изпълни задачата с предоставения случай; не представяй това като реален тест на отделни устройства.\n\nПровери резултата: Пляскането и ясните съгласни съвпадат на няколко места. При дълъг материал проверката обхваща края. Коригираните работни копия са отделени от оригиналите.\n\nПримерна работна бележка: При учебния дълъг запис началният маркер съвпада, но след 35 минути устните се разминават. Не местя целия звук, за да разваля началото; проверявам времето на файловете и правя подходяща корекция върху работно копие, после проверявам няколко места.\n\nАко не е изпълнено: При постоянно отместване провери подравняването; при нарастващо отместване търси дрейф и настройките. Кратка проба не доказва синхрон на половинчасов запис. Пази оригиналите."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Доказва точен синхрон за всяка продължителност на записа."},{"id":"b","label":"Показва началното подравняване, но не изключва по-късен дрейф."},{"id":"c","label":"Позволява да изтрием оригиналните файлове след подравняване."}],"question":"Какво показва точният общ маркер в началото?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Показва началното подравняване, но не изключва по-късен дрейф. Пляскането и ясните съгласни съвпадат на няколко места. При дълъг материал проверката обхваща края. Коригираните работни копия са отделени от оригиналите."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"40-минутен разговор от телефон и външен рекордер започва точно, но след 35 минути устните не съвпадат.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Премествам целия звук, за да оправя края, въпреки че началото вече съвпада."},{"id":"b","label":"Коригирам само първата реплика и пропускам проверката след 35-ата минута."},{"id":"c","label":"Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда.\n\nКакво да провериш: Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Изрежи всяка неудобна реплика и скрий липсата на синхрон с музика."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Ако имаш две устройства, запиши кратко пляскане и няколко реплики, после провери синхрона. С един телефон изпълни задачата с предоставения случай; не представяй това като реален тест на отделни устройства.","takeaways":["Създай ясен общ маркер за записите и провери синхрона и в началото, и в края.","Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда.","Провери: Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Синхронизирай началото по маркера или камерата."},{"id":"s1","text":"Пусни външен рекордер и камера, после направи видим маркер."},{"id":"s4","text":"Провери говор в началото и края на дългия клип."},{"id":"s2","text":"Кръсти и архивирай файловете по дубъл."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Пусни външен рекордер и камера, после направи видим маркер. → Кръсти и архивирай файловете по дубъл. → Синхронизирай началото по маркера или камерата. → Провери говор в началото и края на дългия клип."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Оказва се, че камерата няма използваем scratch audio.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Местиш целия звук с две рамки и разваляш началото."},{"id":"b","label":"Изрежи всяка неудобна реплика и скрий липсата на синхрон с музика."},{"id":"c","label":"Използвай видимия маркер или времеви бележки и провери няколко говорни момента; не разчитай на автоматичен waveform match."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Използвай видимия маркер или времеви бележки и провери няколко говорни момента; не разчитай на автоматичен waveform match. Пляскането и ясните съгласни съвпадат на няколко места. При дълъг материал проверката обхваща края. Коригираните работни копия са отделени от оригиналите."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Не учим един бутон като универсално решение. Проверяваме настройките и времето на файловете, после конкретния резултат на експорта."}}]},{"module":"s02-m05","lesson":"pv05-07","source_hash":"f98b6080ef3238274be0337f15fa0369","objective":"Ще различаваш слушане, изтегляне и разрешена употреба в клиентско видео. Ще проверяваш конкретната композиция, канала и платената реклама и ще пазиш условията към проекта. Можеш да изпълниш първата задача без музика; не се изисква покупка или публично тестово качване.","hook":"„Без copyright“ в заглавието на чужд клип не е договор за рекламата на клиента.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще различаваш слушане, изтегляне и разрешена употреба в клиентско видео. Ще проверяваш конкретната композиция, канала и платената реклама и ще пазиш условията към проекта. Можеш да изпълниш първата задача без музика; не се изисква покупка или публично тестово качване.","deliverable":"Реши учебния случай: композиция е разрешена само за YouTube, а клиентът иска Instagram реклама. Избери смяна с подходящо разрешен запис или версия без музика. При собствен избор запази точните действащи условия.","check":"Потвърдени са композиция, носител на разрешението, клиент, канали и употреба. Общ надпис „безплатно“ или наличност в приложение не се приема за лиценз. Непотвърдено се отбелязва като такова."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"„Без copyright“ в заглавието на чужд клип не е договор за рекламата на клиента."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Лиценз — условия за определена употреба. Авторство — изискваното посочване на автора и лиценза. Търговска употреба — употреба за бизнес цел, която не се определя само от наличието на монетизация на канала.\n\nСвободно за слушане, безплатно за изтегляне и разрешено за търговска употреба са различни неща.\n\nЗапиши кой държи правата, кой лиценз е купен или предоставен, за коя платформа, срок, територия и употреба важи. Пази фактура или текст на условията към конкретната версия на видеото."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Музика от библиотеката на една платформа може да има правила само за тази платформа; прехвърлянето на клипа във Facebook или реклама може да изисква отделно разрешение. При Creative Commons провери точния вариант и изискваното посочване на авторство; договорът на платена библиотека също може да изключва реклами или препродажба. Когато правата са неясни, използвай проследим лиценз или собствена музика, не се осланяй на тестово публикуване.\n\nГраница на решението: Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Опиши къде и как клиентът ще използва видеото.\n2. Провери конкретния лиценз и страната, която го дава.\n3. Запази условията и документа към проекта.\n4. Прегледай финалната музика и употреба преди предаване."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Видео за сладкарница тръгва в YouTube и след седмица клиентът иска платена реклама в Instagram със същия файл.\n\nРешение: Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права.\n\nКакво да провериш: В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права. В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали.","label":"Как го поправяш"},"before":{"text":"Казваш, че щом YouTube не е свалил видеото, музиката е свободна за всички канали.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Реши учебния случай: композиция е разрешена само за YouTube, а клиентът иска Instagram реклама. Избери смяна с подходящо разрешен запис или версия без музика. При собствен избор запази точните действащи условия.\n\nПровери резултата: Потвърдени са композиция, носител на разрешението, клиент, канали и употреба. Общ надпис „безплатно“ или наличност в приложение не се приема за лиценз. Непотвърдено се отбелязва като такова.\n\nПримерна работна бележка: Условията дават употреба само в YouTube. За исканата Instagram реклама записвам „непотвърдено“ и предавам версия без тази музика или търся подходящо разрешен запис. Самото изписване на автора не разширява лиценза.\n\nАко не е изпълнено: При липсващ обхват върни въпроса към носителя на разрешението или смени музиката. Различавай конкретен Creative Commons лиценз, Audio Library, Creator Music и TikTok CML. Не публикувай пробно, за да чакаш автоматична претенция."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Проверявам дали конкретният лиценз ги покрива, преди да предам версията."},{"id":"b","label":"Запазвам песента, защото вече е използвана без предупреждение."},{"id":"c","label":"Приемам, че всяка Creative Commons музика допуска реклама и промени."}],"question":"Какво правиш при нов канал или платена употреба?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Проверявам дали конкретният лиценз ги покрива, преди да предам версията. Потвърдени са композиция, носител на разрешението, клиент, канали и употреба. Общ надпис „безплатно“ или наличност в приложение не се приема за лиценз. Непотвърдено се отбелязва като такова."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Видео за сладкарница тръгва в YouTube и след седмица клиентът иска платена реклама в Instagram със същия файл.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Пренасям музиката в Instagram, защото не е имало претенция в YouTube."},{"id":"b","label":"Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права."},{"id":"c","label":"Добавям само името на автора, без да проверя обхвата на разрешението."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права.\n\nКакво да провериш: В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Напиши „music by ...“ в описанието и смятай, че така автоматично получаваш лиценз."},{"id":"c","label":"Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Реши учебния случай: композиция е разрешена само за YouTube, а клиентът иска Instagram реклама. Избери смяна с подходящо разрешен запис или версия без музика. При собствен избор запази точните действащи условия.","takeaways":["Свободно за слушане, безплатно за изтегляне и разрешено за търговска употреба са различни неща.","Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права.","Провери: В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Запази условията и документа към проекта."},{"id":"s1","text":"Опиши къде и как клиентът ще използва видеото."},{"id":"s4","text":"Прегледай финалната музика и употреба преди предаване."},{"id":"s2","text":"Провери конкретния лиценз и страната, която го дава."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Опиши къде и как клиентът ще използва видеото. → Провери конкретния лиценз и страната, която го дава. → Запази условията и документа към проекта. → Прегледай финалната музика и употреба преди предаване."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът иска да прожектира видеото на събитие, извън първоначално посочените канали.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Напиши „music by ...“ в описанието и смятай, че така автоматично получаваш лиценз."},{"id":"b","label":"Провери договора за тази употреба преди прожекция; при липса на покритие осигури друг лицензиран вариант."},{"id":"c","label":"Казваш, че щом YouTube не е свалил видеото, музиката е свободна за всички канали."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Провери договора за тази употреба преди прожекция; при липса на покритие осигури друг лицензиран вариант. Потвърдени са композиция, носител на разрешението, клиент, канали и употреба. Общ надпис „безплатно“ или наличност в приложение не се приема за лиценз. Непотвърдено се отбелязва като такова."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"YouTube Audio Library, Creator Music и TikTok Commercial Music Library са различни услуги. Условията не се заменят една с друга. За TikTok се проверяват регионът и допустимото разполагане; не се обещава разрешение за други платформи."}}]},{"module":"s02-m05","lesson":"pv05-08","source_hash":"4ecc447e05643a26f4d4621393806736","objective":"Ще завършиш минута, в която ключовото обяснение се разбира по звука. Ще проверяваш оригинал, монтаж и изнесен файл поотделно. Задачата е за качество на речта; достъпните субтитри остават полезни и не трябва да се премахват от готовото видео.","hook":"Красивият финал не спасява видео, в което едно ключово изречение е неразбираемо.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще завършиш минута, в която ключовото обяснение се разбира по звука. Ще проверяваш оригинал, монтаж и изнесен файл поотделно. Задачата е за качество на речта; достъпните субтитри остават полезни и не трябва да се премахват от готовото видео.","deliverable":"Запиши 60 секунди собствено обяснение за условна услуга или домашен процес. Провери началото, средата и края на наличното устройство. Ако имаш и слушалки, повтори прослушването. Музиката е по избор и с проверени права.","check":"Ключовите думи се разбират при нормална сила; няма заглушена или изкривена важна реплика. Оригиналът и финалът са запазени. Самопроверката не се представя за доказана разбираемост при всички зрители."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Красивият финал не спасява видео, в което едно ключово изречение е неразбираемо."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Пик — кратък максимум на нивото. Синхрон — съответствие на звук и действие. Транскрипт — текст на казаното; може да е ориентир за проверка, но автоматичният текст може да съдържа грешки.\n\nКрайният тест е зрителят да разбере думите при нормално слушане; оценявай оригинала, монтажа и експорта отделно.\n\nЗапиши разговор с реални шумове от мястото, близък микрофон и проверен входен запас. Избери най-разбираемите дубъли, запази естествени паузи и добави музика само ако не конкурира речта и имаш подходящи права."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Провери началото, средата и края на файла на слушалки и на обикновен телефон при нормална сила. Не приемай числова цел за възприеманата сила като универсално правило за всички платформи: виж изискването за конкретната доставка и провери, че няма клипинг. Ако субтитрите са нужни за достъпност, те допълват гласа, а не заместват липсващи думи в звука.\n\nГраница на решението: Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Запиши целта, канала и правата за музика.\n2. Направи аудио проба и 60-секунден запис със запас.\n3. Монтирай за разбираемост и провери синхрон.\n4. Изнеси и прослушай финала на наличния телефон; повтори със слушалки, ако имаш."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Минутно интервю за местен бизнес има правилно лице и две камери, но на 38-ата секунда врата покрива името на услугата.\n\nРешение: Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла.\n\nКакво да провериш: Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла. Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз.","label":"Как го поправяш"},"before":{"text":"Оставяш дефекта, защото надписът на екрана казва същото.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Запиши 60 секунди собствено обяснение за условна услуга или домашен процес. Провери началото, средата и края на наличното устройство. Ако имаш и слушалки, повтори прослушването. Музиката е по избор и с проверени права.\n\nПровери резултата: Ключовите думи се разбират при нормална сила; няма заглушена или изкривена важна реплика. Оригиналът и финалът са запазени. Самопроверката не се представя за доказана разбираемост при всички зрители.\n\nПримерна работна бележка: В отделна бележка записвам трите важни твърдения. Прослушвам финалния файл без да чета текста и отбелязвам неясните места; после сверявам репликите с бележката. Ако на 38-ата секунда удар покрива името, избирам чист дубъл или презапис.\n\nАко не е изпълнено: Ако думата липсва в звука, по-силен микс или правилен субтитър не изпълнява аудио задачата. Поправи конкретната реплика и отвори новия експорт. Пази субтитрите за зрителите, които се нуждаят от тях."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Приемам, че точният измерена сила доказва разбираемост на всяка дума."},{"id":"b","label":"Гледам субтитрите и не проверявам заглушените думи в аудиото."},{"id":"c","label":"Прослушвам действителния финален файл и поправям конкретните неразбираеми места."}],"question":"Как проверяваш минутния проект?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Прослушвам действителния финален файл и поправям конкретните неразбираеми места. Ключовите думи се разбират при нормална сила; няма заглушена или изкривена важна реплика. Оригиналът и финалът са запазени. Самопроверката не се представя за доказана разбираемост при всички зрители."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Минутно интервю за местен бизнес има правилно лице и две камери, но на 38-ата секунда врата покрива името на услугата.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла."},{"id":"b","label":"Повишавам общата сила, въпреки че вратата покрива името на услугата."},{"id":"c","label":"Оставям заглушеното име, защото се чете в автоматичните субтитри."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла.\n\nКакво да провериш: Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Нормализирай всичко до максимума и приеми, че по-силно значи по-ясно."},{"id":"b","label":"Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Запиши 60 секунди собствено обяснение за условна услуга или домашен процес. Провери началото, средата и края на наличното устройство. Ако имаш и слушалки, повтори прослушването. Музиката е по избор и с проверени права.","takeaways":["Крайният тест е зрителят да разбере думите при нормално слушане; оценявай оригинала, монтажа и експорта отделно.","Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла.","Провери: Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Монтирай за разбираемост и провери синхрон."},{"id":"s1","text":"Запиши целта, канала и правата за музика."},{"id":"s4","text":"Изнеси и прослушай финала на наличния телефон; повтори със слушалки, ако имаш."},{"id":"s2","text":"Направи аудио проба и 60-секунден запис със запас."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Запиши целта, канала и правата за музика. → Направи аудио проба и 60-секунден запис със запас. → Монтирай за разбираемост и провери синхрон. → Изнеси и прослушай финала на наличния телефон; повтори със слушалки, ако имаш."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът премахва музиката за вторична версия на видео реклама.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Изнеси вариант без музика и провери паузите, речта и фоновия шум отначало; не приемай, че смесването остава същото."},{"id":"b","label":"Оставяш дефекта, защото надписът на екрана казва същото."},{"id":"c","label":"Нормализирай всичко до максимума и приеми, че по-силно значи по-ясно."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Изнеси вариант без музика и провери паузите, речта и фоновия шум отначало; не приемай, че смесването остава същото. Ключовите думи се разбират при нормална сила; няма заглушена или изкривена важна реплика. Оригиналът и финалът са запазени. Самопроверката не се представя за доказана разбираемост при всички зрители."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Няма задължителен външен оценител. Можеш да сравниш с потвърдения текст; проверка от непознат зрител е полезно допълнение, което самооценката не заменя."}}]},{"module":"s02-m06","lesson":"pv06-01","source_hash":"3853acc3d411ae4b40b19724f3327d64","objective":"Ще съставяш кратък снимачен план, който показва кое е потвърдено и кое още чака решение. Ще свързваш целта на бизнеса с хора, място, време и нужни кадри. Резултатът е една използваема страница за първата проба, вместо списък с техника и скрити предположения.","hook":"Камерата е подготвена, но никой не е потвърдил кой отключва обекта. Снимачният план започва и с тези условия.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще съставяш кратък снимачен план, който показва кое е потвърдено и кое още чака решение. Ще свързваш целта на бизнеса с хора, място, време и нужни кадри. Резултатът е една използваема страница за първата проба, вместо списък с техника и скрити предположения.","deliverable":"Използвай пекарна „Зърно“. От предоставените условия избери потвърдените брой, цена и получаване. Остави наличността като неизвестна. За домашната проба използвай собствен предмет и безопасно място; не измисляй реален контакт на бизнеса.","check":"За всяка нужда е видно потвърдено ли е изпълнението. Задължителните кадри имат възможно време и място. Критична липса води до уточняване или промяна на обхвата."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Камерата е подготвена, но никой не е потвърдил кой отключва обекта. Снимачният план започва и с тези условия."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Предпродукция — подготовката преди снимане. Отговорник — човекът, който може да потвърди конкретен факт или достъп. Критично неизвестно — липса, която може да провали задължителния кадър.\n\nНапиши минимален работен документ: за кого е видеото, къде ще се ползва, кой взема решения и какъв резултат трябва да се види.\n\nЕдна страница стига, ако съдържа контакти, адрес, времеви прозорец, разрешения, резервно място и списък с нужни кадри и звуци. Раздели „потвърдено“ от „чака отговор“."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Не започвай с изреждане на техника. Изясни кои твърдения трябва да бъдат проверени от клиента, дали участниците знаят къде ще се публикува видеото и кой разрешава достъп. Запиши какво е забранено за показване: лични данни, лица, продукти, търговска тайна. Когато има неизвестно, сложи собственик и срок за решение преди началото на снимките.\n\nГраница на решението: Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Определи цел, употреба и критерий за приемане.\n2. Потвърди участници, достъп, условия и права.\n3. Опиши задължителните кадри, звук и резервен вариант.\n4. Позвъни предния ден и затвори всички критични неизвестни."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Местна работилница иска кратко видео за процеса. Майсторът идва след 10 ч., машината работи само в 9 ч., а никой не е изяснил дали може да се снима клиентски продукт.\n\nРешение: Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване.\n\nКакво да провериш: В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване. В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат.","label":"Как го поправяш"},"before":{"text":"Пристигаш с готова shot list и започваш да снимаш без разрешения и без работещ процес.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Използвай пекарна „Зърно“. От предоставените условия избери потвърдените брой, цена и получаване. Остави наличността като неизвестна. За домашната проба използвай собствен предмет и безопасно място; не измисляй реален контакт на бизнеса.\n\nПровери резултата: За всяка нужда е видно потвърдено ли е изпълнението. Задължителните кадри имат възможно време и място. Критична липса води до уточняване или промяна на обхвата.\n\nПримерна работна бележка: Цел: кратко обяснение на учебното предложение. Потвърдено: 6 мини банички, 9 €, вземане след уточняване; доставка няма. Неизвестно: наличност. Проба: собствен предмет у дома, без реални клиентски данни. Непотвърдената наличност не влиза като обещание.\n\nАко не е изпълнено: Ако критичен кадър няма достъп или отговорник, остави го видимо непотвърден и промени плана. AI може да подреди информацията, но не може да потвърди отключване, човек или наличност вместо отговорния."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Само подредба на най-добрите налични камери и обективи."},{"id":"b","label":"Цел, употреба, задължителни кадри, потвърждения и видими неизвестни."},{"id":"c","label":"Предположени часове, записани като потвърдени за удобство."}],"question":"Какво трябва да съдържа краткият план?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Цел, употреба, задължителни кадри, потвърждения и видими неизвестни. За всяка нужда е видно потвърдено ли е изпълнението. Задължителните кадри имат възможно време и място. Критична липса води до уточняване или промяна на обхвата."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Местна работилница иска кратко видео за процеса. Майсторът идва след 10 ч., машината работи само в 9 ч., а никой не е изяснил дали може да се снима клиентски продукт.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Планирам машината след 10 ч., защото тогава пристига майсторът."},{"id":"b","label":"Оставям клиентския продукт в списъка без решение кой може да разреши показването."},{"id":"c","label":"Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване.\n\nКакво да провериш: В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Остави правата и достъпа за след снимките, за да не забавяш екипа."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Използвай пекарна „Зърно“. От предоставените условия избери потвърдените брой, цена и получаване. Остави наличността като неизвестна. За домашната проба използвай собствен предмет и безопасно място; не измисляй реален контакт на бизнеса.","takeaways":["Напиши минимален работен документ: за кого е видеото, къде ще се ползва, кой взема решения и какъв резултат трябва да се види.","Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване.","Провери: В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Опиши задължителните кадри, звук и резервен вариант."},{"id":"s1","text":"Определи цел, употреба и критерий за приемане."},{"id":"s4","text":"Позвъни предния ден и затвори всички критични неизвестни."},{"id":"s2","text":"Потвърди участници, достъп, условия и права."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Определи цел, употреба и критерий за приемане. → Потвърди участници, достъп, условия и права. → Опиши задължителните кадри, звук и резервен вариант. → Позвъни предния ден и затвори всички критични неизвестни."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Вечерта преди снимките човекът за контакт не потвърждава достъпа.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Пристигаш с готова shot list и започваш да снимаш без разрешения и без работещ процес."},{"id":"b","label":"Остави правата и достъпа за след снимките, за да не забавяш екипа."},{"id":"c","label":"Използвай резервното място или промени часа след писмено потвърждение; не пристигай с надежда, че някой ще отключи."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Използвай резервното място или промени часа след писмено потвърждение; не пристигай с надежда, че някой ще отключи. За всяка нужда е видно потвърдено ли е изпълнението. Задължителните кадри имат възможно време и място. Критична липса води до уточняване или промяна на обхвата."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Краткият план събира работните решения. Той не е универсален договор и не замества необходимите потвърждения."}}]},{"module":"s02-m06","lesson":"pv06-02","source_hash":"692f7b7a9b63d97e31702085bbed4ce8","objective":"Ще избираш между точен текст и разговор по опорни точки. Ще пазиш числата и условията точни, без да караш човека да рецитира целия сайт. В края ще имаш кратка проверена реплика и ще знаеш коя част може да се произнесе свободно.","hook":"При четене човекът се затруднява; при свободен разговор пропуска важно условие. Избери форма, която пази и точността, и разбираемостта.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще избираш между точен текст и разговор по опорни точки. Ще пазиш числата и условията точни, без да караш човека да рецитира целия сайт. В края ще имаш кратка проверена реплика и ще знаеш коя част може да се произнесе свободно.","deliverable":"Запиши със собствен глас две версии на учебните условия: точен текст и свободно обяснение. Свери брой, цена и получаване. Избери по-разбираемата версия само ако фактите са верни.","check":"Не се появяват измислени условия. Важната мисъл се разбира без повторно четене. Изборът на формата следва нужната точност и действителното произнасяне."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"При четене човекът се затруднява; при свободен разговор пропуска важно условие. Избери форма, която пази и точността, и разбираемостта."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Опорни точки — кратки теми, които пазят посоката на отговора. Телепромптер — показва текста близо до посоката на камерата. Абсолютно обещание — формулировка като „винаги“, която изисква конкретна проверка.\n\nРаздели задължителните факти от начина, по който говорителят ги произнася.\n\nНапиши опорни точки за естествен разговор и отделен списък с точни числа, условия, имена и юридически одобрени фрази. Телепромптерът помага за точен текст, но изисква репетиция и темпо."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Провери как говорителят разказва темата на приятел без камера. Ако историята е силна, вземи разговорния вариант и допълни необходимите факти с кадри или графика след проверка. Ако обещанието е строго формулирано, заснеми точното изречение отделно. Не принуждавай човек да казва твърдение, което не е потвърдено от отговорния в организацията.\n\nГраница на решението: Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Отбележи точните факти и отговорния за тях.\n2. Запиши свободен пробен отговор.\n3. Избери опорни точки или точен текст според грешките.\n4. Сними и провери съдържанието преди финалния монтаж."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Собственичка на салон говори увлекателно за услугата, но казва „винаги безболезнено“, което клиентът не може да гарантира.\n\nРешение: Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие.\n\nКакво да провериш: Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие. Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания.","label":"Как го поправяш"},"before":{"text":"Оставяш силната реплика, защото звучи убедително, без да провериш обещанието.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Запиши със собствен глас две версии на учебните условия: точен текст и свободно обяснение. Свери брой, цена и получаване. Избери по-разбираемата версия само ако фактите са верни.\n\nПровери резултата: Не се появяват измислени условия. Важната мисъл се разбира без повторно четене. Изборът на формата следва нужната точност и действителното произнасяне.\n\nПримерна работна бележка: Свободна версия: „Пакетът е от 6 мини банички за 9 евро. Уточняваме вземането предварително.“ Точната версия пази същите факти; изборът е по разбираемостта на реалния запис. Не добавям доставка или сигурна наличност.\n\nАко не е изпълнено: При променен факт поправи текста и повтори ключовото изречение. Ако се изисква одобрена точна фраза, не я съкращавай по впечатление. Естествената реч може да запази точността."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Начина на изказ, докато потвърдените факти и условия остават точни."},{"id":"b","label":"Цената и сроковете, ако говорителят звучи уверен."},{"id":"c","label":"Задължителната фраза, ако монтажът е по-кратък без нея."}],"question":"Какво можеш да оставиш свободно при разговорен запис?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Начина на изказ, докато потвърдените факти и условия остават точни. Не се появяват измислени условия. Важната мисъл се разбира без повторно четене. Изборът на формата следва нужната точност и действителното произнасяне."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Собственичка на салон говори увлекателно за услугата, но казва „винаги безболезнено“, което клиентът не може да гарантира.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Оставям „винаги безболезнено“, защото е произнесено естествено."},{"id":"b","label":"Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие."},{"id":"c","label":"Преписвам цялата страница, без да изясня кое обещание може да се потвърди."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие.\n\nКакво да провериш: Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Помоли говорителя да научи още две страници наизуст и ускорете четенето."},{"id":"c","label":"Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Запиши със собствен глас две версии на учебните условия: точен текст и свободно обяснение. Свери брой, цена и получаване. Избери по-разбираемата версия само ако фактите са верни.","takeaways":["Раздели задължителните факти от начина, по който говорителят ги произнася.","Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие.","Провери: Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Избери опорни точки или точен текст според грешките."},{"id":"s1","text":"Отбележи точните факти и отговорния за тях."},{"id":"s4","text":"Сними и провери съдържанието преди финалния монтаж."},{"id":"s2","text":"Запиши свободен пробен отговор."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Отбележи точните факти и отговорния за тях. → Запиши свободен пробен отговор. → Избери опорни точки или точен текст според грешките. → Сними и провери съдържанието преди финалния монтаж."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Клиентът добавя законово изисквана фраза накрая.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Помоли говорителя да научи още две страници наизуст и ускорете четенето."},{"id":"b","label":"Запиши я отделно точно и с разбираемо темпо, после провери с отговорния човек как стои в целия монтаж."},{"id":"c","label":"Оставяш силната реплика, защото звучи убедително, без да провериш обещанието."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Запиши я отделно точно и с разбираемо темпо, после провери с отговорния човек как стои в целия монтаж. Не се появяват измислени условия. Важната мисъл се разбира без повторно четене. Изборът на формата следва нужната точност и действителното произнасяне."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Естественият тон не е оправдание за неточност. Когато е нужна одобрена точна фраза, тя се проверява отделно."}}]},{"module":"s02-m06","lesson":"pv06-03","source_hash":"1fa5f5df77624cf183ec12f2472dfa08","objective":"Ще проверяваш локацията с кратко видео и реч при сравним час. Ще откриваш какво пречи на лицето, звука или фона и ще оставяш реална резервна позиция. Резултатът е избор, който можеш да повториш в работните условия на мястото.","hook":"Снимка на помещението изглежда чудесно, докато не чуеш компресора до стената.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще проверяваш локацията с кратко видео и реч при сравним час. Ще откриваш какво пречи на лицето, звука или фона и ще оставяш реална резервна позиция. Резултатът е избор, който можеш да повториш в работните условия на мястото.","deliverable":"В свое безопасно помещение направи три проби по 10 секунди с едно изречение. Сравни светлина, звук и фон. Проверявай и дребни видими данни; използвай измислени етикети за учебна проверка.","check":"Избраното място позволява разбираема реплика и четим предмет. Знаеш какво може да се премества. Резервът е действително достъпен, а не само красив ъгъл на снимка."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Снимка на помещението изглежда чудесно, докато не чуеш компресора до стената."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Оглед — предварителна проверка на мястото. Резервна позиция — друга потвърдена точка за снимане. Фон — всичко видимо зад основния обект, включително чужди хора и документи.\n\nОгледът е снимана и прослушана проверка при часа на бъдещата работа.\n\nТествай къде ще застане човекът, откъде идва светлината, как звучи гласът, какво се вижда на заден план и къде минават хората. Забележи контакти, ограничения за статив и достъп до тоалетна или почивка."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Променяй един фактор в пробите: позиция, фон, микрофон. Кратко видео с реч разкрива повече от галерия със снимки. Провери дали фирмени знаци, документи на стена, клиентски адреси или чужди лица ще попаднат в кадър. Планирай кога мястото се освобождава и как ще оставиш оборудването без да блокираш работа.\n\nГраница на решението: Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Уговори оглед в сравним час и получи достъп.\n2. Запиши кадър с реч на планираното място.\n3. Провери фон, шум, светлина и маршрут на кабелите.\n4. Потвърди с домакина какво може да се мести или показва."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Кафене разрешава снимки сутрин. Красивият ъгъл от снимките е до хладилна витрина, която се включва внезапно.\n\nРешение: Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза.\n\nКакво да провериш: Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза. Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени.","label":"Как го поправяш"},"before":{"text":"Избираш ъгъла само по снимката и оставяш проверката за след първия въпрос.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"В свое безопасно помещение направи три проби по 10 секунди с едно изречение. Сравни светлина, звук и фон. Проверявай и дребни видими данни; използвай измислени етикети за учебна проверка.\n\nПровери резултата: Избраното място позволява разбираема реплика и четим предмет. Знаеш какво може да се премества. Резервът е действително достъпен, а не само красив ъгъл на снимка.\n\nПримерна работна бележка: А е красиво, но шумно място; Б дава ясен глас, но показва чужд документ; В е изпълнимо и пази светлина, звук и фон. Избирам В или поправям Б и правя нов запис. Това са примерни условия за решението.\n\nАко не е изпълнено: Ако промениш фона, прослушай отново и провери светлината. Ако шумът идва на цикли, пробвай в съответния момент. Не записвай лични данни на истински хора за упражнението."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Статична снимка на празната стая в друг час."},{"id":"b","label":"Оценка само по размера и красотата на фона."},{"id":"c","label":"Кратък запис с реч при сравним час и работещо оборудване."}],"question":"Коя проба най-добре проверява бъдещата локация?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Кратък запис с реч при сравним час и работещо оборудване. Избраното място позволява разбираема реплика и четим предмет. Знаеш какво може да се премества. Резервът е действително достъпен, а не само красив ъгъл на снимка."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Кафене разрешава снимки сутрин. Красивият ъгъл от снимките е до хладилна витрина, която се включва внезапно.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза."},{"id":"b","label":"Приемам снимката за достатъчна и записвам до витрината без речева проба."},{"id":"c","label":"Спирам работата на витрината без потвърждение от домакина."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза.\n\nКакво да провериш: Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Използвай повече шумоподтискане след монтажа вместо проба."},{"id":"b","label":"Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"В свое безопасно помещение направи три проби по 10 секунди с едно изречение. Сравни светлина, звук и фон. Проверявай и дребни видими данни; използвай измислени етикети за учебна проверка.","takeaways":["Огледът е снимана и прослушана проверка при часа на бъдещата работа.","Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза.","Провери: Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Провери фон, шум, светлина и маршрут на кабелите."},{"id":"s1","text":"Уговори оглед в сравним час и получи достъп."},{"id":"s4","text":"Потвърди с домакина какво може да се мести или показва."},{"id":"s2","text":"Запиши кадър с реч на планираното място."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Уговори оглед в сравним час и получи достъп. → Запиши кадър с реч на планираното място. → Провери фон, шум, светлина и маршрут на кабелите. → Потвърди с домакина какво може да се мести или показва."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: В деня на снимките предвидената маса е заета от клиент.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Премини към потвърдения резервен ъгъл, направи нова аудио проба и не мести клиент без съгласие."},{"id":"b","label":"Избираш ъгъла само по снимката и оставяш проверката за след първия въпрос."},{"id":"c","label":"Използвай повече шумоподтискане след монтажа вместо проба."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Премини към потвърдения резервен ъгъл, направи нова аудио проба и не мести клиент без съгласие. Избраното място позволява разбираема реплика и четим предмет. Знаеш какво може да се премества. Резервът е действително достъпен, а не само красив ъгъл на снимка."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Пробата не предвижда всяко събитие. При промяна на човек, шум или достъп изборът се проверява отново."}}]},{"module":"s02-m06","lesson":"pv06-04","source_hash":"38f0e4006c78f60d341b3ff54d76a87a","objective":"Ще подреждаш багажа според това какво може да спре записа. Ще проверяваш захранване, свободно място, звук и копиране преди излизане. Резултатът е работещ минимален комплект и потвърден резерв за критична функция, а не просто пълна чанта.","hook":"Резервният обектив е в чантата, но резервна карта и батерия липсват.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще подреждаш багажа според това какво може да спре записа. Ще проверяваш захранване, свободно място, звук и копиране преди излизане. Резултатът е работещ минимален комплект и потвърден резерв за критична функция, а не просто пълна чанта.","deliverable":"С наличния телефон направи кратък запис, възпроизведи го и копирай на второ налично независимо място, ако имаш такова. Провери заряда и свободната памет. Без второ място не заявявай резервно копие.","check":"Записът се отваря, има достатъчно памет и работещ звук. Оригиналът остава запазен. Ако критичен резерв липсва, планът е ограничен или се отлага; файл не се изтрива по предположение."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Резервният обектив е в чантата, но резервна карта и батерия липсват."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Носител — карта или памет, върху която се записва файлът. Проверено копие — файл, чието копиране и четимост са проверени. Съвместимост — дали кабелът, устройството и захранването действително работят заедно.\n\nПодреждай багажа около видовете провал: няма захранване, няма запис, няма звук, няма безопасен монтаж.\n\nСписъкът за конкретния проект включва заредени батерии, празни проверени карти, микрофон и слушалки, надежден монтаж, кабели и маркировки. Провери съвместимостта и състоянието, а не броя предмети."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Направи пробен път от камерата до компютъра: запис, възпроизвеждане, копие. Маркирай коя карта е използвана и не форматирай заснет материал, преди да имаш проверени копия. Постави дребните резервни части там, където можеш да ги намериш по време на интервюто; списъкът работи само ако се използва преди излизане и при прибиране.\n\nГраница на решението: Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Преброй критичните режими на отказ за този проект.\n2. Провери батерии, медии, микрофон и закрепване с кратък запис.\n3. Подреди основно и резервно средство за всяка критична функция.\n4. Отметни комплекта преди тръгване и след края на деня."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"На снимки извън града без магазин наблизо картата на камерата се запълва след първия час.\n\nРешение: Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал.\n\nКакво да провериш: Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал. Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал.","label":"Как го поправяш"},"before":{"text":"Изтриваш по-старите добри кадри, защото имаш втори обектив, но не и проверено копие.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"С наличния телефон направи кратък запис, възпроизведи го и копирай на второ налично независимо място, ако имаш такова. Провери заряда и свободната памет. Без второ място не заявявай резервно копие.\n\nПровери резултата: Записът се отваря, има достатъчно памет и работещ звук. Оригиналът остава запазен. Ако критичен резерв липсва, планът е ограничен или се отлага; файл не се изтрива по предположение.\n\nПримерна работна бележка: Основен телефон: зареден, достатъчно свободна памет, 10-секундният запис се отваря със звук. Копие: на второ независимо налично място, възпроизведено оттам. Ако такова няма, записвам „нямам резервно копие“, вместо да броя две папки в един телефон.\n\nАко не е изпълнено: Не изтривай или форматирай носителя, преди да провериш копието и нужния брой независими копия за проекта. При липсващ критичен резерв не обещавай надеждност на клиентски снимачен ден."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Наличието на второ устройство без проверка на захранването."},{"id":"b","label":"Проверено съвместимо средство и възпроизведен файл от него."},{"id":"c","label":"Два файлови пътя към единственото копие на същия носител."}],"question":"Кое доказва, че резервът е реален?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Проверено съвместимо средство и възпроизведен файл от него. Записът се отваря, има достатъчно памет и работещ звук. Оригиналът остава запазен. Ако критичен резерв липсва, планът е ограничен или се отлага; файл не се изтрива по предположение."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"На снимки извън града без магазин наблизо картата на камерата се запълва след първия час.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Форматирам използваната карта след копиране, без да отворя копията."},{"id":"b","label":"Изтривам най-старите кадри, за да запазя снимачния график."},{"id":"c","label":"Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал.\n\nКакво да провериш: Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Купи още обективи вместо да провериш записващата верига."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"С наличния телефон направи кратък запис, възпроизведи го и копирай на второ налично независимо място, ако имаш такова. Провери заряда и свободната памет. Без второ място не заявявай резервно копие.","takeaways":["Подреждай багажа около видовете провал: няма захранване, няма запис, няма звук, няма безопасен монтаж.","Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал.","Провери: Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Подреди основно и резервно средство за всяка критична функция."},{"id":"s1","text":"Преброй критичните режими на отказ за този проект."},{"id":"s4","text":"Отметни комплекта преди тръгване и след края на деня."},{"id":"s2","text":"Провери батерии, медии, микрофон и закрепване с кратък запис."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Преброй критичните режими на отказ за този проект. → Провери батерии, медии, микрофон и закрепване с кратък запис. → Подреди основно и резервно средство за всяка критична функция. → Отметни комплекта преди тръгване и след края на деня."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Излиза, че резервният рекордер използва друг тип захранване.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Изтриваш по-старите добри кадри, защото имаш втори обектив, но не и проверено копие."},{"id":"b","label":"Купи още обективи вместо да провериш записващата верига."},{"id":"c","label":"Провери реалните батерии и кабели за него преди тръгване; ако липсват, планирай друг проверен резерв."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Провери реалните батерии и кабели за него преди тръгване; ако липсват, планирай друг проверен резерв. Записът се отваря, има достатъчно памет и работещ звук. Оригиналът остава запазен. Ако критичен резерв липсва, планът е ограничен или се отлага; файл не се изтрива по предположение."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Не се изисква покупка на резерв за учебна 10-секундна проба. При клиентски снимачен ден липсващият резерв е реално ограничение, което трябва да бъде съобщено."}}]},{"module":"s02-m06","lesson":"pv06-05","source_hash":"22a5bd42dd2f09dcc0658ed8e9243cbf","objective":"Ще решаваш дали новата техника отстранява действителен проблем. Ще различаваш поправка чрез позиция, звук или организация от нужда от ново устройство. Резултатът е избор с обоснована полза и пълен разход, без автоматично насочване към покупка.","hook":"Новата камера пристига, но клиентът пак не разбира гласа в рекламата.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще решаваш дали новата техника отстранява действителен проблем. Ще различаваш поправка чрез позиция, звук или организация от нужда от ново устройство. Резултатът е избор с обоснована полза и пълен разход, без автоматично насочване към покупка.","deliverable":"Използвай собствен неуспешен кадър или случая с кухо интервю. Първо пробвай по-близък запис и друго място. Реши въпроса за покупка след сравнение, а не по реклама на модела.","check":"Назован е конкретен дефект и е проверена промяна. Покупката има отношение към този дефект. Ако няма проба с новата техника, ефектът остава непотвърден."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Новата камера пристига, но клиентът пак не разбира гласа в рекламата."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Общ разход — покупка плюс нужни носители, захранване, транспорт и време за обучение. Сравнима проба — тест при достатъчно еднакви условия. Повтарящ се дефект — проблем, видим в повече от един конкретен запис.\n\nНазови дефекта от предишен проект и покажи как покупката ще го намали при същите условия.\n\nАко проблемът е говор отдалеч, близък микрофон и тиха стая могат да помогнат повече от нова камера. Ако видеото губи кадри при презапис, по-добра организация на медията е по-належаща от светлина за фон."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Направи малка проба: снимай една сцена с настоящия комплект, промени само начина на работа и виж дали провалът изчезва. Наем или заем на техника за едно снимане може да покаже разликата преди покупка. Сметни и допълнителните разходи: батерии, носители, стойки, транспорт, време за обучение. Не купувай спецификация, която няма място в този работен процес.\n\nГраница на решението: Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Опиши повторящ се дефект с конкретен файл.\n2. Пробвай поправка чрез позиция, светлина, звук или процес.\n3. Ако не стига, тествай наета/заемана техника при същите условия.\n4. Реши покупка според измеримата промяна и общия разход."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Фрийлансър снима интервюта в малки офиси. Купува по-скъп обектив, но отговорите още звучат кухо.\n\nРешение: Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект.\n\nКакво да провериш: В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект. В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината.","label":"Как го поправяш"},"before":{"text":"Поръчва нова камера, без да е сравнил по-близък микрофон и друго място.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Използвай собствен неуспешен кадър или случая с кухо интервю. Първо пробвай по-близък запис и друго място. Реши въпроса за покупка след сравнение, а не по реклама на модела.\n\nПровери резултата: Назован е конкретен дефект и е проверена промяна. Покупката има отношение към този дефект. Ако няма проба с новата техника, ефектът остава непотвърден.\n\nПримерна работна бележка: Дефект: кух далечен глас. Проба: по-близък микрофон и по-подходящо помещение. Ако това решава проблема, първата стъпка е организацията. Ако остава конкретна липса, пробвам заем или наем преди покупка и записвам пълния разход.\n\nАко не е изпълнено: Ако не можеш да покажеш дефекта в изнесения файл, уточни какво всъщност искаш да подобриш. Резолюцията на камерата не поправя акустика. Без сравнителен тест ползата от новата техника остава предположение."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Тествам близък микрофон и място, преди да реша коя техника липсва."},{"id":"b","label":"Преминавам към по-скъпа камера, защото тя е основното устройство."},{"id":"c","label":"Избирам най-висока резолюция, без да прослушам интервюто."}],"question":"Как избираш първата инвестиция за кух звук?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Тествам близък микрофон и място, преди да реша коя техника липсва. Назован е конкретен дефект и е проверена промяна. Покупката има отношение към този дефект. Ако няма проба с новата техника, ефектът остава непотвърден."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Фрийлансър снима интервюта в малки офиси. Купува по-скъп обектив, но отговорите още звучат кухо.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Поръчвам нов обектив заради проблема в гласа."},{"id":"b","label":"Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект."},{"id":"c","label":"Променям едновременно камера, микрофон и стая и приписвам всичко на покупката."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект.\n\nКакво да провериш: В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Избери техника по най-високата рекламирана резолюция."},{"id":"c","label":"Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Използвай собствен неуспешен кадър или случая с кухо интервю. Първо пробвай по-близък запис и друго място. Реши въпроса за покупка след сравнение, а не по реклама на модела.","takeaways":["Назови дефекта от предишен проект и покажи как покупката ще го намали при същите условия.","Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект.","Провери: В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Ако не стига, тествай наета/заемана техника при същите условия."},{"id":"s1","text":"Опиши повторящ се дефект с конкретен файл."},{"id":"s4","text":"Реши покупка според измеримата промяна и общия разход."},{"id":"s2","text":"Пробвай поправка чрез позиция, светлина, звук или процес."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Опиши повторящ се дефект с конкретен файл. → Пробвай поправка чрез позиция, светлина, звук или процес. → Ако не стига, тествай наета/заемана техника при същите условия. → Реши покупка според измеримата промяна и общия разход."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Нов клиент иска заснемане при светлина, която настоящият комплект не може да поддържа.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Избери техника по най-високата рекламирана резолюция."},{"id":"b","label":"Тествай нает подходящ източник на място, сметни повторяемостта на задачата и едва тогава избери покупка."},{"id":"c","label":"Поръчва нова камера, без да е сравнил по-близък микрофон и друго място."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Тествай нает подходящ източник на място, сметни повторяемостта на задачата и едва тогава избери покупка. Назован е конкретен дефект и е проверена промяна. Покупката има отношение към този дефект. Ако няма проба с новата техника, ефектът остава непотвърден."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Безплатният старт не означава, че всяка реална поръчка може да се изпълни без разход. Наем, заем или отказ от неподходящ проект също са решения."}}]},{"module":"s02-m06","lesson":"pv06-06","source_hash":"06ddd6256f00b0ca483a467f6fb04dc1","objective":"Ще подреждаш снимачния ден според достъп, светлина и наличност на хората. Ще оставяш време за проба, почивка и копиране и ще знаеш кои допълнителни кадри отпадат при закъснение. Резултатът е изпълним график с ясно решение при промяна.","hook":"На хартия има 12 кадъра за час. На терен всеки пренос на лампа взема десет минути.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще подреждаш снимачния ден според достъп, светлина и наличност на хората. Ще оставяш време за проба, почивка и копиране и ще знаеш кои допълнителни кадри отпадат при закъснение. Резултатът е изпълним график с ясно решение при промяна.","deliverable":"Реши учебен график с предварително потвърден достъп от 08:40: процес 09:00–09:20; говорител 12:00–12:20; край на достъпа 13:00. Добави проби, почивка и проверка на файловете. Разграничи два случая: губиш 20 минути от свободното време или пристигаш 20 минути след началото на процеса. В първия отпада допълнителен кадър; във втория изисквай потвърдено ново време или промени обхвата.","check":"Ограничените прозорци са спазени. Първо се пазят задължителният процес и говорът. Има време за безопасно прибиране и файлове, както и определен допълнителен кадър за отпадане."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"На хартия има 12 кадъра за час. На терен всеки пренос на лампа взема десет минути."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Установка — подредбата на камера, звук и светлина за определени кадри. Буфер — отделено време за отклонение. Задължителен кадър — без него основната задача не може да се изпълни.\n\nГрупирай кадрите по място и подготовка, а не само по реда във финалното видео.\n\nОтдели време за пристигане, настройка и проба, действителните дубли, промени на осветление и звук, почивки, копиране и прибиране. Посочи кога ключов човек или локация не са налични."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Постави задължителните кадри преди допълнителните и определи момент за решение „свиваме обхвата“. При разминаване не съкращавай проверката на звук и безопасното прибиране; махни или комбинирай най-малко важен план. Изпрати часовете на участниците като реални прозорци, не като гаранция за минута по минута.\n\nГраница на решението: Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Запиши фиксираните часове на хора, място и светлина.\n2. Групирай кадри по еднаква установка.\n3. Добави проби, почивки, копиране и буфер.\n4. Определи кои кадри отпадат първи при закъснение."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"В сладкарница фурната е достъпна сутрин, собственичката — по обед, а клиентите влизат следобед. Графикът от сценария започва с интервю.\n\nРешение: Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти.\n\nКакво да провериш: Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти. Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране.","label":"Как го поправяш"},"before":{"text":"Следваш монтажния ред на сцените и изпускаш единственото време за печене.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Реши учебен график с предварително потвърден достъп от 08:40: процес 09:00–09:20; говорител 12:00–12:20; край на достъпа 13:00. Добави проби, почивка и проверка на файловете. Разграничи два случая: губиш 20 минути от свободното време или пристигаш 20 минути след началото на процеса. В първия отпада допълнителен кадър; във втория изисквай потвърдено ново време или промени обхвата.\n\nПровери резултата: Ограничените прозорци са спазени. Първо се пазят задължителният процес и говорът. Има време за безопасно прибиране и файлове, както и определен допълнителен кадър за отпадане.\n\nПримерна работна бележка: Ориентировъчен учебен график: 08:40–09:00 проба; 09:00–09:20 процес; 11:45–12:00 говорна проба; 12:00–12:20 говорител; 12:20–12:40 проверка и копиране; 12:40–13:00 прибиране. Незадължителният общ план отпада при натиск във времето.\n\nАко не е изпълнено: Ако закъснението пропуска еднократния процес, премахването на допълнителен кадър не го връща. Нужни са потвърдено ново време или промяна на обхвата. Никой график не прави невъзможния прозорец изпълним."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Единствено по реда на сцените във финалния монтаж."},{"id":"b","label":"По най-красивите кадри, а ограничените хора остават за края."},{"id":"c","label":"По реални зависимости и прозорци на достъп, с време за проверки."}],"question":"По какво подреждаш снимачния ден?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"По реални зависимости и прозорци на достъп, с време за проверки. Ограничените прозорци са спазени. Първо се пазят задължителният процес и говорът. Има време за безопасно прибиране и файлове, както и определен допълнителен кадър за отпадане."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"В сладкарница фурната е достъпна сутрин, собственичката — по обед, а клиентите влизат следобед. Графикът от сценария започва с интервю.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти."},{"id":"b","label":"Започвам с интервюто по монтажния ред и изпускам печенето сутрин."},{"id":"c","label":"Премахвам аудио пробата, за да запазя всички допълнителни кадри."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти.\n\nКакво да провериш: Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Прехвърли всички забавени задачи в края и обещай, че ще се заснемат без нова смяна."},{"id":"b","label":"Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Реши учебен график с предварително потвърден достъп от 08:40: процес 09:00–09:20; говорител 12:00–12:20; край на достъпа 13:00. Добави проби, почивка и проверка на файловете. Разграничи два случая: губиш 20 минути от свободното време или пристигаш 20 минути след началото на процеса. В първия отпада допълнителен кадър; във втория изисквай потвърдено ново време или промени обхвата.","takeaways":["Групирай кадрите по място и подготовка, а не само по реда във финалното видео.","Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти.","Провери: Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Добави проби, почивки, копиране и буфер."},{"id":"s1","text":"Запиши фиксираните часове на хора, място и светлина."},{"id":"s4","text":"Определи кои кадри отпадат първи при закъснение."},{"id":"s2","text":"Групирай кадри по еднаква установка."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Запиши фиксираните часове на хора, място и светлина. → Групирай кадри по еднаква установка. → Добави проби, почивки, копиране и буфер. → Определи кои кадри отпадат първи при закъснение."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Ключовият човек закъснява с половин час.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Използвай времето за предметни кадри и звук от мястото, после актуализирай графика с нов прозорец за човека."},{"id":"b","label":"Следваш монтажния ред на сцените и изпускаш единственото време за печене."},{"id":"c","label":"Прехвърли всички забавени задачи в края и обещай, че ще се заснемат без нова смяна."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Използвай времето за предметни кадри и звук от мястото, после актуализирай графика с нов прозорец за човека. Ограничените прозорци са спазени. Първо се пазят задължителният процес и говорът. Има време за безопасно прибиране и файлове, както и определен допълнителен кадър за отпадане."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"За тази задача можеш да провериш времевите зависимости сам. Истинският график се потвърждава с хората, от които зависи."}}]},{"module":"s02-m06","lesson":"pv06-07","source_hash":"5d3e36e4c4e66accb23e05517b6fda69","objective":"Ще планираш допълващи кадри, които показват действието, за което се говори. Ще различаваш красив общ план от нужния кадър на проверка или резултат. В края ще имаш начало, действие и край на кратък процес, които можеш да монтираш честно.","hook":"Имаш десет красиви детайла на инструменти, но нито един кадър на самата работа.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще планираш допълващи кадри, които показват действието, за което се говори. Ще различаваш красив общ план от нужния кадър на проверка или резултат. В края ще имаш начало, действие и край на кратък процес, които можеш да монтираш честно.","deliverable":"Сними свой безопасен домашен процес: подготовка, едно действие и резултат. Вземи общ и детайлен кадър само ако дават различна информация. Не инсценирай непроверена клиентска услуга като доказателство.","check":"Кадърът действително показва съответното действие. Редът не създава неверен резултат. Липсващият важен момент се отбелязва, а не се прикрива с чужд красив материал."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Имаш десет красиви детайла на инструменти, но нито един кадър на самата работа."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"B-roll — допълващи кадри към основния разказ. Покритие — материалът, нужен за показване на действие или преход. Последователност — запазване на разбираемия ред между движения и предмети.\n\nB-roll трябва да доказва казаното и да покрива нужните преходи, не да пълни време.\n\nЗа всяко твърдение запиши видимо действие: начало, изпълнение и резултат. Вземи широк, среден и близък план само когато те дават различна информация. Отбележи необходимия звук на действието."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Планирай посоката на движенията и предметите между плановете: от коя ръка се взема материалът, къде се поставя и кога процесът се променя. Не снимай чужди лица или чувствителни екрани само защото са удобен фон. След първия снимачен блок отвори материалите и виж кой конкретен срез още няма покритие; допълни го, докато човекът и обектът са налични.\n\nГраница на решението: B-roll не бива да инсценира доказателство за услуга, която не е извършена."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Разпиши ключовите твърдения или движения.\n2. За всяко запиши начало, действие, резултат и нужен звук.\n3. Сними различни информативни дистанции и посоки.\n4. Прегледай материала и попълни липсващите монтажни връзки."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Майстор казва, че всяка поръчка се тества. Заснети са красиви рафтове и усмивка, но няма кадър на самия тест.\n\nРешение: Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение.\n\nКакво да провериш: Зрителят може да посочи на кадър действието, за което говорителят разказва."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение. Зрителят може да посочи на кадър действието, за което говорителят разказва.","label":"Как го поправяш"},"before":{"text":"Покриваш репликата с произволен кадър на инструмент и внушаваш проверка, която не се вижда.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Сними свой безопасен домашен процес: подготовка, едно действие и резултат. Вземи общ и детайлен кадър само ако дават различна информация. Не инсценирай непроверена клиентска услуга като доказателство.\n\nПровери резултата: Кадърът действително показва съответното действие. Редът не създава неверен резултат. Липсващият важен момент се отбелязва, а не се прикрива с чужд красив материал.\n\nПримерна работна бележка: Репликата е „проверявам етикета“. Допълващият материал показва поглед към етикета, самата проверка и отделения проверен предмет. Красивият кадър на рафта може да даде среда, но не показва това действие.\n\nАко не е изпълнено: При липсваща проверка заснеми реалното допустимо действие или преработи твърдението. Не използвай кадър от друг резултат, така че да изглежда като доказателство за текущия случай."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Кадър на рафтовете, без показване на проверката."},{"id":"b","label":"Кадър на действителната проверка и нейния резултат."},{"id":"c","label":"Кадър на тест от друга поръчка, представен като текущия."}],"question":"Кой допълващ кадър подкрепя твърдението „проверяваме поръчката“?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Кадър на действителната проверка и нейния резултат. Кадърът действително показва съответното действие. Редът не създава неверен резултат. Липсващият важен момент се отбелязва, а не се прикрива с чужд красив материал."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Майстор казва, че всяка поръчка се тества. Заснети са красиви рафтове и усмивка, но няма кадър на самия тест.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Покривам твърдението с инструмент, който не показва теста."},{"id":"b","label":"Поставям резултат от друг процес, без да обознача разликата."},{"id":"c","label":"Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение.\n\nКакво да провериш: Зрителят може да посочи на кадър действието, за което говорителят разказва."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"B-roll не бива да инсценира доказателство за услуга, която не е извършена."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Вмъкни красив кадър от друга поръчка и го представи като същия тест."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"B-roll не бива да инсценира доказателство за услуга, която не е извършена."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Сними свой безопасен домашен процес: подготовка, едно действие и резултат. Вземи общ и детайлен кадър само ако дават различна информация. Не инсценирай непроверена клиентска услуга като доказателство.","takeaways":["B-roll трябва да доказва казаното и да покрива нужните преходи, не да пълни време.","Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение.","Провери: Зрителят може да посочи на кадър действието, за което говорителят разказва."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Сними различни информативни дистанции и посоки."},{"id":"s1","text":"Разпиши ключовите твърдения или движения."},{"id":"s4","text":"Прегледай материала и попълни липсващите монтажни връзки."},{"id":"s2","text":"За всяко запиши начало, действие, резултат и нужен звук."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. B-roll не бива да инсценира доказателство за услуга, която не е извършена."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Разпиши ключовите твърдения или движения. → За всяко запиши начало, действие, резултат и нужен звук. → Сними различни информативни дистанции и посоки. → Прегледай материала и попълни липсващите монтажни връзки."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Процесът вече е приключил и няма разрешение за повторение.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Покриваш репликата с произволен кадър на инструмент и внушаваш проверка, която не се вижда."},{"id":"b","label":"Вмъкни красив кадър от друга поръчка и го представи като същия тест."},{"id":"c","label":"Използвай наличните честни кадри, промени формулировката на твърдението или отбележи липсата за нов снимачен ден."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Използвай наличните честни кадри, промени формулировката на твърдението или отбележи липсата за нов снимачен ден. Кадърът действително показва съответното действие. Редът не създава неверен резултат. Липсващият важен момент се отбелязва, а не се прикрива с чужд красив материал."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Показването на едно действие не доказва твърдение за всички поръчки. Проверяват се и думите, и границата на визуалното доказателство."}}]},{"module":"s02-m06","lesson":"pv06-08","source_hash":"7415ab8eaa1c4a93f0f67a8b746c7bc7","objective":"Ще решаваш дали да поискаш повторение по конкретен дефект. Ще преглеждаш звук, факт и действие, вместо да снимаш фиксиран брой дубъли. Резултатът е маркиран използваем вариант и целево повторение само когато има причина.","hook":"Десетият дубъл е изтощен, а първият е бил добър — само че никой не го е проверил.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще решаваш дали да поискаш повторение по конкретен дефект. Ще преглеждаш звук, факт и действие, вместо да снимаш фиксиран брой дубъли. Резултатът е маркиран използваем вариант и целево повторение само когато има причина.","deliverable":"Запиши три кратки собствени демонстрации. След всяка прослушай ключовата дума и провери предмета. Продължи към следващ кадър, когато условията са изпълнени; не повтаряй само по навик.","check":"За избора има конкретен проверен файл. При повторение е назован дефектът. По-естественият тон се запазва само ако фактът и звукът също работят."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Десетият дубъл е изтощен, а първият е бил добър — само че никой не го е проверил."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Дубъл — отделен запис на същата реплика или действие. Използваем материал — покрива смисъла и техническите условия на задачата. Маркиране — записване кой файл и момент ще бъдат използвани.\n\nПреди повторение назови конкретния дефект: факт, тон, кадър, звук или движение.\n\nПървият дубъл често показва естествена енергия; вторият може да изчисти факт или движение. Няма магически брой повторения. Кратко възпроизвеждане със звук спестява повторения без цел."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Раздели „може да се монтира“ от „идеален“. Ако имаш чиста пълна фраза и нужните преходи, снимай вариант само с друга интонация или по-кратък отговор, когато проектът го иска. Ако проблемът е засядане от напрежение, промени въпроса или направи пауза, вместо да повтаряш същата команда. Маркирай успешните дубъли по файл и секунда.\n\nГраница на решението: При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Определи какво трябва да се види и чуе.\n2. Сними един пълен дубъл и го прослушай.\n3. Назови конкретния проблем, преди да поискаш повторение.\n4. Сними целеви дубъл или продължи, ако материалът вече покрива задачата."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Пекар отговаря добре за процеса на втория дубъл. Режисьорът иска още пет „за всеки случай“, но човекът започва да говори механично.\n\nРешение: Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли.\n\nКакво да провериш: Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли. Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен.","label":"Как го поправяш"},"before":{"text":"Повтаряш фразата докато изчезне естественият тон, без да провериш втория файл.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Запиши три кратки собствени демонстрации. След всяка прослушай ключовата дума и провери предмета. Продължи към следващ кадър, когато условията са изпълнени; не повтаряй само по навик.\n\nПровери резултата: За избора има конкретен проверен файл. При повторение е назован дефектът. По-естественият тон се запазва само ако фактът и звукът също работят.\n\nПримерна работна бележка: Дубъл 1 има добра реч, но предметът е закрит. Дубъл 2 показва предмета и пази ключовите думи; маркирам него. Дубъл 3 не е нужен, ако липсващ вариант или дефект вече няма. Не оценявам увереността на човека по броя повторения.\n\nАко не е изпълнено: Преди нов дубъл назови какво ще се промени. Ако нищо конкретно не липсва, премини нататък. При повторение провери и дали новият вариант не губи вече работещата част."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Когато установен дефект или нужният вариант не е покрит от материала."},{"id":"b","label":"Когато винаги правим поне осем повторения за всяка реплика."},{"id":"c","label":"Когато не сме прослушали добрия запис, но искаме още варианти."}],"question":"Кога има основание за още един дубъл?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Когато установен дефект или нужният вариант не е покрит от материала. За избора има конкретен проверен файл. При повторение е назован дефектът. По-естественият тон се запазва само ако фактът и звукът също работят."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Пекар отговаря добре за процеса на втория дубъл. Режисьорът иска още пет „за всеки случай“, но човекът започва да говори механично.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Искам пет повторения, без да прегледам използваемия втори дубъл."},{"id":"b","label":"Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли."},{"id":"c","label":"Избирам най-късния файл само защото има най-много репетиции."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли.\n\nКакво да провериш: Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Снимай фиксирано поне осем дубъла на всяка реплика."},{"id":"c","label":"При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Запиши три кратки собствени демонстрации. След всяка прослушай ключовата дума и провери предмета. Продължи към следващ кадър, когато условията са изпълнени; не повтаряй само по навик.","takeaways":["Преди повторение назови конкретния дефект: факт, тон, кадър, звук или движение.","Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли.","Провери: Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Назови конкретния проблем, преди да поискаш повторение."},{"id":"s1","text":"Определи какво трябва да се види и чуе."},{"id":"s4","text":"Сними целеви дубъл или продължи, ако материалът вече покрива задачата."},{"id":"s2","text":"Сними един пълен дубъл и го прослушай."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Определи какво трябва да се види и чуе. → Сними един пълен дубъл и го прослушай. → Назови конкретния проблем, преди да поискаш повторение. → Сними целеви дубъл или продължи, ако материалът вече покрива задачата."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: След паузата откриваш, че най-добрият дубъл има щракване в ключовата дума.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Снимай фиксирано поне осем дубъла на всяка реплика."},{"id":"b","label":"Поискай целеви повторен отговор при същата обстановка и проверен микрофон, вместо да повтаряш целия разговор."},{"id":"c","label":"Повтаряш фразата докато изчезне естественият тон, без да провериш втория файл."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Поискай целеви повторен отговор при същата обстановка и проверен микрофон, вместо да повтаряш целия разговор. За избора има конкретен проверен файл. При повторение е назован дефектът. По-естественият тон се запазва само ако фактът и звукът също работят."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"По-дългата работа не е автоматично по-добра подготовка. Конкретната обратна връзка е за записа, а не оценка на човека."}}]},{"module":"s02-m06","lesson":"pv06-09","source_hash":"7cfd24ede6489d7839a934dc5d42973a","objective":"Ще подготвяш резервен ход за светлина, звук и достъп. Ще можеш да посочиш при какъв проблем спираш, кой решава промяната и дали алтернативата е действително възможна. Резултатът е малък план, който работи преди терена.","hook":"Слънцето се скрива, появява се шум или човекът за достъп вече не е на място. Подготви изпълним отговор за всяко критично условие.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще подготвяш резервен ход за светлина, звук и достъп. Ще можеш да посочиш при какъв проблем спираш, кой решава промяната и дали алтернативата е действително възможна. Резултатът е малък план, който работи преди терена.","deliverable":"Избери по един риск за домашната проба: слънце, шум и недостъпно място. За всеки избери изпълнимо действие. В учебния случай машината е неразрешена: правилното действие започва със спиране на този кадър.","check":"Алтернативата има реално време, място и нужните потвърждения. При опасно или неразрешено действие снимането спира. Промяната на обхвата е ясна за отговорния човек."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Слънцето се скрива, появява се шум или човекът за достъп вече не е на място. Подготви изпълним отговор за всяко критично условие."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Риск — възможност дадено условие да провали задачата. Ранен признак — наблюдение, което задейства проверка. План Б — предварително проверена друга възможност, а не разрешение за нарушение.\n\nРискът става управляем, когато има ранно предупреждение, собственик на решение и резервна сцена.\n\nЗапиши критичен риск, вероятен симптом, действие и кой дава разрешение. За светлина може да има резервна позиция, за шум — друг времеви прозорец, за достъп — алтернативен човек или кадър."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Определи условия, при които снимането спира: опасен кабел, липса на право за локация, невъзможен за разбиране звук, непотвърдени права за лице. Не решавай чужди разрешения с подпис „после“. Ако се включи резервният план, съобщи на клиента каква информация или кадри ще се променят, преди да продължиш.\n\nГраница на решението: Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Назови три най-скъпи провала за проекта.\n2. Задай измерим симптом и човек за решение.\n3. Избери безопасна алтернатива преди снимачния ден.\n4. При проблем спри, потвърди промяната и направи нова проба."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Видео в работилница трябва да покаже машина. На терен се оказва, че демонстрацията днес не е разрешена по съображения за безопасност.\n\nРешение: Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента.\n\nКакво да провериш: Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента. Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър.","label":"Как го поправяш"},"before":{"text":"Пускаш машината „само за десет секунди“, защото вече е обещана в сценария.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Избери по един риск за домашната проба: слънце, шум и недостъпно място. За всеки избери изпълнимо действие. В учебния случай машината е неразрешена: правилното действие започва със спиране на този кадър.\n\nПровери резултата: Алтернативата има реално време, място и нужните потвърждения. При опасно или неразрешено действие снимането спира. Промяната на обхвата е ясна за отговорния човек.\n\nПримерна работна бележка: Слънце: местя домашната проба извън директния лъч и проверявам пак. Шум: чакам безопасен тих момент или сменям потвърденото място. Недостъпна машина: не снимам; търся разрешена алтернатива или изваждам кадъра от обещания обхват.\n\nАко не е изпълнено: Ако резервът зависи от непотвърден човек или помещение, той още не е резерв. При опасно действие спри кадъра. Промяната трябва да е ясна за отговорния за обхвата и срока."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Когато е записан в документа, дори мястото да не е достъпно."},{"id":"b","label":"Когато позволява обещания кадър да бъде заснет независимо от ограниченията."},{"id":"c","label":"Когато може да се изпълни и е потвърден преди използването му."}],"question":"Кога план Б е действителен резерв?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Когато може да се изпълни и е потвърден преди използването му. Алтернативата има реално време, място и нужните потвърждения. При опасно или неразрешено действие снимането спира. Промяната на обхвата е ясна за отговорния човек."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Видео в работилница трябва да покаже машина. На терен се оказва, че демонстрацията днес не е разрешена по съображения за безопасност.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента."},{"id":"b","label":"Снимам машината за кратко, защото кадърът вече е в сценария."},{"id":"c","label":"Заменям истинската демонстрация със симулация, представена като същото действие."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента.\n\nКакво да провериш: Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Разчитай на софтуер, за да превърне опасна или несъществуваща сцена в доказателство."},{"id":"b","label":"Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Избери по един риск за домашната проба: слънце, шум и недостъпно място. За всеки избери изпълнимо действие. В учебния случай машината е неразрешена: правилното действие започва със спиране на този кадър.","takeaways":["Рискът става управляем, когато има ранно предупреждение, собственик на решение и резервна сцена.","Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента.","Провери: Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Избери безопасна алтернатива преди снимачния ден."},{"id":"s1","text":"Назови три най-скъпи провала за проекта."},{"id":"s4","text":"При проблем спри, потвърди промяната и направи нова проба."},{"id":"s2","text":"Задай измерим симптом и човек за решение."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Назови три най-скъпи провала за проекта. → Задай измерим симптом и човек за решение. → Избери безопасна алтернатива преди снимачния ден. → При проблем спри, потвърди промяната и направи нова проба."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: План Б изисква локация, която клиентът не може да предостави.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Отбележи плана като невалиден и потърси вариант, който може да бъде потвърден предварително."},{"id":"b","label":"Пускаш машината „само за десет секунди“, защото вече е обещана в сценария."},{"id":"c","label":"Разчитай на софтуер, за да превърне опасна или несъществуваща сцена в доказателство."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Отбележи плана като невалиден и потърси вариант, който може да бъде потвърден предварително. Алтернативата има реално време, място и нужните потвърждения. При опасно или неразрешено действие снимането спира. Промяната на обхвата е ясна за отговорния човек."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"AI може да помогне да изброиш рискове, но не потвърждава достъп, състояние на машина или разрешение. Проверяваш ги в действителния процес."}}]},{"module":"s02-m06","lesson":"pv06-10","source_hash":"3464dad2f5d7d53d80c8472d5e574856","objective":"Ще правиш кратка репетиция, която проверява истинското действие, дрехи, предмет и звук. Ще откриваш конкретния момент, в който ръка закрива етикет или предмет удря микрофона. В края ще имаш поправена проба преди дългия или неповторимия запис.","hook":"Празният кадър е перфектен; щом човекът седне, микрофонът търка сакото и ръката закрива продукта.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще правиш кратка репетиция, която проверява истинското действие, дрехи, предмет и звук. Ще откриваш конкретния момент, в който ръка закрива етикет или предмет удря микрофона. В края ще имаш поправена проба преди дългия или неповторимия запис.","deliverable":"Изпълни 15-секундно безопасно действие със свой предмет и реч. Провери най-трудния момент. Промени само позицията на предмета или микрофона и повтори. При еднократен продукт използвай заместител за движението.","check":"В пробата се вижда важният надпис и се чува ключовата дума. Промяната поправя назования дефект. Заместителят проверява движението, но не доказва поведението на истинския продукт."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Празният кадър е перфектен; щом човекът седне, микрофонът търка сакото и ръката закрива продукта."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Репетиция — предварително изпълнение за проверка на условията. Неповторим момент — действие, което не може безопасно или честно да се повтори. Заместител — учебен предмет, който не представяш като истинския продукт.\n\nРепетирай действието, което ще снимаш, а не празна сцена с красив фокус.\n\nВключи истинския човек, облекло, предмет, звук и път на движение. Провери във видеото начало, ключова реплика и край на действието. Не е нужно дълго разиграване, но пробата трябва да покаже какво може да провали кадъра."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Прегледай записа веднага и назови само проверимите проблеми: дреха шуми в определен момент, лице излиза от светлината, ръка закрива етикета. Промени позиция, звук или движение и повтори същата проба. Ако сцената включва неповторим момент, направи съкратена репетиция без да го изхабяваш и подготви резервен план.\n\nГраница на решението: Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Постави участник и предмет в истинските им позиции.\n2. Пусни кратко пълно действие със запис на звук.\n3. Прослушай и погледни най-трудния момент.\n4. Поправи една конкретна причина и повтори пробата."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Шеф-готвач показва пълнене на буркани. При първа проба етикетът се обръща от камерата, а метален капак удря микрофона.\n\nРешение: Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа.\n\nКакво да провериш: На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа. На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори.","label":"Как го поправяш"},"before":{"text":"Казваш „ще оправим в монтажа“ и започваш цялата серия буркани.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Изпълни 15-секундно безопасно действие със свой предмет и реч. Провери най-трудния момент. Промени само позицията на предмета или микрофона и повтори. При еднократен продукт използвай заместител за движението.\n\nПровери резултата: В пробата се вижда важният надпис и се чува ключовата дума. Промяната поправя назования дефект. Заместителят проверява движението, но не доказва поведението на истинския продукт.\n\nПримерна работна бележка: При пълната проба ръката закрива надписа и предметът удря близкия микрофон. Променям само безопасната позиция и записвам пак. Ако използвам заместител, отбелязвам, че съм проверил движението, а не окончателния продукт.\n\nАко не е изпълнено: Статичната снимка не проверява движение и звук. Възпроизведи най-трудния момент; повтори именно него след поправката. Пази единствения клиентски продукт и необходимите разрешения."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Статичен кадър без човека, движението и предмета."},{"id":"b","label":"Кратко пълно действие с реалните условия и запис на звук."},{"id":"c","label":"Многократно изпълнение с единствения продукт без потвърдено разрешение."}],"question":"Коя репетиция проверява сцената най-добре?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Кратко пълно действие с реалните условия и запис на звук. В пробата се вижда важният надпис и се чува ключовата дума. Промяната поправя назования дефект. Заместителят проверява движението, но не доказва поведението на истинския продукт."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Шеф-готвач показва пълнене на буркани. При първа проба етикетът се обръща от камерата, а метален капак удря микрофона.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Оправям само надписа и не прослушвам удара върху репликата."},{"id":"b","label":"Пускам еднократното действие без проверка на кадъра и микрофона."},{"id":"c","label":"Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа.\n\nКакво да провериш: На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Сменяй пет настройки наведнъж и запомни кое точно е помогнало."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Изпълни 15-секундно безопасно действие със свой предмет и реч. Провери най-трудния момент. Промени само позицията на предмета или микрофона и повтори. При еднократен продукт използвай заместител за движението.","takeaways":["Репетирай действието, което ще снимаш, а не празна сцена с красив фокус.","Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа.","Провери: На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Прослушай и погледни най-трудния момент."},{"id":"s1","text":"Постави участник и предмет в истинските им позиции."},{"id":"s4","text":"Поправи една конкретна причина и повтори пробата."},{"id":"s2","text":"Пусни кратко пълно действие със запис на звук."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Постави участник и предмет в истинските им позиции. → Пусни кратко пълно действие със запис на звук. → Прослушай и погледни най-трудния момент. → Поправи една конкретна причина и повтори пробата."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Продуктът може да се използва само веднъж и проба с него не е възможна.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Казваш „ще оправим в монтажа“ и започваш цялата серия буркани."},{"id":"b","label":"Сменяй пет настройки наведнъж и запомни кое точно е помогнало."},{"id":"c","label":"Репетирай с празна опаковка или заместител със сходен размер; осигури достатъчно камери/покритие за единствения истински дубъл."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Репетирай с празна опаковка или заместител със сходен размер; осигури достатъчно камери/покритие за единствения истински дубъл. В пробата се вижда важният надпис и се чува ключовата дума. Промяната поправя назования дефект. Заместителят проверява движението, но не доказва поведението на истинския продукт."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Правилната репетиция проверява причината за провал. Не се обявява за пълно заснемане на реалния резултат."}}]},{"module":"s02-m06","lesson":"pv06-11","source_hash":"6888c8af08361700e38c25297652a4c4","objective":"Ще водиш човек през записа с ясна задача, кратък въпрос и конкретна обратна връзка. Ще проверяваш дали колебанието идва от неясна употреба, труден текст или непотвърден факт. Резултатът е по-подреден разговор, без натиск и обещание, че всеки участник ще се почувства еднакво.","hook":"Общото „отпусни се“ не казва какво трябва да се промени в записа. Кратката конкретна задача дава по-ясна посока.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще водиш човек през записа с ясна задача, кратък въпрос и конкретна обратна връзка. Ще проверяваш дали колебанието идва от неясна употреба, труден текст или непотвърден факт. Резултатът е по-подреден разговор, без натиск и обещание, че всеки участник ще се почувства еднакво.","deliverable":"С доброволен пълнолетен познат проведи кратък пробен разговор за безопасна обща тема. Обясни предварително, че е учебен и как ще се пази записът. При липса на участник репетирай инструкциите сам; това още не е интервю.","check":"Употребата е ясна, въпросът е конкретен и обратната връзка е за репликата. При отказ сменяш въпроса или формата. Не извличаш частен клиентски пример, за да изпълниш задачата."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Общото „отпусни се“ не казва какво трябва да се промени в записа. Кратката конкретна задача дава по-ясна посока."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Конкретна обратна връзка — назовава работеща или неработеща част от записа. Употреба — къде и за какво ще се използва видеото. Доброволно участие — човекът разбира задачата и не е притискан да участва.\n\nДай проста задача, кратък въпрос и право на повторение; обясни какво ще използваш от записа.\n\nЗапочни с нещо, което човекът прави всеки ден, или с лесен конкретен въпрос. Пази малък брой хора около камерата и дай време за пробен дубъл без публика. Кажи „Това начало работи, нека повторим последната мисъл по-бавно“, вместо обща оценка на човека."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Провери дали колебанието идва от неясна употреба, твърде много текст, непотвърден факт или нежелание за участие. Това са възможни причини за конкретния разговор, а не диагноза. Изясни задачата и остави възможност човекът да не отговори или да спре.\n\nУговорете предварително как ще се уточняват факти и как ще се използва записът. Не променяй смисъла тайно в монтажа. При неточност върни конкретното твърдение за проверка. При отказ от участие смени формата или говорителя и следвай приложимите условия за употреба на вече направения запис.\n\nГраница на решението: Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Обясни употреба, време и как протича записа.\n2. Започни с лесно конкретно действие или въпрос.\n3. Дай една точна обратна връзка след проба.\n4. Провери смисъла и звука преди да продължиш."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Счетоводителка трябва да обясни нова услуга. На четвъртия дубъл чете все по-бързо и бърка условие за цена.\n\nРешение: Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж.\n\nКакво да провериш: Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж. Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани.","label":"Как го поправяш"},"before":{"text":"Повтаряш „по-естествено!“ без да ѝ кажеш коя част вече е добра.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"С доброволен пълнолетен познат проведи кратък пробен разговор за безопасна обща тема. Обясни предварително, че е учебен и как ще се пази записът. При липса на участник репетирай инструкциите сам; това още не е интервю.\n\nПровери резултата: Употребата е ясна, въпросът е конкретен и обратната връзка е за репликата. При отказ сменяш въпроса или формата. Не извличаш частен клиентски пример, за да изпълниш задачата.\n\nПримерна работна бележка: Инструкция: „Това е учебен запис; ще го пазим само за уговорената цел. Кажи как правиш тази една стъпка. Можем да повторим или да спрем.“ След пробата: „Началото е ясно; последното условие не се чу — повтори само него.“\n\nАко не е изпълнено: При колебание изясни употребата и задачата. При отказ смени въпроса или формата. При непотвърден факт върни въпроса за проверка; не търси по-убедително произнасяне на същото непроверено обещание."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"„Началото е ясно; повтори само последното условие по-бавно.“"},{"id":"b","label":"„Просто бъди уверен и не мисли за камерата.“"},{"id":"c","label":"„Трябва да разкажеш личния случай, защото вече сме започнали.“"}],"question":"Коя обратна връзка помага на конкретния запис?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"„Началото е ясно; повтори само последното условие по-бавно.“ Употребата е ясна, въпросът е конкретен и обратната връзка е за репликата. При отказ сменяш въпроса или формата. Не извличаш частен клиентски пример, за да изпълниш задачата."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Счетоводителка трябва да обясни нова услуга. На четвъртия дубъл чете все по-бързо и бърка условие за цена.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Искам още по-бърз дубъл, без да уточня бърканото ценово условие."},{"id":"b","label":"Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж."},{"id":"c","label":"Хваля говорителя общо, но оставям причината за напрежението неизяснена."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж.\n\nКакво да провериш: Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Промени текста тайно в монтажа така, че участникът да звучи по-уверено."},{"id":"c","label":"Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"С доброволен пълнолетен познат проведи кратък пробен разговор за безопасна обща тема. Обясни предварително, че е учебен и как ще се пази записът. При липса на участник репетирай инструкциите сам; това още не е интервю.","takeaways":["Дай проста задача, кратък въпрос и право на повторение; обясни какво ще използваш от записа.","Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж.","Провери: Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Дай една точна обратна връзка след проба."},{"id":"s1","text":"Обясни употреба, време и как протича записа."},{"id":"s4","text":"Провери смисъла и звука преди да продължиш."},{"id":"s2","text":"Започни с лесно конкретно действие или въпрос."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Обясни употреба, време и как протича записа. → Започни с лесно конкретно действие или въпрос. → Дай една точна обратна връзка след проба. → Провери смисъла и звука преди да продължиш."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Човекът казва, че не желае да говори за личен клиентски случай.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Промени текста тайно в монтажа така, че участникът да звучи по-уверено."},{"id":"b","label":"Премини към анонимизиран процес или друг пример, който той доброволно може да обясни."},{"id":"c","label":"Повтаряш „по-естествено!“ без да ѝ кажеш коя част вече е добра."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Премини към анонимизиран процес или друг пример, който той доброволно може да обясни. Употребата е ясна, въпросът е конкретен и обратната връзка е за репликата. При отказ сменяш въпроса или формата. Не извличаш частен клиентски пример, за да изпълниш задачата."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Страх от излагане, неясни очаквания или претоварен текст са възможни обяснения в конкретен разговор. Не диагностицираш човека и не използваш психологическа схема за натиск."}}]},{"module":"s02-m06","lesson":"pv06-12","source_hash":"235b95744d20be5cb574013acd3cfab5","objective":"Ще превръщаш рекламно твърдение в кратък въпрос за действие, пример и проверка. Ще изслушваш отговора и ще отделяш фактите, които трябва да се потвърдят. Резултатът е конкретна мисъл, която може да се покаже, вместо заучен суперлатив.","hook":"На „Как сте по-добри от конкуренцията?“ получаваш пет общи прилагателни и нито един кадър.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще превръщаш рекламно твърдение в кратък въпрос за действие, пример и проверка. Ще изслушваш отговора и ще отделяш фактите, които трябва да се потвърдят. Резултатът е конкретна мисъл, която може да се покаже, вместо заучен суперлатив.","deliverable":"Използвай учебната фраза „качеството е в основата“. Избери въпрос за конкретната проверка на една партида, после въпрос какво става при отклонение. Не изисквай имена или данни на реални клиенти.","check":"Въпросът допуска и неудобен отговор, без да подсказва похвала. Действието, резултатът и ограничението са разграничени. Непотвърдено число остава за проверка."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"На „Как сте по-добри от конкуренцията?“ получаваш пет общи прилагателни и нито един кадър."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Насочващ въпрос — подсказва желания отговор. Уточняващ въпрос — търси подробност след отговора. Проверим факт — може да се свери с конкретен източник, действие или документ.\n\nИскай случай и действие: какво се случи, какво избрахте, какъв резултат наблюдавахте.\n\nКраткият въпрос оставя място за разказ. „Разкажи за последния клиент, на когото помогна“ дава по-добър материал от „Кажи, че сте най-добрите“. След конкретния случай попитай за доказателство, ограничение и какво не е проработило."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Изслушай отговора докрай, не задавай втори въпрос върху първия. Отбележи фраза, която изисква проверка: число, срок, резултат или здравно/финансово обещание. Планирай покривни кадри за действията, които участникът описва. Когато отговорът е само лозунг, помоли за един конкретен ден, предмет или действие.\n\nГраница на решението: Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Запиши какво зрителят трябва да разбере.\n2. Задай кратък въпрос за реален случай.\n3. Попитай какво се вижда, как е проверено и какви са границите.\n4. Маркирай ключови факти за потвърждение и кадри за покритие."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Производител на халва казва „качеството е в основата“. Трябва ти видео за реалното производство.\n\nРешение: Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре.\n\nКакво да провериш: В отговора има конкретно действие и граница, които могат да се проверят и покажат."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре. В отговора има конкретно действие и граница, които могат да се проверят и покажат.","label":"Как го поправяш"},"before":{"text":"Насочваш го да повтори лозунга с повече ентусиазъм.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Използвай учебната фраза „качеството е в основата“. Избери въпрос за конкретната проверка на една партида, после въпрос какво става при отклонение. Не изисквай имена или данни на реални клиенти.\n\nПровери резултата: Въпросът допуска и неудобен отговор, без да подсказва похвала. Действието, резултатът и ограничението са разграничени. Непотвърдено число остава за проверка.\n\nПримерна работна бележка: Първи въпрос: „Как проверявате една партида?“ След отговора: „Какво правите, ако проверката покаже отклонение?“ Отделям описаното действие от непотвърденото число и планирам кадър само на действително достъпния процес.\n\nАко не е изпълнено: Ако получаваш общи прилагателни, поискай един конкретен пример и граница. Ако задаваш въпрос с очаквана похвала, преформулирай го така, че да допуска и неудобен отговор. Не изисквай чужди клиентски данни."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"„Кажете защо качеството ви е най-добро на пазара.“"},{"id":"b","label":"„Нали всички клиенти са доволни от всяка поръчка?“"},{"id":"c","label":"„Как проверявате една партида и какво правите при отклонение?“"}],"question":"Кой въпрос може да даде проверим материал за производството?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"„Как проверявате една партида и какво правите при отклонение?“ Въпросът допуска и неудобен отговор, без да подсказва похвала. Действието, резултатът и ограничението са разграничени. Непотвърдено число остава за проверка."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Производител на халва казва „качеството е в основата“. Трябва ти видео за реалното производство.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре."},{"id":"b","label":"Искам участникът да повтори лозунга с повече ентусиазъм."},{"id":"c","label":"Подсказвам, че няма отклонения, преди да чуя реалния процес."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре.\n\nКакво да провериш: В отговора има конкретно действие и граница, които могат да се проверят и покажат."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Задай наведнъж три въпроса и после избери удобния отговор."},{"id":"b","label":"Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Използвай учебната фраза „качеството е в основата“. Избери въпрос за конкретната проверка на една партида, после въпрос какво става при отклонение. Не изисквай имена или данни на реални клиенти.","takeaways":["Искай случай и действие: какво се случи, какво избрахте, какъв резултат наблюдавахте.","Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре.","Провери: В отговора има конкретно действие и граница, които могат да се проверят и покажат."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Попитай какво се вижда, как е проверено и какви са границите."},{"id":"s1","text":"Запиши какво зрителят трябва да разбере."},{"id":"s4","text":"Маркирай ключови факти за потвърждение и кадри за покритие."},{"id":"s2","text":"Задай кратък въпрос за реален случай."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Запиши какво зрителят трябва да разбере. → Задай кратък въпрос за реален случай. → Попитай какво се вижда, как е проверено и какви са границите. → Маркирай ключови факти за потвърждение и кадри за покритие."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Човекът започва да разкрива лични данни на клиент.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Спрете, уточнете какво може да се каже и презаснемете с анонимен, позволен пример."},{"id":"b","label":"Насочваш го да повтори лозунга с повече ентусиазъм."},{"id":"c","label":"Задай наведнъж три въпроса и после избери удобния отговор."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Спрете, уточнете какво може да се каже и презаснемете с анонимен, позволен пример. Въпросът допуска и неудобен отговор, без да подсказва похвала. Действието, резултатът и ограничението са разграничени. Непотвърдено число остава за проверка."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Този въпрос не доказва качество сам по себе си. Следват потвърждение на твърдението и честни кадри на действието, което действително може да се покаже."}}]},{"module":"s02-m06","lesson":"pv06-13","source_hash":"2d55d356fe0548d75252cb647c1d30f8","objective":"Ще снимаш познато действие, без камерата да променя важния работен ред. Ще различаваш позволено повторение за технически кадър от инсценирано доказателство. В края ще имаш кратък монтаж, който запазва последователността и не внушава несъществуващ резултат.","hook":"Пред камера човекът може да промени обичайното действие. Провери дали важната реална стъпка остава видима.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще снимаш познато действие, без камерата да променя важния работен ред. Ще различаваш позволено повторение за технически кадър от инсценирано доказателство. В края ще имаш кратък монтаж, който запазва последователността и не внушава несъществуващ резултат.","deliverable":"Запиши със собствен предмет 30 секунди от безопасен процес и направи 10-секундна версия. Ако участва възрастен познат, той знае какво се записва. Запази действителния ред между действие и резултат.","check":"Проверката или друга важна стъпка не отпада заради позиране. Повторението не се представя за доказателство за неповторимо събитие. Случайни хора и чужди данни не се включват в учебния запис."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Пред камера човекът може да промени обичайното действие. Провери дали важната реална стъпка остава видима."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Инсцениране — подреждане или повторение на действие за кадъра. Автентичност — достоверност на представеното, а не тайно снимане. Причинно-следствен ред — кое действие действително предхожда резултата.\n\nДай време на участника да се върне към познатото действие и снимай истинския процес с ясни правила.\n\nПреди запис обясни коя дейност ще се снима и кой няма да попада в кадър. Не крий камерата като техника за „автентичност“. Избери по-дълъг статичен кадър, остави човека да работи и поддържай малък екип."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Можеш да помолиш за повторение на действие за технически кадър, но не представяй повторението като доказателство за уникално събитие, което не се е случило. Запази последователност от началото до края и истински звук от работата. Ако присъствието на камера променя процедурата или нарушава безопасност, спри и адаптирай кадъра.\n\nГраница на решението: Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Уточни дейността и границите на снимане.\n2. Постави камерата така, че да не пречи на работата.\n3. Запиши цял цикъл на действие и собствен звук.\n4. Провери дали монтажът не внушава несъществуващ резултат."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Майсторка опакова поръчка. Екипът иска тя да се усмихва към камерата при всяка стъпка, но така пропуска контролното теглене.\n\nРешение: Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване.\n\nКакво да провериш: Видеото показва реалната последователност и участниците знаят кога и защо са заснети."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване. Видеото показва реалната последователност и участниците знаят кога и защо са заснети.","label":"Как го поправяш"},"before":{"text":"Режисираш последователност, в която липсва реалната проверка, а после твърдиш, че е заснета.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Запиши със собствен предмет 30 секунди от безопасен процес и направи 10-секундна версия. Ако участва възрастен познат, той знае какво се записва. Запази действителния ред между действие и резултат.\n\nПровери резултата: Проверката или друга важна стъпка не отпада заради позиране. Повторението не се представя за доказателство за неповторимо събитие. Случайни хора и чужди данни не се включват в учебния запис.\n\nПримерна работна бележка: Краткият монтаж запазва подготовката, проверката и резултата в действителния им ред. Мога да повторя безопасно действие за друг технически план, но не го представям като запис на неповторимо събитие.\n\nАко не е изпълнено: Ако монтажът внушава резултат от друг случай, премахни тази връзка. При позиране върни вниманието към реалната безопасна задача, с информиран участник. Не снимай скрито за упражнението."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Усмивка вместо пропуснатата проверка, за да изглежда работата по-уверена."},{"id":"b","label":"Съкратен запис, който запазва важните действия и действителния им ред."},{"id":"c","label":"Кадър от друг резултат, представен като последица от текущото действие."}],"question":"Кой монтаж е честен към процеса?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Съкратен запис, който запазва важните действия и действителния им ред. Проверката или друга важна стъпка не отпада заради позиране. Повторението не се представя за доказателство за неповторимо събитие. Случайни хора и чужди данни не се включват в учебния запис."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Майсторка опакова поръчка. Екипът иска тя да се усмихва към камерата при всяка стъпка, но така пропуска контролното теглене.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Карам майсторката да гледа камерата и оставям контролното теглене извън записа."},{"id":"b","label":"Добавям теглене от друга поръчка, като го представям за текущото."},{"id":"c","label":"Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване.\n\nКакво да провериш: Видеото показва реалната последователност и участниците знаят кога и защо са заснети."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Сложи скрита камера и после искай разрешения."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Запиши със собствен предмет 30 секунди от безопасен процес и направи 10-секундна версия. Ако участва възрастен познат, той знае какво се записва. Запази действителния ред между действие и резултат.","takeaways":["Дай време на участника да се върне към познатото действие и снимай истинския процес с ясни правила.","Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване.","Провери: Видеото показва реалната последователност и участниците знаят кога и защо са заснети."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Запиши цял цикъл на действие и собствен звук."},{"id":"s1","text":"Уточни дейността и границите на снимане."},{"id":"s4","text":"Провери дали монтажът не внушава несъществуващ резултат."},{"id":"s2","text":"Постави камерата така, че да не пречи на работата."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Уточни дейността и границите на снимане. → Постави камерата така, че да не пречи на работата. → Запиши цял цикъл на действие и собствен звук. → Провери дали монтажът не внушава несъществуващ резултат."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: По време на процеса влиза случаен клиент, който не е част от снимките.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Режисираш последователност, в която липсва реалната проверка, а после твърдиш, че е заснета."},{"id":"b","label":"Сложи скрита камера и после искай разрешения."},{"id":"c","label":"Спри или промени кадъра, така че клиентът да не бъде записван/публикуван без подходящо основание."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Спри или промени кадъра, така че клиентът да не бъде записван/публикуван без подходящо основание. Проверката или друга важна стъпка не отпада заради позиране. Повторението не се представя за доказателство за неповторимо събитие. Случайни хора и чужди данни не се включват в учебния запис."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Разпознаваемият обичаен процес може да помогне на разказа. Той се показва с информирани участници и потвърдена употреба; скритият запис не е учебен метод."}}]},{"module":"s02-m06","lesson":"pv06-14","source_hash":"de21d7db2c2aead274de3533e3e4ff1e","objective":"Ще разпознаваш кога запис или публикация с деца изисква спиране и уточняване с отговорната организация. Ще различаваш вътрешен отчет, публичен сайт и платена реклама. Практиката е с условни лица и цели; не е необходимо да снимаш истински деца.","hook":"Училището казва „всички са съгласни“, но няма яснота за реклама, съхранение и конкретните деца в кадър.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще разпознаваш кога запис или публикация с деца изисква спиране и уточняване с отговорната организация. Ще различаваш вътрешен отчет, публичен сайт и платена реклама. Практиката е с условни лица и цели; не е необходимо да снимаш истински деца.","deliverable":"Реши учебния случай: потвърден е само вътрешен отчет, а се иска платена публична реклама. Отбележи новата употреба като непотвърдена и избери версия без разпознаваеми деца, докато организацията изясни условията.","check":"Няма автоматично пренасяне на потвърждението към нова цел. Кадри с неизвестен статус не се публикуват. Изборът не се основава на възрастов праг за онлайн услуги, пренесен механично към снимане."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Училището казва „всички са съгласни“, но няма яснота за реклама, съхранение и конкретните деца в кадър."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Правно основание — основанието за конкретно обработване на лични данни. Обхват — за кои лица, цели и употреби са потвърдени условията. Разпознаваемост — човек може да бъде установен и по други подробности освен лицето.\n\nПреди камерата провери с организацията правното основание, употребата, ограниченията и кой отговаря за всяко дете.\n\nРаботи със списък кой може да се снима и за каква конкретна цел, даден от упълномощения организатор. Не записвай имена и излишни лични данни в кадър. Определи безопасни зони за деца извън камерата."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Отдели вътрешното използване от публичното публикуване. Правното основание за различни вътрешни дейности се определя от организацията и отговорния за данните. Това не дава автоматично право за сайт или платена реклама със същите деца.\n\nВ насоките си за образованието КЗЛД посочва предварително конкретно съгласие за публикуване на ученически снимки и видео, отделено от други документи и с възможност за оттегляне. Изясни конкретните лица, цели, канали, съхранение, достъп до оригиналите и надзор с отговорната организация. Не извеждай право за снимане от възрастов праг за регистрация в онлайн услуга.\n\nГраница на решението: Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Установи отговорен възрастен и правилата на организацията.\n2. Провери кои участници и употреби са разрешени.\n3. Подготви кадри, които не разкриват ненужни данни.\n4. Преди публикуване провери финалната версия и обхвата на разрешенията."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"НПО снима детска работилница. Има разрешение за вътрешен отчет, но по-късно иска публична платена реклама със същите лица.\n\nРешение: Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца.\n\nКакво да провериш: За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца. За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани.","label":"Как го поправяш"},"before":{"text":"Приемаш вътрешното разрешение за достатъчно и изпращаш рекламата без нова проверка.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Реши учебния случай: потвърден е само вътрешен отчет, а се иска платена публична реклама. Отбележи новата употреба като непотвърдена и избери версия без разпознаваеми деца, докато организацията изясни условията.\n\nПровери резултата: Няма автоматично пренасяне на потвърждението към нова цел. Кадри с неизвестен статус не се публикуват. Изборът не се основава на възрастов праг за онлайн услуги, пренесен механично към снимане.\n\nПримерна работна бележка: Учебна карта: вътрешен отчет — потвърден само в този обхват; сайт — непотвърден; платена реклама — непотвърдена. Спирам публичната версия и подготвям безопасна алтернатива без разпознаваеми деца, докато организацията уточни новата употреба.\n\nАко не е изпълнено: Не приемай замъглено лице за автоматична анонимност: глас, име, училище и контекст също могат да разпознават. Не пренасяй правила за регистрация в онлайн услуга към правото да снимаш. Практиката остава с условни лица."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Спирам публикацията и искам проверка на конкретната нова цел и разрешенията."},{"id":"b","label":"Приемам първото потвърждение за достатъчно за всеки бъдещ канал."},{"id":"c","label":"Публикувам с надпис „образователна цел“, без проверка на лицата и употребата."}],"question":"Какво правиш, когато вътрешен детски отчет стане публична реклама?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Спирам публикацията и искам проверка на конкретната нова цел и разрешенията. Няма автоматично пренасяне на потвърждението към нова цел. Кадри с неизвестен статус не се публикуват. Изборът не се основава на възрастов праг за онлайн услуги, пренесен механично към снимане."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"НПО снима детска работилница. Има разрешение за вътрешен отчет, но по-късно иска публична платена реклама със същите лица.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Използвам разрешението за вътрешен отчет и за платената кампания."},{"id":"b","label":"Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца."},{"id":"c","label":"Изрязвам имената, без да проверя останалата разпознаваемост."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца.\n\nКакво да провериш: За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Публикувай със замъглено лице, без да провериш дали и гласът, името или контекстът разпознават детето."},{"id":"c","label":"Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Реши учебния случай: потвърден е само вътрешен отчет, а се иска платена публична реклама. Отбележи новата употреба като непотвърдена и избери версия без разпознаваеми деца, докато организацията изясни условията.","takeaways":["Преди камерата провери с организацията правното основание, употребата, ограниченията и кой отговаря за всяко дете.","Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца.","Провери: За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Подготви кадри, които не разкриват ненужни данни."},{"id":"s1","text":"Установи отговорен възрастен и правилата на организацията."},{"id":"s4","text":"Преди публикуване провери финалната версия и обхвата на разрешенията."},{"id":"s2","text":"Провери кои участници и употреби са разрешени."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Установи отговорен възрастен и правилата на организацията. → Провери кои участници и употреби са разрешени. → Подготви кадри, които не разкриват ненужни данни. → Преди публикуване провери финалната версия и обхвата на разрешенията."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: В залата влиза дете, за което няма потвърдено разрешение за запис.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Публикувай със замъглено лице, без да провериш дали и гласът, името или контекстът разпознават детето."},{"id":"b","label":"Насочи камерата към работа без разпознаваемо лице или изчакай организацията да изясни условията."},{"id":"c","label":"Приемаш вътрешното разрешение за достатъчно и изпращаш рекламата без нова проверка."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Насочи камерата към работа без разпознаваемо лице или изчакай организацията да изясни условията. Няма автоматично пренасяне на потвърждението към нова цел. Кадри с неизвестен статус не се публикуват. Изборът не се основава на възрастов праг за онлайн услуги, пренесен механично към снимане."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"За публикуване на ученически снимки и видео КЗЛД посочва предварително конкретно и оттегляемо съгласие. Това не се смесва с правилата за други вътрешни обработки. Реалният случай се потвърждава от отговорната организация."}}]},{"module":"s02-m06","lesson":"pv06-15","source_hash":"897cefcb3d5b5390a2281a14ff65021d","objective":"Ще разделяш достъпа до локация, участието на хора, чуждите материали и проверката на фирмените факти. Ще пазиш източник и дата към числа и условия. Резултатът е фактически проверен план и файл, в който няма случайно включен клиентски документ.","hook":"Говорителят обещава „гарантиран резултат“, а логото на чужд клиент стои зад него.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще разделяш достъпа до локация, участието на хора, чуждите материали и проверката на фирмените факти. Ще пазиш източник и дата към числа и условия. Резултатът е фактически проверен план и файл, в който няма случайно включен клиентски документ.","deliverable":"В учебен кадър използвай измислен лист с надпис „чужд договор“. Избери прекадриране или премахване на листа. За „над 500 клиента“ изисквай източник и дата или извади числото от текста.","check":"Всеки важен факт има потвърждение. Разрешение за офиса не се приема за разрешение за всеки човек и материал. Чужди данни не остават във финалната версия."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Говорителят обещава „гарантиран резултат“, а логото на чужд клиент стои зад него."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Лист на твърденията — списък на проверимите фрази и източниците им. Одобрение — потвърждение от отговорен човек за определена част. Поверителен материал — информация, която не трябва да излиза в този запис.\n\nРаздели разрешение за място, участие на хора, използване на материали и проверка на публичните твърдения.\n\nЕдна фирма може да разреши снимки в офиса, без това да включва служители, клиентски документи, музика на заден план или чужди брандове. Запиши кой от компанията може да одобри всяка част."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Създай кратък списък с факти, които трябва да се потвърдят: цена, срок, обхват, резултати и условия. Запиши датата и източника на потвърждение, както и какво остава неизвестно. Преди снимачен ден прибери видимите чужди данни и набележи къде в кадъра се появяват чужди знаци. При смяна на сценария поискайте ново одобрение за новото твърдение, не го „поправяйте“ с дребен надпис.\n\nГраница на решението: Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Запиши всички планирани публични твърдения.\n2. Определи собственик на фактите и разрешенията.\n3. Провери локацията за чужди хора, знаци и документи.\n4. Сними само потвърденото и изпрати фактическия монтаж за одобрение."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Фирма за услуги казва, че работи с „над 500 клиента“, но никой не знае към коя дата е числото. На стена се вижда договор на друг клиент.\n\nРешение: Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла.\n\nКакво да провериш: Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла. Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни.","label":"Как го поправяш"},"before":{"text":"Оставяш числото и документа в кадър, защото ще излезе бързо в социалните мрежи.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"В учебен кадър използвай измислен лист с надпис „чужд договор“. Избери прекадриране или премахване на листа. За „над 500 клиента“ изисквай източник и дата или извади числото от текста.\n\nПровери резултата: Всеки важен факт има потвърждение. Разрешение за офиса не се приема за разрешение за всеки човек и материал. Чужди данни не остават във финалната версия.\n\nПримерна работна бележка: Офисът е разрешен в уговорения обхват, но договорът във фона е чужд: махам учебния лист или прекадрирам. Числото „над 500 клиента“ няма източник и дата: връщам го за потвърждение или го изваждам от текста.\n\nАко не е изпълнено: Провери отделно място, хора, материали и факти. Подписът на управител не урежда автоматично всички тези въпроси. Ако промениш кадъра или репликата след одобрение, провери новата финална версия."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Автоматични права върху служители, договори и фонова музика."},{"id":"b","label":"Точност на всяко ново число, добавено от маркетинга."},{"id":"c","label":"Само разрешения обхват за мястото; останалите лица, материали и факти се проверяват отделно."}],"question":"Какво потвърждава разрешението да снимаш в офис?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Само разрешения обхват за мястото; останалите лица, материали и факти се проверяват отделно. Всеки важен факт има потвърждение. Разрешение за офиса не се приема за разрешение за всеки човек и материал. Чужди данни не остават във финалната версия."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Фирма за услуги казва, че работи с „над 500 клиента“, но никой не знае към коя дата е числото. На стена се вижда договор на друг клиент.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла."},{"id":"b","label":"Оставям числото без дата, защото то е произнесено от служител."},{"id":"c","label":"Показвам договора на стената, защото ръководството е разрешило снимки в офиса."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла.\n\nКакво да провериш: Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Сложи дребен надпис „резултатите може да варират“ и остави неподкрепения абсолютен текст."},{"id":"b","label":"Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"В учебен кадър използвай измислен лист с надпис „чужд договор“. Избери прекадриране или премахване на листа. За „над 500 клиента“ изисквай източник и дата или извади числото от текста.","takeaways":["Раздели разрешение за място, участие на хора, използване на материали и проверка на публичните твърдения.","Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла.","Провери: Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Провери локацията за чужди хора, знаци и документи."},{"id":"s1","text":"Запиши всички планирани публични твърдения."},{"id":"s4","text":"Сними само потвърденото и изпрати фактическия монтаж за одобрение."},{"id":"s2","text":"Определи собственик на фактите и разрешенията."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Запиши всички планирани публични твърдения. → Определи собственик на фактите и разрешенията. → Провери локацията за чужди хора, знаци и документи. → Сними само потвърденото и изпрати фактическия монтаж за одобрение."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: След снимките маркетингът добавя ново твърдение за най-ниска цена.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Върни го за доказателство и одобрение с дата; без него не го поставяй в публичния файл."},{"id":"b","label":"Оставяш числото и документа в кадър, защото ще излезе бързо в социалните мрежи."},{"id":"c","label":"Сложи дребен надпис „резултатите може да варират“ и остави неподкрепения абсолютен текст."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Върни го за доказателство и одобрение с дата; без него не го поставяй в публичния файл. Всеки важен факт има потвърждение. Разрешение за офиса не се приема за разрешение за всеки човек и материал. Чужди данни не остават във финалната версия."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Според EDPB служителите по принцип може да не са в положение да дадат свободно съгласие на работодателя. Не решаваме всички фирмени случаи с подпис от управител; конкретната употреба се проверява с отговорния за нея."}}]},{"module":"s02-m06","lesson":"pv06-16","source_hash":"ac976cf1c74a6ee0faf63b6897dd9e8b","objective":"Ще помагаш на фирмен говорител да обясни конкретно действие и условие със собствени думи. Ще заменяш общата похвала с полезен отговор за зрителя. В края ще имаш кратка реплика, която казва какво човекът може действително да очаква.","hook":"Управителят знае всичко, но в кадър казва само „качество, професионализъм, отношение“.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще помагаш на фирмен говорител да обясни конкретно действие и условие със собствени думи. Ще заменяш общата похвала с полезен отговор за зрителя. В края ще имаш кратка реплика, която казва какво човекът може действително да очаква.","deliverable":"Реши случая с късно пристигане в хотел. Избери реплика с потвърдени час, начин за контакт и условия. Ако телефонът не е потвърден, остави го извън файла и върни въпроса за уточняване.","check":"Зрителят знае следващата стъпка. Няма непроверено „винаги“. Говорителят не е заставен да играе роля, която прикрива непотвърдена процедура."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Управителят знае всичко, но в кадър казва само „качество, професионализъм, отношение“."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Зрителска нужда — какво човекът трябва да разбере или направи. Условие — границата, при която обещаното действие е изпълнимо. Самостоятелна реплика — разбира се и без целия предишен разговор.\n\nПопитай как фирмата работи в конкретен ден, после превърни отговора в една полезна за зрителя мисъл.\n\nПодготви до три цели: какъв проблем решава услугата, как протича работата и какво клиентът може да очаква. Поискай реален пример, в който самият говорител е взел решение."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Проверявай дали фирмените фрази са истина за целия клиентски процес. Ако човекът започне да чете страница с суперлативи, спри и го попитай как би обяснил услугата на свой познат. Запиши кратки самостоятелни отговори и чисти начални и крайни изречения за монтаж. Когато чужд отдел трябва да одобри условия, използвай само потвърдените части.\n\nГраница на решението: Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Избери една конкретна зрителска нужда.\n2. Вземи реален случай и проверими действия.\n3. Запиши кратки отговори със собствени думи.\n4. Свери фирмените факти и изгледай целия монтаж с говорителя."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Управител на малък хотел трябва да обясни какво става при късно пристигане. Сценарият казва само „винаги сме на разположение“.\n\nРешение: Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа.\n\nКакво да провериш: Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа. Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени.","label":"Как го поправяш"},"before":{"text":"Оставяш абстрактното обещание, защото звучи добре на камера.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Реши случая с късно пристигане в хотел. Избери реплика с потвърдени час, начин за контакт и условия. Ако телефонът не е потвърден, остави го извън файла и върни въпроса за уточняване.\n\nПровери резултата: Зрителят знае следващата стъпка. Няма непроверено „винаги“. Говорителят не е заставен да играе роля, която прикрива непотвърдена процедура.\n\nПримерна работна бележка: Учебни потвърдени условия: при пристигане след 22:00 гостът изпраща съобщение през потвърдения канал до 18:00 в деня на настаняване. Репликата обяснява тези две стъпки; не измислям денонощен телефон. Часовете са само за този условен казус.\n\nАко не е изпълнено: При липсващ контакт не попълвай случаен номер. Уточни процедурата с отговорния или остави репликата извън публикацията. Свободният тон не оправдава непроверено „винаги“."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Общото „винаги сме на разположение“, без проверено условие."},{"id":"b","label":"Точна процедура с потвърдени часове и начин за контакт."},{"id":"c","label":"Непотвърден нощен номер, за да има завършен призив."}],"question":"Коя реплика е полезна за късно пристигащ гост?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Точна процедура с потвърдени часове и начин за контакт. Зрителят знае следващата стъпка. Няма непроверено „винаги“. Говорителят не е заставен да играе роля, която прикрива непотвърдена процедура."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Управител на малък хотел трябва да обясни какво става при късно пристигане. Сценарият казва само „винаги сме на разположение“.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Запазвам лозунга и не питам кой действително приема госта."},{"id":"b","label":"Добавям примерен телефон в графиката, преди екипът да го потвърди."},{"id":"c","label":"Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа.\n\nКакво да провериш: Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес."},{"id":"b","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"c","label":"Подложи отговора на тежък ефект и бърз монтаж, за да не личи липсата на конкретика."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Реши случая с късно пристигане в хотел. Избери реплика с потвърдени час, начин за контакт и условия. Ако телефонът не е потвърден, остави го извън файла и върни въпроса за уточняване.","takeaways":["Попитай как фирмата работи в конкретен ден, после превърни отговора в една полезна за зрителя мисъл.","Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа.","Провери: Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Запиши кратки отговори със собствени думи."},{"id":"s1","text":"Избери една конкретна зрителска нужда."},{"id":"s4","text":"Свери фирмените факти и изгледай целия монтаж с говорителя."},{"id":"s2","text":"Вземи реален случай и проверими действия."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Избери една конкретна зрителска нужда. → Вземи реален случай и проверими действия. → Запиши кратки отговори със собствени думи. → Свери фирмените факти и изгледай целия монтаж с говорителя."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Няма потвърден нощен телефон за връзка.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Оставяш абстрактното обещание, защото звучи добре на камера."},{"id":"b","label":"Подложи отговора на тежък ефект и бърз монтаж, за да не личи липсата на конкретика."},{"id":"c","label":"Не го обещавай; остави потвърдените канали и поискайте актуална информация преди финала."}]},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Не го обещавай; остави потвърдените канали и поискайте актуална информация преди финала. Зрителят знае следващата стъпка. Няма непроверено „винаги“. Говорителят не е заставен да играе роля, която прикрива непотвърдена процедура."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Конкретното обяснение може да намали неяснотата на процедурата. Не обещаваме предварително ефект върху резервациите или доверието."}}]},{"module":"s02-m06","lesson":"pv06-17","source_hash":"31d0e197b89f72bb9d5fe1e1e4defbf1","objective":"Ще снимаш себе си с ясна позиция и кратки проверки на действителния запис. Ще следиш фокус, важен предмет, звук и ограничения на устройството. Резултатът е няколко използваеми сегмента, без да откриваш грешката след цял снимачен ден.","hook":"Говориш убедително 20 минути, после откриваш, че фокусът е на рафта зад теб.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще снимаш себе си с ясна позиция и кратки проверки на действителния запис. Ще следиш фокус, важен предмет, звук и ограничения на устройството. Резултатът е няколко използваеми сегмента, без да откриваш грешката след цял снимачен ден.","deliverable":"С наличен телефон запиши три сегмента по 10–15 секунди. Преди третия премести стола и направи нова проба. Проверявай файла, а не само положението на камерата.","check":"Очите или важният предмет са отчетливи; ръцете и действието не са отрязани; речта се чува. При промяна на светлина или позиция има нов проверен сегмент."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Говориш убедително 20 минути, после откриваш, че фокусът е на рафта зад теб."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Маркировка — ориентир за проверената позиция. Фокус — кои части са отчетливо записани. Сегмент — кратка самостоятелна част от записа. Превю — предварителен изглед, който не заменя готовия файл.\n\nПри самозаснемане замести липсващия оператор с маркировки, контролен кадър и кратки проверки.\n\nМаркирай къде стоиш, заключи кадъра и провери фокус на истинското място на очите. Избери близък микрофон и прослушай проба. Използвай телефон или монитор за контрол, ако имаш, но не оставяй превюто да спира запис или изтощава батерия."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Раздели текста на кратки мисли и оставяй секунди тишина преди и след всяка. След промяна на позиция, облекло или светлина повтори теста; грешка в един дубъл е по-евтина от грешка в цял снимачен ден. Ако устройството има ограничение на запис или време, провери го предварително на истинската продължителност.\n\nГраница на решението: Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Маркирай позиция, кадър и разстояние до микрофона.\n2. Запиши проба с движение и най-силната реплика.\n3. Възпроизведи файла и провери очи, глас и таймер.\n4. Снимай на къси сегменти и проверявай след всяка смяна."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Предприемач снима курс сам. Премества стола след първата почивка и продължава; всички следващи клипове имат отрязана ръка.\n\nРешение: Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл.\n\nКакво да провериш: Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл. Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент.","label":"Как го поправяш"},"before":{"text":"Разчиташ, че широкият кадър ще се поправи с автоматично прекадриране.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"С наличен телефон запиши три сегмента по 10–15 секунди. Преди третия премести стола и направи нова проба. Проверявай файла, а не само положението на камерата.\n\nПровери резултата: Очите или важният предмет са отчетливи; ръцете и действието не са отрязани; речта се чува. При промяна на светлина или позиция има нов проверен сегмент.\n\nПримерна работна бележка: Първите два сегмента пазят очи, ръце и звук. След преместването столът оставя предмета извън кадър: новата проба го показва, поправям позицията и записвам третия сегмент отново.\n\nАко не е изпълнено: При промяна на светлина, дистанция или движение не разчитай само на същите настройки. Отвори файла и провери важния момент. Ако автофокусът търси, провери друга безопасна позиция или наличното заключване."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Нов кратък запис и възпроизвеждане на истинската позиция."},{"id":"b","label":"Същите настройки без запис, защото камерата не е местена."},{"id":"c","label":"Оценка само по индикатора, че устройството записва."}],"question":"Как проверяваш самозаснемането след преместване?"},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Нов кратък запис и възпроизвеждане на истинската позиция. Очите или важният предмет са отчетливи; ръцете и действието не са отрязани; речта се чува. При промяна на светлина или позиция има нов проверен сегмент."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Предприемач снима курс сам. Премества стола след първата почивка и продължава; всички следващи клипове имат отрязана ръка.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Продължавам след преместването, без да проверя отрязаната ръка."},{"id":"b","label":"Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл."},{"id":"c","label":"Гледам единствено превюто, без да прослушам файла."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл.\n\nКакво да провериш: Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Тази настройка работи еднакво добре при всички места и хора."},{"id":"b","label":"Провери само миниатюрата на екрана и изтрий тестовия файл без прослушване."},{"id":"c","label":"Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"С наличен телефон запиши три сегмента по 10–15 секунди. Преди третия премести стола и направи нова проба. Проверявай файла, а не само положението на камерата.","takeaways":["При самозаснемане замести липсващия оператор с маркировки, контролен кадър и кратки проверки.","Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл.","Провери: Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Възпроизведи файла и провери очи, глас и таймер."},{"id":"s1","text":"Маркирай позиция, кадър и разстояние до микрофона."},{"id":"s4","text":"Снимай на къси сегменти и проверявай след всяка смяна."},{"id":"s2","text":"Запиши проба с движение и най-силната реплика."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Маркирай позиция, кадър и разстояние до микрофона. → Запиши проба с движение и най-силната реплика. → Възпроизведи файла и провери очи, глас и таймер. → Снимай на къси сегменти и проверявай след всяка смяна."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: Слънцето изчезва след първия сегмент.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Провери само миниатюрата на екрана и изтрий тестовия файл без прослушване."},{"id":"b","label":"Преоцени светлината, направи нов тест за експонация и баланс и запази контролен кадър за съвпадение."},{"id":"c","label":"Разчиташ, че широкият кадър ще се поправи с автоматично прекадриране."}]},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Преоцени светлината, направи нов тест за експонация и баланс и запази контролен кадър за съвпадение. Очите или важният предмет са отчетливи; ръцете и действието не са отрязани; речта се чува. При промяна на светлина или позиция има нов проверен сегмент."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Автоматиката може да е подходяща за първа проба, ако е проверена при истинското движение. Липсата на ръчни настройки не се прикрива като пълен контрол."}}]},{"module":"s02-m06","lesson":"pv06-18","source_hash":"efa4f47fbf013520da71c614c9e9e5ad","objective":"Ще събереш подготовката, въпросите, светлината, звука и монтажа в кратко интервю. Ще работиш с доброволен пълнолетен участник и безопасна тема, без да е нужен клиент или преподавател. Резултатът е 60–90 секунди с една ясна мисъл, верни факти и проверен реален файл.","hook":"Финалният отговор е интересен, но записът не е готов за употреба, ако звукът, фактите или уговорените права още не са проверени.","blocks":[{"key":"objective","type":"objective","position":0,"required":true,"points":1,"title":"Какво ще можеш след урока","content":{"body":"Ще събереш подготовката, въпросите, светлината, звука и монтажа в кратко интервю. Ще работиш с доброволен пълнолетен участник и безопасна тема, без да е нужен клиент или преподавател. Резултатът е 60–90 секунди с една ясна мисъл, верни факти и проверен реален файл.","deliverable":"Подготви три кратки въпроса за безопасно познато действие. С доброволен възрастен участник запиши проба и разговор; добави честни кадри на същото действие. Изнеси 60–90 секунди и провери факт, звук, синхрон и видим фон.","check":"Основната мисъл е разбираема, кадрите не подменят случая и непотвърдени числа са махнати. Записът е с ясна употреба и запазени оригинали. Без участник можеш да подготвиш плана, но още не си завършил реалното интервю."}},{"key":"hook","type":"hook","position":1,"required":true,"points":1,"title":"Ситуация от работата","content":{"body":"Финалният отговор е интересен, но записът не е готов за употреба, ако звукът, фактите или уговорените права още не са проверени."}},{"key":"core","type":"rich_text","position":2,"required":true,"points":2,"title":"Основното обяснение","content":{"body":"Фактическа проверка — сверяване на казаното с потвърден източник. Финална версия — конкретният файл, избран за употреба. Самооценка — твоя проверка по критерии; не е доказана реакция на независима публика.\n\nРаботи с реален доброволен възрастен участник, разрешено място и проверена употреба на видеото.\n\nПодготви едностраничен план с цел, въпроси и задължителни действия за B-roll. На терен запиши проба, кратък разговор, звук от мястото и действия, които действително илюстрират казаното. Не използвай деца за този учебен проект."}},{"key":"deep_dive","type":"rich_text","position":3,"required":true,"points":2,"title":"На терен","content":{"body":"Монтирай 60–90 секунди с една основна мисъл и конкретен проверен пример. Свери числата, видимите лица и документи, уговорената употреба и музиката, ако има такава. Сравни оригиналния и финалния звук, провери синхрона и отвори изнесения файл на налично реално устройство.\n\nСамопроверката не изисква оценител: можеш да свериш думите с потвърдените факти, да прослушаш файла и да провериш кадрите. Участникът е нужен за истинското интервю, но не е длъжен да оценява работата ти. Независим зрител може да даде допълнителна обратна връзка; такава реакция още не е получена, ако имаш само собствена проверка.\n\nГраница на решението: Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите."}},{"key":"method","type":"rich_text","position":4,"required":true,"points":2,"title":"Работен ред","content":{"body":"1. Осигури участник, цел, права и конкретни въпроси.\n2. Направи проба и заснеми разговор плюс честен B-roll.\n3. Монтирай за смисъл, разбираем глас и верни факти.\n4. Провери експорта, правата и финалния файл на реално устройство."}},{"key":"worked_example","type":"example","position":5,"required":true,"points":2,"title":"Решен случай","content":{"body":"Интервю с пекар разказва как подготвя поръчки. Има жив отговор, но B-roll показва друга поръчка, а цената е казана без дата.\n\nРешение: Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза.\n\nКакво да провериш: По самопроверка основната мисъл и ключовите думи са ясни; фактите и употребата са потвърдени, фонът и синхронът са прегледани. Външната зрителска реакция остава непроверена, ако не е получена."}},{"key":"before_after","type":"before_after","position":6,"required":true,"points":2,"title":"Честа грешка и поправка","content":{"after":{"text":"Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза. По самопроверка основната мисъл и ключовите думи са ясни; фактите и употребата са потвърдени, фонът и синхронът са прегледани. Външната зрителска реакция остава непроверена, ако не е получена.","label":"Как го поправяш"},"before":{"text":"Предаваш проекта като „готов“, защото картината е красива и музиката прикрива аудио грешките.","label":"Как се губи контрол"}}},{"key":"field_diagnostic","type":"rich_text","position":7,"required":true,"points":2,"title":"Твоят опит","content":{"body":"Подготви три кратки въпроса за безопасно познато действие. С доброволен възрастен участник запиши проба и разговор; добави честни кадри на същото действие. Изнеси 60–90 секунди и провери факт, звук, синхрон и видим фон.\n\nПровери резултата: Основната мисъл е разбираема, кадрите не подменят случая и непотвърдени числа са махнати. Записът е с ясна употреба и запазени оригинали. Без участник можеш да подготвиш плана, но още не си завършил реалното интервю.\n\nПримерна работна бележка: Краткият план съдържа цел, три въпроса и уговорената употреба. Финалните 60–90 секунди показват доброволния пълнолетен участник и същото безопасно действие. В бележката отделям проверени факти, технически проверки и неполучена външна реакция.\n\nАко не е изпълнено: При чужд документ спри този експорт, премахни кадъра и отвори новия файл. При неясна цена върни я за потвърждение с дата или я махни. План без участник е подготовка; не е завършено интервю."}},{"key":"knowledge_check","type":"quiz","position":8,"required":true,"points":2,"title":"Провери принципа","content":{"options":[{"id":"a","label":"Само красив монтаж, независимо от чужди документи и неясна цена."},{"id":"b","label":"Самооценка като доказателство за качество при всички бъдещи клиенти."},{"id":"c","label":"План, доброволен участник и реален файл, проверен по отделни фактически и технически критерии."}],"question":"Какво показва завършената учебна задача?"},"evaluation":{"correct":"c"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"План, доброволен участник и реален файл, проверен по отделни фактически и технически критерии. Основната мисъл е разбираема, кадрите не подменят случая и непотвърдени числа са махнати. Записът е с ясна употреба и запазени оригинали. Без участник можеш да подготвиш плана, но още не си завършил реалното интервю."}},{"key":"decision_case","type":"scenario","position":9,"required":true,"points":3,"title":"Реши случая","content":{"prompt":"Интервю с пекар разказва как подготвя поръчки. Има жив отговор, но B-roll показва друга поръчка, а цената е казана без дата.\n\nКой ход предприемаш първо и как ще го провериш?","options":[{"id":"a","label":"Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза."},{"id":"b","label":"Оставям кадър от друга поръчка като доказателство за описвания процес."},{"id":"c","label":"Приемам цената без дата и заглушената реплика, защото картината е добра."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза.\n\nКакво да провериш: По самопроверка основната мисъл и ключовите думи са ясни; фактите и употребата са потвърдени, фонът и синхронът са прегледани. Външната зрителска реакция остава непроверена, ако не е получена."}},{"key":"boundary_check","type":"quiz","position":10,"required":true,"points":2,"title":"Къде е границата","content":{"options":[{"id":"a","label":"Приеми, че публикуването само по себе си доказва качество и налични права."},{"id":"b","label":"Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите."},{"id":"c","label":"Тази настройка работи еднакво добре при всички места и хора."}],"question":"Кое ограничение трябва да провериш, преди да повториш решението на друг терен?"},"evaluation":{"correct":"b"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите."}},{"key":"summary","type":"summary","position":11,"required":true,"points":2,"title":"Запомни за следващия запис","content":{"nextStep":"Подготви три кратки въпроса за безопасно познато действие. С доброволен възрастен участник запиши проба и разговор; добави честни кадри на същото действие. Изнеси 60–90 секунди и провери факт, звук, синхрон и видим фон.","takeaways":["Работи с реален доброволен възрастен участник, разрешено място и проверена употреба на видеото.","Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза.","Провери: По самопроверка основната мисъл и ключовите думи са ясни; фактите и употребата са потвърдени, фонът и синхронът са прегледани. Външната зрителска реакция остава непроверена, ако не е получена."]}},{"key":"sequence_practice","type":"sequence_sort","position":12,"required":false,"points":2,"title":"Подреди действията","content":{"items":[{"id":"s3","text":"Монтирай за смисъл, разбираем глас и верни факти."},{"id":"s1","text":"Осигури участник, цел, права и конкретни въпроси."},{"id":"s4","text":"Провери експорта, правата и финалния файл на реално устройство."},{"id":"s2","text":"Направи проба и заснеми разговор плюс честен B-roll."}],"instruction":"Подреди хода така, че пробата да предхожда окончателното решение. Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите."},"evaluation":{"order":["s1","s2","s3","s4"]},"scoring":{"mode":"exact_order"},"feedback":{"explanation":"Правилният ред: Осигури участник, цел, права и конкретни въпроси. → Направи проба и заснеми разговор плюс честен B-roll. → Монтирай за смисъл, разбираем глас и верни факти. → Провери експорта, правата и финалния файл на реално устройство."}},{"key":"scenario_transfer","type":"scenario","position":13,"required":true,"points":3,"title":"Когато условието се промени","content":{"prompt":"Нов случай: След завършване участникът уточнява, че един кадър съдържа поверителен документ.\n\nКакво ще направиш сега?","options":[{"id":"a","label":"Спри този експорт, премахни кадъра и предай проверена нова версия; актуализирай бележките за одобрение."},{"id":"b","label":"Предаваш проекта като „готов“, защото картината е красива и музиката прикрива аудио грешките."},{"id":"c","label":"Приеми, че публикуването само по себе си доказва качество и налични права."}]},"evaluation":{"correct":"a"},"scoring":{"mode":"single_choice"},"feedback":{"explanation":"Спри този експорт, премахни кадъра и предай проверена нова версия; актуализирай бележките за одобрение. Основната мисъл е разбираема, кадрите не подменят случая и непотвърдени числа са махнати. Записът е с ясна употреба и запазени оригинали. Без участник можеш да подготвиш плана, но още не си завършил реалното интервю."}},{"key":"field_note","type":"rich_text","position":14,"required":false,"points":1,"title":"За следващото снимане","content":{"body":"Не се изисква външен оценител или публично качване. Реакция на непознат зрител би дала допълнителни данни; не я обявяваме за получена, когато имаме само собствена проверка."}}]}]$pv456_payload$::jsonb;
 spec jsonb; block_spec jsonb;
